window.VN_STORY = {
  "version": 1,
  "storyId": "wanxuan_long_story",
  "storyTitle": "坠落凡间的头号食客",
  "exportedAt": "2026-10-01 16:01:03",
  "steps": [
    { "id": "第一幕-降临——名为草莓奶油的意外", "type": "marker", "markerTitle": "第一幕：降临——名为“草莓奶油”的意外", "next": "1-1" },
    { "id": "1-1", "type": "marker", "markerTitle": "寂静的独居生活", "next": "1-1-text-0002" },
    { "id": "1-1-text-0002", "type": "narration", "speaker": "", "content": "独居久了以后，房间会长出一种很奇怪的静。", "expression": "", "background": "day", "stageNote": "【场景】客厅 / 午后 / 晴\n【BG】大客厅，大片落地窗，光线安静地落在地板上\n【BGM】轻柔钢琴，极淡", "next": "1-1-text-0003" },
    { "id": "1-1-text-0003", "type": "narration", "speaker": "", "content": "不是没有声音。", "expression": "", "background": "day", "next": "1-1-text-0004" },
    { "id": "1-1-text-0004", "type": "narration", "speaker": "", "content": "冰箱会低低地运行，空调会送出均匀的风，墙上的钟会一下一下往前走。", "expression": "", "background": "day", "next": "1-1-text-0005" },
    { "id": "1-1-text-0005", "type": "narration", "speaker": "", "content": "但那些声音都太规律了，规律得像一种被允许存在的背景。它们不打扰人，也不陪伴人。", "expression": "", "background": "day", "next": "1-1-text-0006" },
    { "id": "1-1-text-0006", "type": "narration", "speaker": "", "content": "我坐在客厅中央的沙发上，拆开一只纸盒。", "expression": "", "background": "day", "next": "1-1-text-0007" },
    { "id": "1-1-text-0007", "type": "narration", "speaker": "", "content": "里面是我前几天预约的限量草莓蛋糕。", "expression": "", "background": "day", "next": "1-1-text-0008" },
    { "id": "1-1-text-0008", "type": "narration", "speaker": "", "content": "城里很难订，价格也夸张。店家用透明的薄膜罩着，像在保护一件比甜点更接近展品的东西。", "expression": "", "background": "day", "next": "1-1-text-0009" },
    { "id": "1-1-text-0009", "type": "narration", "speaker": "", "content": "我把塑料叉插进奶油时，最先感受到的是阻力。", "expression": "", "background": "day", "next": "1-1-text-0010" },
    { "id": "1-1-text-0010", "type": "narration", "speaker": "", "content": "奶油很轻，却不是空的。", "expression": "", "background": "day", "next": "1-1-text-0011" },
    { "id": "1-1-text-0011", "type": "narration", "speaker": "", "content": "它像初雪一样松软，叉尖陷进去时会微微回弹，留下一道细窄的裂口。", "expression": "", "background": "day", "next": "1-1-text-0012" },
    { "id": "1-1-text-0012", "type": "narration", "speaker": "", "content": "表面的草莓切得很漂亮，边缘还挂着细小的汁水，红得清透，像午后玻璃上短暂停住的一点夕光。", "expression": "", "background": "day", "next": "1-1-text-0013" },
    { "id": "1-1-text-0013", "type": "narration", "speaker": "", "content": "我挖下一口，放进嘴里。", "expression": "", "background": "day", "next": "1-1-text-0014" },
    { "id": "1-1-text-0014", "type": "narration", "speaker": "", "content": "冰凉、柔软，带着刚从冷藏柜里取出的清冽甜气。", "expression": "", "background": "day", "next": "1-1-text-0015" },
    { "id": "1-1-text-0015", "type": "narration", "speaker": "", "content": "奶油先化开，像云一样滑过舌尖，甜味并不猛烈，而是柔和地铺开，后面才跟上草莓的酸。", "expression": "", "background": "day", "next": "1-1-text-0016" },
    { "id": "1-1-text-0016", "type": "narration", "speaker": "", "content": "那一点酸让甜味有了层次，不至于腻，也不至于寡淡。", "expression": "", "background": "day", "next": "1-1-text-0017" },
    { "id": "1-1-text-0017", "type": "narration", "speaker": "", "content": "蛋糕胚很细，咬断时几乎没有声音，只留下一种被湿润奶油浸透后的绵密感。", "expression": "", "background": "day", "next": "1-1-text-0018" },
    { "id": "1-1-text-0018", "type": "narration", "speaker": "", "content": "很好吃。", "expression": "", "background": "day", "next": "1-1-text-0019" },
    { "id": "1-1-text-0019", "type": "narration", "speaker": "", "content": "我又吃了一口。", "expression": "", "background": "day", "next": "1-1-text-0020" },
    { "id": "1-1-text-0020", "type": "narration", "speaker": "", "content": "还是很好吃。", "expression": "", "background": "day", "next": "1-1-text-0021" },
    { "id": "1-1-text-0021", "type": "narration", "speaker": "", "content": "可惜没有人能让我在咽下去的同时抬头说一句——“这个真的不错”。", "expression": "", "background": "day", "next": "1-1-text-0022" },
    { "id": "1-1-text-0022", "type": "narration", "speaker": "", "content": "我看着面前那只精致得有些过头的蛋糕，忽然觉得它像一种被过分郑重对待的孤独。", "expression": "", "background": "day", "next": "1-1-text-0023" },
    { "id": "1-1-text-0023", "type": "dialogue", "speaker": "我", "content": "明明是这么甜的东西，一个人吃，好像也只是多余的热量而已。", "expression": "", "background": "day", "next": "1-1-text-0024" },
    { "id": "1-1-text-0024", "type": "narration", "speaker": "", "content": "客厅里太安静了。", "expression": "", "background": "day", "next": "1-1-text-0025" },
    { "id": "1-1-text-0025", "type": "narration", "speaker": "", "content": "安静到我甚至能听见叉子碰到纸盘边缘时那一声很轻的“嗒”。", "expression": "", "background": "day", "next": "1-1-text-0026" },
    { "id": "1-1-text-0026", "type": "narration", "speaker": "", "content": "我拿起手机，屏幕上没有新消息。", "expression": "", "background": "day", "next": "1-1-text-0027" },
    { "id": "1-1-text-0027", "type": "narration", "speaker": "", "content": "购物软件推来两条促销，外卖平台问我要不要回购上周的烤布蕾。除此之外，没有别的。", "expression": "", "background": "day", "next": "1-1-text-0028" },
    { "id": "1-1-text-0028", "type": "narration", "speaker": "", "content": "有时候我会怀疑，自己是不是已经把生活过成了一个密封得太好的储物盒。", "expression": "", "background": "day", "next": "1-1-text-0029" },
    { "id": "1-1-text-0029", "type": "narration", "speaker": "", "content": "食物放进去不会坏，家具摆进去不会乱，连情绪也像被整整齐齐码放在角落里，不会溢出来，不会惊动谁。", "expression": "", "background": "day", "next": "1-1-text-0030" },
    { "id": "1-1-text-0030", "type": "narration", "speaker": "", "content": "我正准备吃第三口。", "expression": "", "background": "day", "next": "1-1-text-0031" },
    { "id": "1-1-text-0031", "type": "narration", "speaker": "", "content": "——轰！！", "expression": "", "background": "day", "next": "1-1-text-0032" },
    { "id": "1-1-text-0032", "type": "narration", "speaker": "", "content": "一声巨响从阳台方向砸了过来。", "expression": "", "background": "day", "next": "1-1-text-0033" },
    { "id": "1-1-text-0033", "type": "narration", "speaker": "", "content": "落地窗都跟着震了一下。", "expression": "", "background": "day", "next": "1-1-text-0034" },
    { "id": "1-1-text-0034", "type": "narration", "speaker": "", "content": "我手里的叉子差点掉进奶油里，心脏先是猛地一缩，接着才迟钝地开始狂跳。", "expression": "", "background": "day", "next": "1-1-text-0035" },
    { "id": "1-1-text-0035", "type": "dialogue", "speaker": "我", "content": "……什么东西？", "expression": "", "background": "day", "next": "1-1-text-0036" },
    { "id": "1-1-text-0036", "type": "narration", "speaker": "", "content": "我起身时，拖鞋在木地板上磨出一小段急促的声响。", "expression": "", "background": "day", "next": "1-1-text-0037" },
    { "id": "1-1-text-0037", "type": "narration", "speaker": "", "content": "阳光正铺在阳台门前，白得刺眼。隔着玻璃，我先看见一团散开的白色裙摆，再看见一个蜷缩着的人影。", "expression": "", "background": "day", "next": "1-1-text-0038" },
    { "id": "1-1-text-0038", "type": "narration", "speaker": "", "content": "我愣了一秒。", "expression": "", "background": "day", "next": "1-1-text-0039" },
    { "id": "1-1-text-0039", "type": "narration", "speaker": "", "content": "然后彻底愣住。", "expression": "", "background": "day", "next": "1-2" },
    { "id": "1-2", "type": "marker", "markerTitle": "天使的着陆", "next": "1-2-text-0041" },
    { "id": "1-2-text-0041", "type": "narration", "speaker": "", "content": "她坐在阳台地上，像是刚从很高的地方摔下来。", "expression": "A", "background": "day", "stageNote": "【场景】阳台 / 午后\n【立绘】皖萱 [表情A：圣洁]", "next": "1-2-text-0042" },
    { "id": "1-2-text-0042", "type": "narration", "speaker": "", "content": "不，准确地说，她看上去根本不该出现在这里。", "expression": "", "background": "day", "next": "1-2-text-0043" },
    { "id": "1-2-text-0043", "type": "narration", "speaker": "", "content": "白色长裙的布料薄得像云，边缘沾着一点灰。长发柔软地散开，发梢被光照得发亮。", "expression": "", "background": "day", "next": "1-2-text-0044" },
    { "id": "1-2-text-0044", "type": "narration", "speaker": "", "content": "她背后有一对半透明的羽翼——不是电影里那种夸张而耀眼的样子，更像晨雾凝成的形状，薄而轻，稍微一动就像会散掉。", "expression": "", "background": "day", "next": "1-2-text-0045" },
    { "id": "1-2-text-0045", "type": "narration", "speaker": "", "content": "最荒唐的是，她头顶真的有一圈淡淡的光。", "expression": "", "background": "day", "next": "1-2-text-0046" },
    { "id": "1-2-text-0046", "type": "narration", "speaker": "", "content": "很淡，像金色的呼吸。", "expression": "", "background": "day", "next": "1-2-text-0047" },
    { "id": "1-2-text-0047", "type": "narration", "speaker": "", "content": "她抬起头看我。", "expression": "", "background": "day", "next": "1-2-text-0048" },
    { "id": "1-2-text-0048", "type": "narration", "speaker": "", "content": "眼睛很亮，不是凌厉的亮，而是那种被清水洗过一样、近乎无辜的亮。", "expression": "", "background": "day", "next": "1-2-text-0049" },
    { "id": "1-2-text-0049", "type": "dialogue", "speaker": "皖萱", "content": "打扰了。", "expression": "", "background": "day", "next": "1-2-text-0050" },
    { "id": "1-2-text-0050", "type": "narration", "speaker": "", "content": "她说得很认真，像敲错门后还保持礼貌的陌生人。", "expression": "", "background": "day", "next": "1-2-text-0051" },
    { "id": "1-2-text-0051", "type": "dialogue", "speaker": "我", "content": "……你是谁？", "expression": "", "background": "day", "next": "1-2-text-0052" },
    { "id": "1-2-text-0052", "type": "dialogue", "speaker": "皖萱", "content": "我是来自天界的实习天使，编号八九六四。此次降临人间，是为了调查“人类幸福的来源”。", "expression": "", "background": "day", "next": "1-2-text-0053" },
    { "id": "1-2-text-0053", "type": "narration", "speaker": "", "content": "她一板一眼地说完，微微坐直，神情郑重得像在宣读某种任务书。", "expression": "", "background": "day", "next": "1-2-text-0054" },
    { "id": "1-2-text-0054", "type": "narration", "speaker": "", "content": "我盯着她头顶那圈光，脑子里有很多种怀疑在打架，最后只剩下一句最朴素的——", "expression": "", "background": "day", "next": "1-2-text-0055" },
    { "id": "1-2-text-0055", "type": "dialogue", "speaker": "我", "content": "你是……在拍节目吗？", "expression": "", "background": "day", "next": "1-2-text-0056" },
    { "id": "1-2-text-0056", "type": "narration", "speaker": "", "content": "她眨了眨眼。", "expression": "", "background": "day", "next": "1-2-text-0057" },
    { "id": "1-2-text-0057", "type": "dialogue", "speaker": "皖萱", "content": "不是。", "expression": "", "background": "day", "next": "1-2-text-0058" },
    { "id": "1-2-text-0058", "type": "dialogue", "speaker": "我", "content": "那是 cosplay？", "expression": "", "background": "day", "next": "1-2-text-0059" },
    { "id": "1-2-text-0059", "type": "dialogue", "speaker": "皖萱", "content": "不是。", "expression": "", "background": "day", "next": "1-2-text-0060" },
    { "id": "1-2-text-0060", "type": "dialogue", "speaker": "我", "content": "……那你是怎么进我家阳台的？", "expression": "", "background": "day", "next": "1-2-text-0061" },
    { "id": "1-2-text-0061", "type": "narration", "speaker": "", "content": "她沉默了两秒，视线有一点心虚地飘开。", "expression": "", "background": "day", "next": "1-2-text-0062" },
    { "id": "1-2-text-0062", "type": "dialogue", "speaker": "皖萱", "content": "理论上，是“优雅降临”。", "expression": "", "background": "day", "next": "1-2-text-0063" },
    { "id": "1-2-text-0063", "type": "dialogue", "speaker": "我", "content": "理论上？", "expression": "", "background": "day", "next": "1-2-text-0064" },
    { "id": "1-2-text-0064", "type": "dialogue", "speaker": "皖萱", "content": "实际操作出现了一点偏差。", "expression": "", "background": "day", "next": "1-2-text-0065" },
    { "id": "1-2-text-0065", "type": "narration", "speaker": "", "content": "我看着阳台角落那盆被砸倒的绿植，以及她裙摆边蹭上的灰，觉得这“一点偏差”应该足以写事故报告。", "expression": "", "background": "day", "next": "1-2-text-0066" },
    { "id": "1-2-text-0066", "type": "narration", "speaker": "", "content": "我还想再问，下一秒，她的肚子突然发出一声极其清晰、极其响亮的——", "expression": "", "background": "day", "next": "1-2-text-0067" },
    { "id": "1-2-text-0067", "type": "narration", "speaker": "", "content": "“咕——”", "expression": "", "background": "day", "next": "1-2-text-0068" },
    { "id": "1-2-text-0068", "type": "narration", "speaker": "", "content": "空气静止了。", "expression": "", "background": "day", "next": "1-2-text-0069" },
    { "id": "1-2-text-0069", "type": "narration", "speaker": "", "content": "她僵住。", "expression": "", "background": "day", "next": "1-2-text-0070" },
    { "id": "1-2-text-0070", "type": "narration", "speaker": "", "content": "我也僵住。", "expression": "", "background": "day", "next": "1-2-text-0071" },
    { "id": "1-2-text-0071", "type": "narration", "speaker": "", "content": "有那么一瞬间，连窗外的风都像识趣地停了。", "expression": "", "background": "day", "next": "1-2-text-0072" },
    { "id": "1-2-text-0072", "type": "narration", "speaker": "", "content": "她慢慢低下头，耳尖一点一点红起来。", "expression": "", "background": "day", "next": "1-2-text-0073" },
    { "id": "1-2-text-0073", "type": "dialogue", "speaker": "皖萱", "content": "……", "expression": "", "background": "day", "next": "1-2-text-0074" },
    { "id": "1-2-text-0074", "type": "dialogue", "speaker": "我", "content": "……", "expression": "", "background": "day", "next": "1-2-text-0075" },
    { "id": "1-2-text-0075", "type": "dialogue", "speaker": "皖萱", "content": "调查工作消耗比较大。", "expression": "", "background": "day", "next": "1-2-text-0076" },
    { "id": "1-2-text-0076", "type": "dialogue", "speaker": "我", "content": "原来天使也会饿？", "expression": "", "background": "day", "next": "1-2-text-0077" },
    { "id": "1-2-text-0077", "type": "dialogue", "speaker": "皖萱", "content": "严格来说，天使对“精神性满足”的需求更高。但我目前还处在实习阶段，系统兼容性没有完全调整好，所以——", "expression": "", "background": "day", "next": "1-2-text-0078" },
    { "id": "1-2-text-0078", "type": "narration", "speaker": "", "content": "她停住，目光忽然越过我，落在客厅茶几上的蛋糕上。", "expression": "", "background": "day", "next": "1-2-text-0079" },
    { "id": "1-2-text-0079", "type": "narration", "speaker": "", "content": "那目光几乎是发亮的。", "expression": "", "background": "day", "next": "1-2-text-0080" },
    { "id": "1-2-text-0080", "type": "narration", "speaker": "", "content": "像一只在雪地里走了很久的小动物，终于看见一盏温热的灯。", "expression": "", "background": "day", "next": "1-2-text-0081" },
    { "id": "1-2-text-0081", "type": "narration", "speaker": "", "content": "我顺着她的视线回头，看见那块被我吃了两口的草莓蛋糕安静地放在桌面上，奶油边缘还留着叉痕。", "expression": "", "background": "day", "next": "1-2-text-0082" },
    { "id": "1-2-text-0082", "type": "narration", "speaker": "", "content": "她的喉咙很轻地动了一下。", "expression": "", "background": "day", "next": "1-2-text-0083" },
    { "id": "1-2-text-0083", "type": "dialogue", "speaker": "皖萱", "content": "……那个，是人类的幸福样本吗？", "expression": "", "background": "day", "next": "1-2-text-0084" },
    { "id": "1-2-text-0084", "type": "narration", "speaker": "", "content": "我没忍住，笑了一下。", "expression": "", "background": "day", "next": "1-2-text-0085" },
    { "id": "1-2-text-0085", "type": "narration", "speaker": "", "content": "刚才那点警惕，被她这样一看，忽然就散了很多。", "expression": "", "background": "day", "next": "1-2-text-0086" },
    { "id": "1-2-text-0086", "type": "dialogue", "speaker": "我", "content": "大概算吧。", "expression": "", "background": "day", "next": "1-2-text-0087" },
    { "id": "1-2-text-0087", "type": "dialogue", "speaker": "皖萱", "content": "我可以近距离观察吗？", "expression": "", "background": "day", "next": "1-2-text-0088" },
    { "id": "1-2-text-0088", "type": "dialogue", "speaker": "我", "content": "如果我说不行呢？", "expression": "", "background": "day", "next": "1-2-text-0089" },
    { "id": "1-2-text-0089", "type": "narration", "speaker": "", "content": "她很认真地想了想。", "expression": "", "background": "day", "next": "1-2-text-0090" },
    { "id": "1-2-text-0090", "type": "dialogue", "speaker": "皖萱", "content": "那我会礼貌地表示遗憾。然后继续饿着。", "expression": "", "background": "day", "next": "1-2-text-0091" },
    { "id": "1-2-text-0091", "type": "narration", "speaker": "", "content": "她说得太诚实，以至于像一种笨拙的坦白。", "expression": "", "background": "day", "next": "1-2-text-0092" },
    { "id": "1-2-text-0092", "type": "narration", "speaker": "", "content": "我把蛋糕端起来，走到阳台门边，递给她。", "expression": "", "background": "day", "next": "1-2-text-0093" },
    { "id": "1-2-text-0093", "type": "dialogue", "speaker": "我", "content": "先起来吧。观察样本之前，至少别坐在我家地上。", "expression": "", "background": "day", "next": "1-2-text-0094" },
    { "id": "1-2-text-0094", "type": "narration", "speaker": "", "content": "她接过去的时候，动作比想象中轻，小心得像在接一片会融化的雪。", "expression": "", "background": "day", "next": "1-2-text-0095" },
    { "id": "1-2-text-0095", "type": "narration", "speaker": "", "content": "然后，她低头咬了一口。", "expression": "", "background": "day", "next": "1-2-text-0096" },
    { "id": "1-2-text-0096", "type": "narration", "speaker": "", "content": "那一瞬间，我知道“表情发亮”不是夸张修辞。", "expression": "", "background": "day", "next": "1-2-text-0097" },
    { "id": "1-2-text-0097", "type": "narration", "speaker": "", "content": "她睫毛轻轻一颤，眼睛猛地睁大，像有某种极柔和又极盛大的光从眼底一下子漫开。", "expression": "", "background": "day", "next": "1-2-text-0098" },
    { "id": "1-2-text-0098", "type": "narration", "speaker": "", "content": "她含着那口奶油，脸颊微微鼓起，整个人都安静了，像是全部注意力都被舌尖那一点甜彻底夺走。", "expression": "", "background": "day", "next": "1-2-text-0099" },
    { "id": "1-2-text-0099", "type": "narration", "speaker": "", "content": "她又很慢地咽下去。", "expression": "", "background": "day", "next": "1-2-text-0100" },
    { "id": "1-2-text-0100", "type": "narration", "speaker": "", "content": "窗外的阳光照在她侧脸上，连那点奶油的冷白都显得柔软。", "expression": "", "background": "day", "next": "1-2-text-0101" },
    { "id": "1-2-text-0101", "type": "dialogue", "speaker": "皖萱", "content": "……好厉害。", "expression": "", "background": "day", "next": "1-2-text-0102" },
    { "id": "1-2-text-0102", "type": "dialogue", "speaker": "我", "content": "只是蛋糕而已。", "expression": "", "background": "day", "next": "1-2-text-0103" },
    { "id": "1-2-text-0103", "type": "dialogue", "speaker": "皖萱", "content": "不是“只是”。", "expression": "", "background": "day", "next": "1-2-text-0104" },
    { "id": "1-2-text-0104", "type": "narration", "speaker": "", "content": "她抱着纸盘，声音很轻。", "expression": "", "background": "day", "next": "1-2-text-0105" },
    { "id": "1-2-text-0105", "type": "dialogue", "speaker": "皖萱", "content": "它先是软的，像云。然后草莓的味道会在后面追上来，酸一点点，刚好把甜托住。", "expression": "", "background": "day", "next": "1-2-text-0106" },
    { "id": "1-2-text-0106", "type": "narration", "speaker": "", "content": "奶油明明很凉，可是吃下去的时候，胸口却会慢慢热起来。", "expression": "", "background": "day", "next": "1-2-text-0107" },
    { "id": "1-2-text-0107", "type": "narration", "speaker": "", "content": "这就是……人类说的“好吃得想叹气”吗？", "expression": "", "background": "day", "next": "1-2-text-0108" },
    { "id": "1-2-text-0108", "type": "narration", "speaker": "", "content": "我怔了一下。", "expression": "", "background": "day", "next": "1-2-text-0109" },
    { "id": "1-2-text-0109", "type": "narration", "speaker": "", "content": "同样一块蛋糕，我刚才只吃出了价格、手艺和新鲜度。", "expression": "", "background": "day", "next": "1-2-text-0110" },
    { "id": "1-2-text-0110", "type": "narration", "speaker": "", "content": "可从她嘴里说出来，它忽然像第一次真正有了味道。", "expression": "", "background": "day", "next": "1-3" },
    { "id": "1-3", "type": "marker", "markerTitle": "“观察人类”的合理借宿", "next": "1-3-text-0112" },
    { "id": "1-3-text-0112", "type": "narration", "speaker": "", "content": "五分钟后，事情朝着一个非常荒唐、却又意外顺理成章的方向发展了。", "expression": "", "background": "day", "stageNote": "【场景】客厅 / 午后延续", "next": "1-3-text-0113" },
    { "id": "1-3-text-0113", "type": "narration", "speaker": "", "content": "她坐在我家沙发上，双手规规矩矩放在膝盖上，刚才那块蛋糕已经被吃得只剩最后一点奶油痕迹。", "expression": "", "background": "day", "next": "1-3-text-0114" },
    { "id": "1-3-text-0114", "type": "narration", "speaker": "", "content": "她的表情重新恢复成一本正经，只是眼神明显比刚出现时柔和了许多。", "expression": "", "background": "day", "next": "1-3-text-0115" },
    { "id": "1-3-text-0115", "type": "dialogue", "speaker": "皖萱", "content": "经过初步调查，我认为你具有较高的观察价值。", "expression": "", "background": "day", "next": "1-3-text-0116" },
    { "id": "1-3-text-0116", "type": "dialogue", "speaker": "我", "content": "这听起来不像什么好话。", "expression": "", "background": "day", "next": "1-3-text-0117" },
    { "id": "1-3-text-0117", "type": "dialogue", "speaker": "皖萱", "content": "你的住所宽敞，储备充足，甜品质量优良，具备持续研究“人类幸福来源”的优越条件。", "expression": "", "background": "day", "next": "1-3-text-0118" },
    { "id": "1-3-text-0118", "type": "dialogue", "speaker": "我", "content": "你直接说你想蹭吃蹭住就行。", "expression": "", "background": "day", "next": "1-3-text-0119" },
    { "id": "1-3-text-0119", "type": "narration", "speaker": "", "content": "她沉默两秒，没有反驳。", "expression": "", "background": "day", "next": "1-3-text-0120" },
    { "id": "1-3-text-0120", "type": "dialogue", "speaker": "皖萱", "content": "……如果用人类比较容易理解的说法，是的。", "expression": "", "background": "day", "next": "1-3-text-0121" },
    { "id": "1-3-text-0121", "type": "narration", "speaker": "", "content": "我靠在沙发背上，看着她。", "expression": "", "background": "day", "next": "1-3-text-0122" },
    { "id": "1-3-text-0122", "type": "narration", "speaker": "", "content": "老实说，正常人现在应该报警，或者至少把这位“从阳台掉下来的自称天使的少女”送去更适合解释这一切的地方。", "expression": "", "background": "day", "next": "1-3-text-0123" },
    { "id": "1-3-text-0123", "type": "narration", "speaker": "", "content": "可奇怪的是，我并没有太强烈的排斥感。", "expression": "", "background": "day", "next": "1-3-text-0124" },
    { "id": "1-3-text-0124", "type": "narration", "speaker": "", "content": "也许是因为她看上去实在不像危险。", "expression": "", "background": "day", "next": "1-3-text-0125" },
    { "id": "1-3-text-0125", "type": "narration", "speaker": "", "content": "也许是因为这个下午原本太静了，而她像一颗偏离轨道的小行星，猝不及防撞进来，硬生生在我一成不变的日常里砸开一圈涟漪。", "expression": "", "background": "day", "next": "1-3-text-0126" },
    { "id": "1-3-text-0126", "type": "narration", "speaker": "", "content": "又或者，只是因为她吃蛋糕时那副太过认真的样子，让我有一点莫名其妙地……想再看一次。", "expression": "", "background": "day", "next": "1-3-text-0127" },
    { "id": "1-3-text-0127", "type": "dialogue", "speaker": "我", "content": "你打算观察多久？", "expression": "", "background": "day", "next": "1-3-text-0128" },
    { "id": "1-3-text-0128", "type": "dialogue", "speaker": "皖萱", "content": "按原定计划，是三十个地面日。", "expression": "", "background": "day", "next": "1-3-text-0129" },
    { "id": "1-3-text-0129", "type": "dialogue", "speaker": "我", "content": "一个月？", "expression": "", "background": "day", "next": "1-3-text-0130" },
    { "id": "1-3-text-0130", "type": "dialogue", "speaker": "皖萱", "content": "是的。", "expression": "", "background": "day", "next": "1-3-text-0131" },
    { "id": "1-3-text-0131", "type": "dialogue", "speaker": "我", "content": "你有住的地方吗？", "expression": "", "background": "day", "next": "1-3-text-0132" },
    { "id": "1-3-text-0132", "type": "narration", "speaker": "", "content": "她摇头。", "expression": "", "background": "day", "next": "1-3-text-0133" },
    { "id": "1-3-text-0133", "type": "dialogue", "speaker": "我", "content": "钱呢？", "expression": "", "background": "day", "next": "1-3-text-0134" },
    { "id": "1-3-text-0134", "type": "narration", "speaker": "", "content": "她继续摇头。", "expression": "", "background": "day", "next": "1-3-text-0135" },
    { "id": "1-3-text-0135", "type": "dialogue", "speaker": "我", "content": "手机？", "expression": "", "background": "day", "next": "1-3-text-0136" },
    { "id": "1-3-text-0136", "type": "narration", "speaker": "", "content": "她迟疑了一下，从袖口里摸出一片发着微光的小羽毛。", "expression": "", "background": "day", "next": "1-3-text-0137" },
    { "id": "1-3-text-0137", "type": "dialogue", "speaker": "皖萱", "content": "这个可以进行部分联络。", "expression": "", "background": "day", "next": "1-3-text-0138" },
    { "id": "1-3-text-0138", "type": "dialogue", "speaker": "我", "content": "……行，当我没问。", "expression": "", "background": "day", "next": "1-3-text-0139" },
    { "id": "1-3-text-0139", "type": "narration", "speaker": "", "content": "我按了按眉心。", "expression": "", "background": "day", "next": "1-3-text-0140" },
    { "id": "1-3-text-0140", "type": "narration", "speaker": "", "content": "这事无论从哪方面看都很离谱。", "expression": "", "background": "day", "next": "1-3-text-0141" },
    { "id": "1-3-text-0141", "type": "narration", "speaker": "", "content": "可离谱到一定程度，反而会让人懒得追究逻辑。", "expression": "", "background": "day", "next": "1-3-text-0142" },
    { "id": "1-3-text-0142", "type": "narration", "speaker": "", "content": "我站起身，把茶几上空掉的蛋糕盒收好。", "expression": "", "background": "day", "next": "1-3-text-0143" },
    { "id": "1-3-text-0143", "type": "dialogue", "speaker": "我", "content": "我这里只有一个条件。", "expression": "", "background": "day", "next": "1-3-text-0144" },
    { "id": "1-3-text-0144", "type": "narration", "speaker": "", "content": "她立刻坐直。", "expression": "", "background": "day", "next": "1-3-text-0145" },
    { "id": "1-3-text-0145", "type": "dialogue", "speaker": "皖萱", "content": "请说。", "expression": "", "background": "day", "next": "1-3-text-0146" },
    { "id": "1-3-text-0146", "type": "dialogue", "speaker": "我", "content": "别把我家拆了。", "expression": "", "background": "day", "next": "1-3-text-0147" },
    { "id": "1-3-text-0147", "type": "narration", "speaker": "", "content": "她很认真地点头。", "expression": "", "background": "day", "next": "1-3-text-0148" },
    { "id": "1-3-text-0148", "type": "dialogue", "speaker": "皖萱", "content": "我会尽量优雅地活动。", "expression": "", "background": "day", "next": "1-3-text-0149" },
    { "id": "1-3-text-0149", "type": "dialogue", "speaker": "我", "content": "还有，别随便从阳台着陆。", "expression": "", "background": "day", "next": "1-3-text-0150" },
    { "id": "1-3-text-0150", "type": "dialogue", "speaker": "皖萱", "content": "……这个也会尽量。", "expression": "", "background": "day", "next": "1-3-text-0151" },
    { "id": "1-3-text-0151", "type": "narration", "speaker": "", "content": "我看着她，叹了口气。", "expression": "", "background": "day", "next": "1-3-text-0152" },
    { "id": "1-3-text-0152", "type": "dialogue", "speaker": "我", "content": "客房一直空着。你要是没地方去，就先住那儿。", "expression": "", "background": "day", "next": "1-3-text-0153" },
    { "id": "1-3-text-0153", "type": "narration", "speaker": "", "content": "她睁大眼睛，像是没想到会这么顺利。", "expression": "", "background": "day", "next": "1-3-text-0154" },
    { "id": "1-3-text-0154", "type": "narration", "speaker": "", "content": "下一秒，那种近乎圣洁的端庄表情裂开一点，露出底下藏不住的喜悦。", "expression": "", "background": "day", "next": "1-3-text-0155" },
    { "id": "1-3-text-0155", "type": "dialogue", "speaker": "皖萱", "content": "真的吗？", "expression": "", "background": "day", "next": "1-3-text-0156" },
    { "id": "1-3-text-0156", "type": "dialogue", "speaker": "我", "content": "真的。", "expression": "", "background": "day", "next": "1-3-text-0157" },
    { "id": "1-3-text-0157", "type": "dialogue", "speaker": "皖萱", "content": "那我会非常认真地观察你的。", "expression": "", "background": "day", "next": "1-3-text-0158" },
    { "id": "1-3-text-0158", "type": "dialogue", "speaker": "我", "content": "听上去像被什么奇怪机构盯上了。", "expression": "", "background": "day", "next": "1-3-text-0159" },
    { "id": "1-3-text-0159", "type": "dialogue", "speaker": "皖萱", "content": "请放心，我的研究方向主要集中在——", "expression": "", "background": "day", "next": "1-3-text-0160" },
    { "id": "1-3-text-0160", "type": "narration", "speaker": "", "content": "她停顿一下，神色庄重。", "expression": "", "background": "day", "next": "1-3-text-0161" },
    { "id": "1-3-text-0161", "type": "dialogue", "speaker": "皖萱", "content": "一日三餐、加餐、夜宵，以及甜点在人类情感稳定中的作用。", "expression": "", "background": "day", "next": "1-3-text-0162" },
    { "id": "1-3-text-0162", "type": "narration", "speaker": "", "content": "我忍不住笑出声。", "expression": "", "background": "day", "next": "1-3-text-0163" },
    { "id": "1-3-text-0163", "type": "narration", "speaker": "", "content": "那笑意很轻，却久违地不是出于礼貌，也不是因为看了什么随手点开的短视频。", "expression": "", "background": "day", "next": "1-3-text-0164" },
    { "id": "1-3-text-0164", "type": "narration", "speaker": "", "content": "只是单纯地觉得好笑，所以笑了。", "expression": "", "background": "day", "next": "1-3-text-0165" },
    { "id": "1-3-text-0165", "type": "narration", "speaker": "", "content": "她看着我，眨了眨眼。", "expression": "", "background": "day", "next": "1-3-text-0166" },
    { "id": "1-3-text-0166", "type": "dialogue", "speaker": "皖萱", "content": "你现在的情绪波动，和刚才独自吃蛋糕时不一样。", "expression": "", "background": "day", "next": "1-3-text-0167" },
    { "id": "1-3-text-0167", "type": "narration", "speaker": "", "content": "我一怔。", "expression": "", "background": "day", "next": "1-3-text-0168" },
    { "id": "1-3-text-0168", "type": "dialogue", "speaker": "皖萱", "content": "刚才的你，像把自己放在一个很大的盒子里。", "expression": "", "background": "day", "next": "1-3-text-0169" },
    { "id": "1-3-text-0169", "type": "narration", "speaker": "", "content": "明明周围有光，也有吃的，可是光照不进去，味道也只停在嘴里。", "expression": "", "background": "day", "next": "1-3-text-0170" },
    { "id": "1-3-text-0170", "type": "narration", "speaker": "", "content": "现在稍微不一样了。", "expression": "", "background": "day", "next": "1-3-text-0171" },
    { "id": "1-3-text-0171", "type": "narration", "speaker": "", "content": "我没接话。", "expression": "", "background": "day", "next": "1-3-text-0172" },
    { "id": "1-3-text-0172", "type": "narration", "speaker": "", "content": "因为她说得太直。", "expression": "", "background": "day", "next": "1-3-text-0173" },
    { "id": "1-3-text-0173", "type": "narration", "speaker": "", "content": "直得像一根羽毛，轻飘飘落下来，却恰好压在最难解释的地方。", "expression": "", "background": "day", "next": "1-3-text-0174" },
    { "id": "1-3-text-0174", "type": "narration", "speaker": "", "content": "她却像没意识到自己说了多么接近本质的话，只是偏头看我，认真地补上一句：", "expression": "", "background": "day", "next": "1-3-text-0175" },
    { "id": "1-3-text-0175", "type": "dialogue", "speaker": "皖萱", "content": "也许这就是我的降临任务开始奏效了。", "expression": "", "background": "day", "next": "1-4" },
    { "id": "1-4", "type": "marker", "markerTitle": "第一顿正式晚餐", "next": "1-4-text-0177" },
    { "id": "1-4-text-0177", "type": "narration", "speaker": "", "content": "到了傍晚，我才后知后觉地意识到，家里突然多了一个人，意味着很多平时不需要思考的小事也要重新开始计算。", "expression": "", "background": "evening", "stageNote": "【场景】餐厅 / 傍晚\n【BG】夕阳染色的餐桌\n【BGM】温暖木吉他", "next": "1-4-text-0178" },
    { "id": "1-4-text-0178", "type": "narration", "speaker": "", "content": "比如晚餐。", "expression": "", "background": "evening", "next": "1-4-text-0179" },
    { "id": "1-4-text-0179", "type": "narration", "speaker": "", "content": "我本来打算随便叫个外卖。", "expression": "", "background": "evening", "next": "1-4-text-0180" },
    { "id": "1-4-text-0180", "type": "narration", "speaker": "", "content": "可她坐在餐桌边，双手扶着椅子，安安静静看着我，目光里有一种不加掩饰的期待。那种期待很单纯，单纯到让我忽然觉得，如果只用塑料盒把这顿饭解决掉，好像有点对不起她下午那副把蛋糕吃出宗教感的样子。", "expression": "", "background": "evening", "next": "1-4-text-0181" },
    { "id": "1-4-text-0181", "type": "narration", "speaker": "", "content": "于是我打开冰箱，看了看现有的食材。", "expression": "", "background": "evening", "next": "1-4-text-0182" },
    { "id": "1-4-text-0182", "type": "narration", "speaker": "", "content": "最后做得不复杂。", "expression": "", "background": "evening", "next": "1-4-text-0183" },
    { "id": "1-4-text-0183", "type": "narration", "speaker": "", "content": "黄油煎三文鱼，奶油蘑菇汤，一碗简单的蒜香意面，再配一小盘切好的番茄和生菜。", "expression": "", "background": "evening", "next": "1-4-text-0184" },
    { "id": "1-4-text-0184", "type": "narration", "speaker": "", "content": "锅里的黄油融化时，香气是最先从边缘起来的。", "expression": "", "background": "evening", "next": "1-4-text-0185" },
    { "id": "1-4-text-0185", "type": "narration", "speaker": "", "content": "它不像甜点那种柔软的甜，而是更厚一点，更热一点，带着乳脂受热后才会释放出的圆润香味。三文鱼下锅的一瞬间，表面立刻发出细密的“滋啦”声，粉橘色的鱼肉被热气逼出一点透明的油光，边缘慢慢卷起，空气里很快多了一股鲜香。", "expression": "", "background": "evening", "next": "1-4-text-0186" },
    { "id": "1-4-text-0186", "type": "narration", "speaker": "", "content": "我转头时，发现皖萱已经站到了厨房门口。", "expression": "", "background": "evening", "next": "1-4-text-0187" },
    { "id": "1-4-text-0187", "type": "narration", "speaker": "", "content": "她扶着门框，表情像在观看某种重要仪式。", "expression": "", "background": "evening", "next": "1-4-text-0188" },
    { "id": "1-4-text-0188", "type": "dialogue", "speaker": "皖萱", "content": "这也是幸福生成的过程吗？", "expression": "", "background": "evening", "next": "1-4-text-0189" },
    { "id": "1-4-text-0189", "type": "dialogue", "speaker": "我", "content": "算是吧。", "expression": "", "background": "evening", "next": "1-4-text-0190" },
    { "id": "1-4-text-0190", "type": "dialogue", "speaker": "皖萱", "content": "原来幸福在生成的时候，会发出这样的声音。", "expression": "", "background": "evening", "next": "1-4-text-0191" },
    { "id": "1-4-text-0191", "type": "narration", "speaker": "", "content": "晚餐端上桌时，夕阳刚好斜斜落进来。", "expression": "", "background": "evening", "next": "1-4-text-0192" },
    { "id": "1-4-text-0192", "type": "narration", "speaker": "", "content": "瓷盘边缘被照出一圈淡金色。奶油汤表面漂着细碎黑胡椒，热气一缕一缕往上升。蒜香意面上撒了欧芹碎和少量芝士粉，三文鱼表皮煎得微焦，切开时内部还是柔嫩的浅橘色。", "expression": "", "background": "evening", "next": "1-4-text-0193" },
    { "id": "1-4-text-0193", "type": "narration", "speaker": "", "content": "皖萱握着叉子，看了很久，像不知道该从哪里开始。", "expression": "", "background": "evening", "next": "1-4-text-0194" },
    { "id": "1-4-text-0194", "type": "dialogue", "speaker": "我", "content": "不合口味？", "expression": "", "background": "evening", "next": "1-4-text-0195" },
    { "id": "1-4-text-0195", "type": "dialogue", "speaker": "皖萱", "content": "不是。", "expression": "", "background": "evening", "next": "1-4-text-0196" },
    { "id": "1-4-text-0196", "type": "narration", "speaker": "", "content": "是感觉……太丰盛了。", "expression": "", "background": "evening", "next": "1-4-text-0197" },
    { "id": "1-4-text-0197", "type": "narration", "speaker": "", "content": "她低头先尝了一口汤。", "expression": "", "background": "evening", "next": "1-4-text-0198" },
    { "id": "1-4-text-0198", "type": "narration", "speaker": "", "content": "奶油汤入口的那一下，她眼睛就弯了。", "expression": "", "background": "evening", "next": "1-4-text-0199" },
    { "id": "1-4-text-0199", "type": "dialogue", "speaker": "皖萱", "content": "热的。", "expression": "", "background": "evening", "next": "1-4-text-0200" },
    { "id": "1-4-text-0200", "type": "narration", "speaker": "", "content": "那语气轻得像叹息。", "expression": "", "background": "evening", "next": "1-4-text-0201" },
    { "id": "1-4-text-0201", "type": "dialogue", "speaker": "皖萱", "content": "蘑菇有一点点潮湿森林的味道，奶油很柔软，咽下去的时候喉咙会变暖。", "expression": "", "background": "evening", "next": "1-4-text-0202" },
    { "id": "1-4-text-0202", "type": "narration", "speaker": "", "content": "这和蛋糕不一样。蛋糕像被光照到的云，这个像是……被毛毯裹住。", "expression": "", "background": "evening", "next": "1-4-text-0203" },
    { "id": "1-4-text-0203", "type": "narration", "speaker": "", "content": "我拿叉子的动作停了停。", "expression": "", "background": "evening", "next": "1-4-text-0204" },
    { "id": "1-4-text-0204", "type": "narration", "speaker": "", "content": "平心而论，这只是一碗做法稳定的奶油蘑菇汤。", "expression": "", "background": "evening", "next": "1-4-text-0205" },
    { "id": "1-4-text-0205", "type": "narration", "speaker": "", "content": "可她的形容让它忽然有了超过“好喝”本身的温度。", "expression": "", "background": "evening", "next": "1-4-text-0206" },
    { "id": "1-4-text-0206", "type": "narration", "speaker": "", "content": "她又去切三文鱼。", "expression": "", "background": "evening", "next": "1-4-text-0207" },
    { "id": "1-4-text-0207", "type": "narration", "speaker": "", "content": "刀叉碰到表皮，发出细小清脆的一声。外层轻焦，里面却嫩，鱼肉分开时像瓣瓣散开的粉色花纹。她放进嘴里，先是安静地嚼，接着很轻地吸了一口气。", "expression": "", "background": "evening", "next": "1-4-text-0208" },
    { "id": "1-4-text-0208", "type": "dialogue", "speaker": "皖萱", "content": "边上脆一点，中间很软。", "expression": "", "background": "evening", "next": "1-4-text-0209" },
    { "id": "1-4-text-0209", "type": "narration", "speaker": "", "content": "还有汁水。", "expression": "", "background": "evening", "next": "1-4-text-0210" },
    { "id": "1-4-text-0210", "type": "narration", "speaker": "", "content": "咬下去的时候，盐和黄油的味道会一起出来……", "expression": "", "background": "evening", "next": "1-4-text-0211" },
    { "id": "1-4-text-0211", "type": "narration", "speaker": "", "content": "她说着说着，声音忽然变小。", "expression": "", "background": "evening", "next": "1-4-text-0212" },
    { "id": "1-4-text-0212", "type": "dialogue", "speaker": "皖萱", "content": "人类为了活着，居然会把“吃饭”这件事做得这么认真吗？", "expression": "", "background": "evening", "next": "1-4-text-0213" },
    { "id": "1-4-text-0213", "type": "narration", "speaker": "", "content": "我低头笑了笑。", "expression": "", "background": "evening", "next": "1-4-text-0214" },
    { "id": "1-4-text-0214", "type": "dialogue", "speaker": "我", "content": "也不是所有人都这么认真。", "expression": "", "background": "evening", "next": "1-4-text-0215" },
    { "id": "1-4-text-0215", "type": "dialogue", "speaker": "皖萱", "content": "那你为什么会？", "expression": "", "background": "evening", "next": "1-4-text-0216" },
    { "id": "1-4-text-0216", "type": "narration", "speaker": "", "content": "为什么。", "expression": "", "background": "evening", "next": "1-4-text-0217" },
    { "id": "1-4-text-0217", "type": "narration", "speaker": "", "content": "这个问题很奇怪。", "expression": "", "background": "evening", "next": "1-4-text-0218" },
    { "id": "1-4-text-0218", "type": "narration", "speaker": "", "content": "我以前没想过。", "expression": "", "background": "evening", "next": "1-4-text-0219" },
    { "id": "1-4-text-0219", "type": "narration", "speaker": "", "content": "也许是因为一个人住久了，如果不在吃的上面花一点心思，日子就真的会变成纯粹的生存。", "expression": "", "background": "evening", "next": "1-4-text-0220" },
    { "id": "1-4-text-0220", "type": "narration", "speaker": "", "content": "起床、工作、点外卖、洗澡、睡觉。", "expression": "", "background": "evening", "next": "1-4-text-0221" },
    { "id": "1-4-text-0221", "type": "narration", "speaker": "", "content": "每一天都能过，但每一天都很像复制品。", "expression": "", "background": "evening", "next": "1-4-text-0222" },
    { "id": "1-4-text-0222", "type": "narration", "speaker": "", "content": "我看着面前的餐盘，又看她认真吃饭的样子，忽然有了一个更清楚的答案。", "expression": "", "background": "evening", "next": "1-4-text-0223" },
    { "id": "1-4-text-0223", "type": "dialogue", "speaker": "我", "content": "可能是因为，如果连吃饭都不认真一点，会更像一个人了。", "expression": "", "background": "evening", "next": "1-4-text-0224" },
    { "id": "1-4-text-0224", "type": "narration", "speaker": "", "content": "她抬眼看我。", "expression": "", "background": "evening", "next": "1-4-text-0225" },
    { "id": "1-4-text-0225", "type": "narration", "speaker": "", "content": "这次，她没立刻接话，也没用那种天真得近乎直白的方式继续拆开我。", "expression": "", "background": "evening", "next": "1-4-text-0226" },
    { "id": "1-4-text-0226", "type": "narration", "speaker": "", "content": "她只是低下头，把手边的番茄轻轻叉起来，咬了一口。", "expression": "", "background": "evening", "next": "1-4-text-0227" },
    { "id": "1-4-text-0227", "type": "narration", "speaker": "", "content": "番茄汁在齿间破开，酸甜很新鲜。", "expression": "", "background": "evening", "next": "1-4-text-0228" },
    { "id": "1-4-text-0228", "type": "narration", "speaker": "", "content": "她嚼了两下，忽然很小声地说：", "expression": "", "background": "evening", "next": "1-4-text-0229" },
    { "id": "1-4-text-0229", "type": "dialogue", "speaker": "皖萱", "content": "那从今天开始，你不是一个人吃饭了。", "expression": "", "background": "evening", "next": "第二幕-共生——两个人的食光轨迹" },
    { "id": "第二幕-共生——两个人的食光轨迹", "type": "marker", "markerTitle": "第二幕：共生——两个人的“食”光轨迹", "next": "2-1" },
    { "id": "2-1", "type": "marker", "markerTitle": "厨房里的共犯", "next": "2-1-text-0232" },
    { "id": "2-1-text-0232", "type": "narration", "speaker": "", "content": "皖萱住进来第三天，提出了一个很严肃的要求。", "expression": "", "background": "day", "stageNote": "【场景】厨房 / 白天", "next": "2-1-text-0233" },
    { "id": "2-1-text-0233", "type": "dialogue", "speaker": "皖萱", "content": "我认为，单方面接受投喂，不利于建立平衡的观察关系。", "expression": "", "background": "day", "next": "2-1-text-0234" },
    { "id": "2-1-text-0234", "type": "dialogue", "speaker": "我", "content": "所以？", "expression": "", "background": "day", "next": "2-1-text-0235" },
    { "id": "2-1-text-0235", "type": "dialogue", "speaker": "皖萱", "content": "所以今天开始，我会协助你进行食物制作。", "expression": "", "background": "day", "next": "2-1-text-0236" },
    { "id": "2-1-text-0236", "type": "narration", "speaker": "", "content": "我看了一眼她那双一看就不像切过菜的手，保持了谨慎的沉默。", "expression": "", "background": "day", "next": "2-1-text-0237" },
    { "id": "2-1-text-0237", "type": "dialogue", "speaker": "我", "content": "你会做饭？", "expression": "", "background": "day", "next": "2-1-text-0238" },
    { "id": "2-1-text-0238", "type": "dialogue", "speaker": "皖萱", "content": "理论课程成绩优秀。", "expression": "", "background": "day", "next": "2-1-text-0239" },
    { "id": "2-1-text-0239", "type": "dialogue", "speaker": "我", "content": "实践呢？", "expression": "", "background": "day", "next": "2-1-text-0240" },
    { "id": "2-1-text-0240", "type": "dialogue", "speaker": "皖萱", "content": "……降落课程我原本也以为自己很优秀。", "expression": "", "background": "day", "next": "2-1-text-0241" },
    { "id": "2-1-text-0241", "type": "narration", "speaker": "", "content": "我笑了。", "expression": "", "background": "day", "next": "2-1-text-0242" },
    { "id": "2-1-text-0242", "type": "narration", "speaker": "", "content": "最后还是答应了她。", "expression": "", "background": "day", "next": "2-1-text-0243" },
    { "id": "2-1-text-0243", "type": "narration", "speaker": "", "content": "冰箱里有刚买回来的米、海苔、金枪鱼罐头、蛋黄酱和一些配菜。", "expression": "", "background": "day", "next": "2-1-text-0244" },
    { "id": "2-1-text-0244", "type": "narration", "speaker": "", "content": "我本来打算做点复杂的东西，可她站在料理台边，盯着那锅刚蒸好的米饭，眼神简直像被白雾里的香气勾走了魂。", "expression": "", "background": "day", "next": "2-1-text-0245" },
    { "id": "2-1-text-0245", "type": "narration", "speaker": "", "content": "新米刚焖好时，香味和任何炒菜都不一样。", "expression": "", "background": "day", "next": "2-1-text-0246" },
    { "id": "2-1-text-0246", "type": "narration", "speaker": "", "content": "它没有很强的攻击性，只是温温热热地往上冒，像一层极轻的雾，里面裹着谷物本身干净而安稳的甜。掀锅那一下，水汽扑到脸上，连视线都会被烫得模糊半秒。", "expression": "", "background": "day", "next": "2-1-text-0247" },
    { "id": "2-1-text-0247", "type": "dialogue", "speaker": "皖萱", "content": "这个味道……好温柔。", "expression": "", "background": "day", "next": "2-1-text-0248" },
    { "id": "2-1-text-0248", "type": "dialogue", "speaker": "我", "content": "饭团要不要试试？", "expression": "", "background": "day", "next": "2-1-text-0249" },
    { "id": "2-1-text-0249", "type": "narration", "speaker": "", "content": "她立刻点头。", "expression": "", "background": "day", "next": "2-1-text-0250" },
    { "id": "2-1-text-0250", "type": "narration", "speaker": "", "content": "于是那天的午饭从“可能很丰盛的一桌”变成了“意外朴素的饭团定食”。", "expression": "", "background": "day", "next": "2-1-text-0251" },
    { "id": "2-1-text-0251", "type": "narration", "speaker": "", "content": "米饭稍微晾到不烫手，我示意她洗手。", "expression": "", "background": "day", "next": "2-1-text-0252" },
    { "id": "2-1-text-0252", "type": "narration", "speaker": "", "content": "她把手伸到水流下，动作很认真，连指缝都仔仔细细冲了一遍，像要参加某种神圣仪式。", "expression": "", "background": "day", "next": "2-1-text-0253" },
    { "id": "2-1-text-0253", "type": "narration", "speaker": "", "content": "我把盐、海苔、金枪鱼拌蛋黄酱都摆好，示范给她看。", "expression": "", "background": "day", "next": "2-1-text-0254" },
    { "id": "2-1-text-0254", "type": "dialogue", "speaker": "我", "content": "先沾一点盐，米不要握太紧，不然会硬。", "expression": "", "background": "day", "next": "2-1-text-0255" },
    { "id": "2-1-text-0255", "type": "narration", "speaker": "", "content": "中间留空，把馅塞进去，再慢慢合起来。", "expression": "", "background": "day", "next": "2-1-text-0256" },
    { "id": "2-1-text-0256", "type": "narration", "speaker": "", "content": "她看得很专注。", "expression": "", "background": "day", "next": "2-1-text-0257" },
    { "id": "2-1-text-0257", "type": "narration", "speaker": "", "content": "轮到自己上手时，却还是高估了自己对“适度用力”的理解。", "expression": "", "background": "day", "next": "2-1-text-0258" },
    { "id": "2-1-text-0258", "type": "narration", "speaker": "", "content": "第一个饭团被她捏得很实，圆滚滚一只，像颗认真过头的雪球。", "expression": "", "background": "day", "next": "2-1-text-0259" },
    { "id": "2-1-text-0259", "type": "narration", "speaker": "", "content": "第二个则因为太想轻一点，刚翻面就裂开，米粒“哗啦”散了一小半。", "expression": "", "background": "day", "next": "2-1-text-0260" },
    { "id": "2-1-text-0260", "type": "narration", "speaker": "", "content": "她低头盯着手里的失败品，表情肉眼可见地蔫下去。", "expression": "", "background": "day", "next": "2-1-text-0261" },
    { "id": "2-1-text-0261", "type": "dialogue", "speaker": "皖萱", "content": "它牺牲了。", "expression": "", "background": "day", "next": "2-1-text-0262" },
    { "id": "2-1-text-0262", "type": "dialogue", "speaker": "我", "content": "只是散了，还能吃。", "expression": "", "background": "day", "next": "2-1-text-0263" },
    { "id": "2-1-text-0263", "type": "dialogue", "speaker": "皖萱", "content": "我在伤害食物。", "expression": "", "background": "day", "next": "2-1-text-0264" },
    { "id": "2-1-text-0264", "type": "dialogue", "speaker": "我", "content": "没有这么严重。", "expression": "", "background": "day", "next": "2-1-text-0265" },
    { "id": "2-1-text-0265", "type": "narration", "speaker": "", "content": "我伸手过去，帮她把掌心边缘快掉下来的米轻轻按回去。", "expression": "", "background": "day", "next": "2-1-text-0266" },
    { "id": "2-1-text-0266", "type": "narration", "speaker": "", "content": "她的手上沾着米粒和一点水汽，温度很暖。我握住她手背的瞬间，她明显僵了一下。", "expression": "", "background": "day", "next": "2-1-text-0267" },
    { "id": "2-1-text-0267", "type": "narration", "speaker": "", "content": "我也停了一拍。", "expression": "", "background": "day", "next": "2-1-text-0268" },
    { "id": "2-1-text-0268", "type": "narration", "speaker": "", "content": "厨房里很安静，只剩电饭锅保温时细微的嗡鸣。", "expression": "", "background": "day", "next": "2-1-text-0269" },
    { "id": "2-1-text-0269", "type": "narration", "speaker": "", "content": "近距离下，能闻到她身上淡淡的香，不像香水，更像洗净后晾在太阳下的布料味道，干净得几乎没有杂质。", "expression": "", "background": "day", "next": "2-1-text-0270" },
    { "id": "2-1-text-0270", "type": "dialogue", "speaker": "我", "content": "别太用力。", "expression": "", "background": "day", "next": "2-1-text-0271" },
    { "id": "2-1-text-0271", "type": "narration", "speaker": "", "content": "你把它当成会碎的东西，它反而比较容易成形。", "expression": "", "background": "day", "next": "2-1-text-0272" },
    { "id": "2-1-text-0272", "type": "narration", "speaker": "", "content": "她抬头看我。", "expression": "", "background": "day", "next": "2-1-text-0273" },
    { "id": "2-1-text-0273", "type": "narration", "speaker": "", "content": "那目光里有很短暂的一点茫然，然后很轻地“嗯”了一声。", "expression": "", "background": "day", "next": "2-1-text-0274" },
    { "id": "2-1-text-0274", "type": "narration", "speaker": "", "content": "我们靠得很近。", "expression": "", "background": "day", "next": "2-1-text-0275" },
    { "id": "2-1-text-0275", "type": "narration", "speaker": "", "content": "近到我能看见她睫毛投下来的影子，和鼻尖上沾到的一点面粉——不知道是刚才拆海苔包装时蹭上的，还是更早之前留下的。", "expression": "", "background": "day", "next": "2-1-text-0276" },
    { "id": "2-1-text-0276", "type": "narration", "speaker": "", "content": "我没忍住，伸手替她擦了一下。", "expression": "", "background": "day", "next": "2-1-text-0277" },
    { "id": "2-1-text-0277", "type": "narration", "speaker": "", "content": "她眨眼的动作停住了。", "expression": "", "background": "day", "next": "2-1-text-0278" },
    { "id": "2-1-text-0278", "type": "narration", "speaker": "", "content": "我的指腹掠过她脸侧时，触感很轻，很软，像碰到一朵被太阳晒暖的云。那点面粉在指尖化开，留下几乎察觉不到的干燥粉感。", "expression": "", "background": "day", "next": "2-1-text-0279" },
    { "id": "2-1-text-0279", "type": "narration", "speaker": "", "content": "她耳尖一下子红了。", "expression": "", "background": "day", "next": "2-1-text-0280" },
    { "id": "2-1-text-0280", "type": "dialogue", "speaker": "皖萱", "content": "你、你们人类在协助做饭的时候，距离都这么近吗？", "expression": "", "background": "day", "next": "2-1-text-0281" },
    { "id": "2-1-text-0281", "type": "dialogue", "speaker": "我", "content": "看情况。", "expression": "", "background": "day", "next": "2-1-text-0282" },
    { "id": "2-1-text-0282", "type": "dialogue", "speaker": "我", "content": "属于你快把饭团捏成武器的情况。", "expression": "", "background": "day", "next": "2-1-text-0283" },
    { "id": "2-1-text-0283", "type": "narration", "speaker": "", "content": "最后那顿饭很简单。", "expression": "", "background": "day", "next": "2-1-text-0284" },
    { "id": "2-1-text-0284", "type": "narration", "speaker": "", "content": "饭团，玉子烧，味噌汤，再配两小碟腌黄瓜。", "expression": "", "background": "day", "next": "2-1-text-0285" },
    { "id": "2-1-text-0285", "type": "narration", "speaker": "", "content": "可我们坐下来时，皖萱盯着自己做成的那几个歪歪扭扭的饭团，看得很久，久到像是在确认某种实感。", "expression": "", "background": "day", "next": "2-1-text-0286" },
    { "id": "2-1-text-0286", "type": "narration", "speaker": "", "content": "她咬下第一口，海苔先碎开，米饭的温热和咸味一起铺出来，中间包着的金枪鱼沙拉略带油润，蛋黄酱把鱼肉的纤维感裹得柔和，越嚼越能尝到米本身的甜。", "expression": "", "background": "day", "next": "2-1-text-0287" },
    { "id": "2-1-text-0287", "type": "narration", "speaker": "", "content": "她慢慢咽下去，眼睛一点一点亮起来。", "expression": "", "background": "day", "next": "2-1-text-0288" },
    { "id": "2-1-text-0288", "type": "dialogue", "speaker": "皖萱", "content": "这个味道……和蛋糕不一样，也和昨天的三文鱼不一样。", "expression": "", "background": "day", "next": "2-1-text-0289" },
    { "id": "2-1-text-0289", "type": "narration", "speaker": "", "content": "它没有那么惊艳。", "expression": "", "background": "day", "next": "2-1-text-0290" },
    { "id": "2-1-text-0290", "type": "narration", "speaker": "", "content": "可是吃下去的时候，会觉得心里很安静。", "expression": "", "background": "day", "next": "2-2" },
    { "id": "2-2", "type": "marker", "markerTitle": "外卖箱与人间奇迹", "next": "2-2-text-0292" },
    { "id": "2-2-text-0292", "type": "narration", "speaker": "", "content": "皖萱来到人间后的第一个震撼，不是电视，不是手机，也不是扫地机器人。", "expression": "", "background": "evening", "stageNote": "【场景】客厅 / 傍晚 / 小雨", "next": "2-2-text-0293" },
    { "id": "2-2-text-0293", "type": "narration", "speaker": "", "content": "而是外卖。", "expression": "", "background": "evening", "next": "2-2-text-0294" },
    { "id": "2-2-text-0294", "type": "narration", "speaker": "", "content": "那天下午下雨，我懒得出门，也不想做饭。", "expression": "", "background": "evening", "next": "2-2-text-0295" },
    { "id": "2-2-text-0295", "type": "narration", "speaker": "", "content": "皖萱趴在沙发背上看窗外，白雾一样的雨丝贴着玻璃往下滑，城市在潮湿的光里显得有些朦胧。", "expression": "", "background": "evening", "next": "2-2-text-0296" },
    { "id": "2-2-text-0296", "type": "dialogue", "speaker": "皖萱", "content": "今天的晚餐计划是什么？", "expression": "", "background": "evening", "next": "2-2-text-0297" },
    { "id": "2-2-text-0297", "type": "dialogue", "speaker": "我", "content": "让别人替我们做。", "expression": "", "background": "evening", "next": "2-2-text-0298" },
    { "id": "2-2-text-0298", "type": "narration", "speaker": "", "content": "她转头看我，神情郑重得像在听什么高级人类文明。", "expression": "", "background": "evening", "next": "2-2-text-0299" },
    { "id": "2-2-text-0299", "type": "narration", "speaker": "", "content": "我打开外卖软件，给她看屏幕。", "expression": "", "background": "evening", "next": "2-2-text-0300" },
    { "id": "2-2-text-0300", "type": "narration", "speaker": "", "content": "寿司、炸鸡、拉面、甜品、奶茶、韩餐、烧烤……一整排图片滚过去，像一条永远不会饿死的河。", "expression": "", "background": "evening", "next": "2-2-text-0301" },
    { "id": "2-2-text-0301", "type": "narration", "speaker": "", "content": "她看得呼吸都放轻了。", "expression": "", "background": "evening", "next": "2-2-text-0302" },
    { "id": "2-2-text-0302", "type": "dialogue", "speaker": "皖萱", "content": "这些……都可以送到门口？", "expression": "", "background": "evening", "next": "2-2-text-0303" },
    { "id": "2-2-text-0303", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "evening", "next": "2-2-text-0304" },
    { "id": "2-2-text-0304", "type": "dialogue", "speaker": "皖萱", "content": "只要点一下？", "expression": "", "background": "evening", "next": "2-2-text-0305" },
    { "id": "2-2-text-0305", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "evening", "next": "2-2-text-0306" },
    { "id": "2-2-text-0306", "type": "dialogue", "speaker": "皖萱", "content": "人类的文明是不是基本都用在“避免自己挨饿”上了？", "expression": "", "background": "evening", "next": "2-2-text-0307" },
    { "id": "2-2-text-0307", "type": "dialogue", "speaker": "我", "content": "你这个总结，某种意义上也没错。", "expression": "", "background": "evening", "next": "2-2-text-0308" },
    { "id": "2-2-text-0308", "type": "narration", "speaker": "", "content": "最后她在寿司和炸鸡之间挣扎了很久，像在两种不同的幸福之间做艰难抉择。", "expression": "", "background": "evening", "next": "2-2-text-0309" },
    { "id": "2-2-text-0309", "type": "narration", "speaker": "", "content": "我看着她一脸严肃地比较图片，忽然觉得给人点外卖这件事，也能生出一种莫名的期待。", "expression": "", "background": "evening", "next": "2-2-text-0310" },
    { "id": "2-2-text-0310", "type": "narration", "speaker": "", "content": "像在等一个人第一次拆礼物。", "expression": "", "background": "evening", "next": "2-2-text-0311" },
    { "id": "2-2-text-0311", "type": "narration", "speaker": "", "content": "门铃响的时候，她几乎是从沙发上弹起来的。", "expression": "", "background": "evening", "next": "2-2-text-0312" },
    { "id": "2-2-text-0312", "type": "narration", "speaker": "", "content": "我去开门，门外的雨气一下子漫进来，潮湿、微凉，还带着一点柏油路被打湿后的气味。骑手把两大袋外卖递过来，我接过时，纸袋还是热的，里面混着炸物的油香、米饭的热气和酱汁浓郁的甜咸味。", "expression": "", "background": "evening", "next": "2-2-text-0313" },
    { "id": "2-2-text-0313", "type": "narration", "speaker": "", "content": "皖萱站在玄关，目不转睛地看着。", "expression": "", "background": "evening", "next": "2-2-text-0314" },
    { "id": "2-2-text-0314", "type": "dialogue", "speaker": "皖萱", "content": "幸福是装在纸袋里送来的吗？", "expression": "", "background": "evening", "next": "2-2-text-0315" },
    { "id": "2-2-text-0315", "type": "dialogue", "speaker": "我", "content": "今天这份差不多。", "expression": "", "background": "evening", "next": "2-2-text-0316" },
    { "id": "2-2-text-0316", "type": "narration", "speaker": "", "content": "把餐盒一一摆上桌时，她又一次进入了那种近乎屏息的专注状态。", "expression": "", "background": "evening", "next": "2-2-text-0317" },
    { "id": "2-2-text-0317", "type": "narration", "speaker": "", "content": "透明盒里的寿司整整齐齐排着，米粒柔润，鱼生表面泛着干净的光；炸鸡裹粉金黄，边缘有明显的酥脆纹理，热气把盒盖内壁蒸出一层细小水珠；旁边还有一杯冰奶茶，杯壁结着水，黑色珍珠沉在底下，像一串安静的星子。", "expression": "", "background": "evening", "next": "2-2-text-0318" },
    { "id": "2-2-text-0318", "type": "narration", "speaker": "", "content": "她先去拿寿司。", "expression": "", "background": "evening", "next": "2-2-text-0319" },
    { "id": "2-2-text-0319", "type": "narration", "speaker": "", "content": "蘸上极少一点酱油，送进口中。", "expression": "", "background": "evening", "next": "2-2-text-0320" },
    { "id": "2-2-text-0320", "type": "narration", "speaker": "", "content": "米饭是温的，微微发黏，却不失颗粒感。鱼生贴上舌面时有一种柔软而清凉的滑，像薄薄一层海风。咀嚼之后，脂香才慢慢散出来，不油腻，只是很安静地化开。", "expression": "", "background": "evening", "next": "2-2-text-0321" },
    { "id": "2-2-text-0321", "type": "dialogue", "speaker": "皖萱", "content": "这个好像……很安静的海。", "expression": "", "background": "evening", "next": "2-2-text-0322" },
    { "id": "2-2-text-0322", "type": "dialogue", "speaker": "我", "content": "海？", "expression": "", "background": "evening", "next": "2-2-text-0323" },
    { "id": "2-2-text-0323", "type": "dialogue", "speaker": "皖萱", "content": "嗯。", "expression": "", "background": "evening", "next": "2-2-text-0324" },
    { "id": "2-2-text-0324", "type": "narration", "speaker": "", "content": "它没有很重的味道，可是会慢慢铺开。", "expression": "", "background": "evening", "next": "2-2-text-0325" },
    { "id": "2-2-text-0325", "type": "narration", "speaker": "", "content": "像坐在岸边，风一点一点吹过来。", "expression": "", "background": "evening", "next": "2-2-text-0326" },
    { "id": "2-2-text-0326", "type": "narration", "speaker": "", "content": "她说完，又去夹炸鸡。", "expression": "", "background": "evening", "next": "2-2-text-0327" },
    { "id": "2-2-text-0327", "type": "narration", "speaker": "", "content": "炸衣在齿间“咔”的一声裂开。", "expression": "", "background": "evening", "next": "2-2-text-0328" },
    { "id": "2-2-text-0328", "type": "narration", "speaker": "", "content": "那声音清脆到让人食欲都跟着被勾起来。里面的鸡肉却仍然嫩，汁水被牢牢锁在薄薄一层金黄外壳里，咬下去时先是油香，再是胡椒和一点微甜的调味，热度几乎贴着舌尖扩散。", "expression": "", "background": "evening", "next": "2-2-text-0329" },
    { "id": "2-2-text-0329", "type": "narration", "speaker": "", "content": "皖萱猛地睁大眼睛。", "expression": "", "background": "evening", "next": "2-2-text-0330" },
    { "id": "2-2-text-0330", "type": "dialogue", "speaker": "皖萱", "content": "这个不安静。", "expression": "", "background": "evening", "next": "2-2-text-0331" },
    { "id": "2-2-text-0331", "type": "narration", "speaker": "", "content": "我笑了。", "expression": "", "background": "evening", "next": "2-2-text-0332" },
    { "id": "2-2-text-0332", "type": "dialogue", "speaker": "我", "content": "那它像什么？", "expression": "", "background": "evening", "next": "2-2-text-0333" },
    { "id": "2-2-text-0333", "type": "dialogue", "speaker": "皖萱", "content": "像庆典。", "expression": "", "background": "evening", "next": "2-2-text-0334" },
    { "id": "2-2-text-0334", "type": "narration", "speaker": "", "content": "她说得太认真，反而让我想笑。", "expression": "", "background": "evening", "next": "2-2-text-0335" },
    { "id": "2-2-text-0335", "type": "narration", "speaker": "", "content": "可我没笑出声，只是低头拆开奶茶吸管，递给她。", "expression": "", "background": "evening", "next": "2-2-text-0336" },
    { "id": "2-2-text-0336", "type": "narration", "speaker": "", "content": "她学着我的样子戳开封膜，吸了一口。冰块轻轻撞在杯壁上，发出很小的脆响。茶味先上来，后面是牛奶的顺滑，再往后，珍珠带着弹性慢慢滚进齿间，甜味不算重，却很绵长。", "expression": "", "background": "evening", "next": "2-2-text-0337" },
    { "id": "2-2-text-0337", "type": "dialogue", "speaker": "皖萱", "content": "这又是另一种奇迹。", "expression": "", "background": "evening", "next": "2-2-text-0338" },
    { "id": "2-2-text-0338", "type": "dialogue", "speaker": "我", "content": "你对“奇迹”的标准是不是有点低？", "expression": "", "background": "evening", "next": "2-2-text-0339" },
    { "id": "2-2-text-0339", "type": "dialogue", "speaker": "皖萱", "content": "不是标准低。", "expression": "", "background": "evening", "next": "2-2-text-0340" },
    { "id": "2-2-text-0340", "type": "narration", "speaker": "", "content": "是人类真的很会让平凡的东西变得值得期待。", "expression": "", "background": "evening", "next": "2-2-text-0341" },
    { "id": "2-2-text-0341", "type": "narration", "speaker": "", "content": "窗外还在下雨。", "expression": "", "background": "evening", "next": "2-2-text-0342" },
    { "id": "2-2-text-0342", "type": "narration", "speaker": "", "content": "屋里开着暖黄的灯，炸鸡的香、热米饭的气味和杯壁凝成的凉意混在一起，把原本潮湿发闷的傍晚撑得很满。", "expression": "", "background": "evening", "next": "2-2-text-0343" },
    { "id": "2-2-text-0343", "type": "narration", "speaker": "", "content": "皖萱一边吃，一边认真记笔记。", "expression": "", "background": "evening", "next": "2-2-text-0344" },
    { "id": "2-2-text-0344", "type": "narration", "speaker": "", "content": "是真的记。", "expression": "", "background": "evening", "next": "2-2-text-0345" },
    { "id": "2-2-text-0345", "type": "narration", "speaker": "", "content": "她拿着我给她的便签本，在上面工工整整写：", "expression": "", "background": "evening", "next": "2-2-text-0346" },
    { "id": "2-2-text-0346", "type": "narration", "speaker": "", "content": "“外卖：人类把等待也做成了幸福的一部分。”", "expression": "", "background": "evening", "next": "2-2-text-0347" },
    { "id": "2-2-text-0347", "type": "narration", "speaker": "", "content": "我看着那行字，心口有一点说不清的发热。", "expression": "", "background": "evening", "next": "2-2-text-0348" },
    { "id": "2-2-text-0348", "type": "dialogue", "speaker": "我", "content": "你们天界还要交书面报告？", "expression": "", "background": "evening", "next": "2-2-text-0349" },
    { "id": "2-2-text-0349", "type": "dialogue", "speaker": "皖萱", "content": "当然。", "expression": "", "background": "evening", "next": "2-2-text-0350" },
    { "id": "2-2-text-0350", "type": "narration", "speaker": "", "content": "调查不能只靠感动，要有证据。", "expression": "", "background": "evening", "next": "2-2-text-0351" },
    { "id": "2-2-text-0351", "type": "dialogue", "speaker": "我", "content": "那今天的证据是什么？", "expression": "", "background": "evening", "next": "2-2-text-0352" },
    { "id": "2-2-text-0352", "type": "narration", "speaker": "", "content": "她停下笔，抬头看我。", "expression": "", "background": "evening", "next": "2-2-text-0353" },
    { "id": "2-2-text-0353", "type": "dialogue", "speaker": "皖萱", "content": "证据是，下雨天不用出门，也会有人和热腾腾的饭一起按响门铃。", "expression": "", "background": "evening", "next": "2-2-text-0354" },
    { "id": "2-2-text-0354", "type": "narration", "speaker": "", "content": "她想了想，又补了一句。", "expression": "", "background": "evening", "next": "2-2-text-0355" },
    { "id": "2-2-text-0355", "type": "dialogue", "speaker": "皖萱", "content": "还有，等门铃的时候，如果旁边有人一起期待，等待会比食物先变甜。", "expression": "", "background": "evening", "next": "2-2-text-0356" },
    { "id": "2-2-text-0356", "type": "narration", "speaker": "", "content": "那天晚上我们把外卖几乎吃光。", "expression": "", "background": "evening", "next": "2-2-text-0357" },
    { "id": "2-2-text-0357", "type": "narration", "speaker": "", "content": "炸鸡最后还剩一块，她看了看，又看了看我，最终很郑重地把它夹到我碗里。", "expression": "", "background": "evening", "next": "2-2-text-0358" },
    { "id": "2-2-text-0358", "type": "dialogue", "speaker": "皖萱", "content": "观察对象也需要补充能量。", "expression": "", "background": "evening", "next": "2-2-text-0359" },
    { "id": "2-2-text-0359", "type": "dialogue", "speaker": "我", "content": "你不是很喜欢这个？", "expression": "", "background": "evening", "next": "2-2-text-0360" },
    { "id": "2-2-text-0360", "type": "dialogue", "speaker": "皖萱", "content": "喜欢。", "expression": "", "background": "evening", "next": "2-2-text-0361" },
    { "id": "2-2-text-0361", "type": "narration", "speaker": "", "content": "她说到这里，低头抿了一口奶茶，声音轻了一点。", "expression": "", "background": "evening", "next": "2-2-text-0362" },
    { "id": "2-2-text-0362", "type": "dialogue", "speaker": "皖萱", "content": "可是一起吃饭，不应该总让一个人把喜欢的都吃完。", "expression": "", "background": "evening", "next": "2-2-text-0363" },
    { "id": "2-2-text-0363", "type": "narration", "speaker": "", "content": "那句话让我握筷子的手停了一瞬。", "expression": "", "background": "evening", "next": "2-2-text-0364" },
    { "id": "2-2-text-0364", "type": "narration", "speaker": "", "content": "以前我一个人吃东西，喜欢什么、不喜欢什么，都不需要被谁看见。反正盘子里最后剩下什么、少了什么，第二天都会和垃圾一起被带走。", "expression": "", "background": "evening", "next": "2-2-text-0365" },
    { "id": "2-2-text-0365", "type": "narration", "speaker": "", "content": "可现在，有人会因为“这是你喜欢的口味”而停下自己本来还想再咬一口的冲动。", "expression": "", "background": "evening", "next": "2-2-text-0366" },
    { "id": "2-2-text-0366", "type": "narration", "speaker": "", "content": "那一瞬间，我突然觉得，所谓被照顾，有时并不是多大的事。", "expression": "", "background": "evening", "next": "2-2-text-0367" },
    { "id": "2-2-text-0367", "type": "narration", "speaker": "", "content": "它只是有人记得把最后一块炸鸡留给你。", "expression": "", "background": "evening", "next": "2-3" },
    { "id": "2-3", "type": "marker", "markerTitle": "并不孤单的下午茶", "next": "2-3-text-0369" },
    { "id": "2-3-text-0369", "type": "narration", "speaker": "", "content": "日子在很细碎的地方变得不一样。", "expression": "", "background": "day", "stageNote": "【场景】客厅 / 午后 / 晴\n【BG】暖阳、懒人沙发、茶几上的甜点盘\n【BGM】慵懒轻爵士", "next": "2-3-text-0370" },
    { "id": "2-3-text-0370", "type": "narration", "speaker": "", "content": "比如原本只用来堆杂志和快递箱的茶几，开始固定在下午出现一只托盘。", "expression": "", "background": "day", "next": "2-3-text-0371" },
    { "id": "2-3-text-0371", "type": "narration", "speaker": "", "content": "有时是红茶和曲奇，有时是咖啡和布丁，有时只是两杯热牛奶配一小碟刚切开的水果。", "expression": "", "background": "day", "next": "2-3-text-0372" },
    { "id": "2-3-text-0372", "type": "narration", "speaker": "", "content": "皖萱对“下午茶”这件事怀有近乎偏爱的耐心。", "expression": "", "background": "day", "next": "2-3-text-0373" },
    { "id": "2-3-text-0373", "type": "narration", "speaker": "", "content": "她说人类把一天切开，在最容易发困和发空的时刻，专门留一段时间给甜和热，这种做法非常聪明。", "expression": "", "background": "day", "next": "2-3-text-0374" },
    { "id": "2-3-text-0374", "type": "narration", "speaker": "", "content": "那天阳光很好。", "expression": "", "background": "day", "next": "2-3-text-0375" },
    { "id": "2-3-text-0375", "type": "narration", "speaker": "", "content": "客厅里的灰尘都像被晒得变轻了，浮在空中，慢慢地飘。皖萱抱着靠枕窝在懒人沙发里，裙摆落下来，像一团被捧松的奶油。茶几上摆着我从附近甜品店买回来的焦糖布丁和刚烤好的黄油曲奇。", "expression": "", "background": "day", "next": "2-3-text-0376" },
    { "id": "2-3-text-0376", "type": "narration", "speaker": "", "content": "布丁表面的焦糖是深琥珀色的。", "expression": "", "background": "day", "next": "2-3-text-0377" },
    { "id": "2-3-text-0377", "type": "narration", "speaker": "", "content": "勺子敲上去时，会先碰到一层很薄的脆壳，然后才陷进下面柔软细腻的蛋奶冻里。那种阻力很轻，像划开一层刚结好的糖霜。", "expression": "", "background": "day", "next": "2-3-text-0378" },
    { "id": "2-3-text-0378", "type": "narration", "speaker": "", "content": "皖萱挖了一勺，送进口中。", "expression": "", "background": "day", "next": "2-3-text-0379" },
    { "id": "2-3-text-0379", "type": "narration", "speaker": "", "content": "焦糖先碎开，微苦，像甜味里故意留下的一点影子。紧接着，蛋奶的柔滑就把那一点苦包住，温顺地化开，只剩下被烤过的糖香和鸡蛋、牛奶混合后的绵密气息。", "expression": "", "background": "day", "next": "2-3-text-0380" },
    { "id": "2-3-text-0380", "type": "narration", "speaker": "", "content": "皖萱闭了闭眼。", "expression": "", "background": "day", "next": "2-3-text-0381" },
    { "id": "2-3-text-0381", "type": "dialogue", "speaker": "皖萱", "content": "这个很像大人。", "expression": "", "background": "day", "next": "2-3-text-0382" },
    { "id": "2-3-text-0382", "type": "dialogue", "speaker": "我", "content": "布丁？", "expression": "", "background": "day", "next": "2-3-text-0383" },
    { "id": "2-3-text-0383", "type": "dialogue", "speaker": "皖萱", "content": "嗯。", "expression": "", "background": "day", "next": "2-3-text-0384" },
    { "id": "2-3-text-0384", "type": "narration", "speaker": "", "content": "先让你尝到一点点苦，可是后面全是软的。", "expression": "", "background": "day", "next": "2-3-text-0385" },
    { "id": "2-3-text-0385", "type": "narration", "speaker": "", "content": "我失笑。", "expression": "", "background": "day", "next": "2-3-text-0386" },
    { "id": "2-3-text-0386", "type": "dialogue", "speaker": "我", "content": "那曲奇像什么？", "expression": "", "background": "day", "next": "2-3-text-0387" },
    { "id": "2-3-text-0387", "type": "narration", "speaker": "", "content": "她拿起一块刚出炉不久的黄油曲奇。", "expression": "", "background": "day", "next": "2-3-text-0388" },
    { "id": "2-3-text-0388", "type": "narration", "speaker": "", "content": "边缘酥得发脆，一掰就会掉下很细的小屑。中心却没那么硬，牙齿一碰就散，黄油和面粉烘烤后的香气带着一点甜，从口腔慢慢往鼻腔里回。", "expression": "", "background": "day", "next": "2-3-text-0389" },
    { "id": "2-3-text-0389", "type": "dialogue", "speaker": "皖萱", "content": "这个像午睡。", "expression": "", "background": "day", "next": "2-3-text-0390" },
    { "id": "2-3-text-0390", "type": "dialogue", "speaker": "我", "content": "这又是怎么得出来的？", "expression": "", "background": "day", "next": "2-3-text-0391" },
    { "id": "2-3-text-0391", "type": "dialogue", "speaker": "皖萱", "content": "因为它一碰就碎，碎完以后会让人很想继续躺着。", "expression": "", "background": "day", "next": "2-3-text-0392" },
    { "id": "2-3-text-0392", "type": "narration", "speaker": "", "content": "她说完就往后缩了一下，真的把自己更深地埋进沙发里。", "expression": "", "background": "day", "next": "2-3-text-0393" },
    { "id": "2-3-text-0393", "type": "narration", "speaker": "", "content": "我看着她，忽然觉得这画面安静得过分。", "expression": "", "background": "day", "next": "2-3-text-0394" },
    { "id": "2-3-text-0394", "type": "narration", "speaker": "", "content": "电视没开，手机被我丢在一边，外面的街道声也很远。屋子里只有杯子碰碟子的细小声音、时钟缓慢推进的咔哒声，以及她偶尔咬到曲奇时发出的很轻的脆响。", "expression": "", "background": "day", "next": "2-3-text-0395" },
    { "id": "2-3-text-0395", "type": "narration", "speaker": "", "content": "我以前不是没度过这样的下午。", "expression": "", "background": "day", "next": "2-3-text-0396" },
    { "id": "2-3-text-0396", "type": "narration", "speaker": "", "content": "甚至可以说，我的大部分下午都差不多：阳光、安静、没有必须立刻处理的事。", "expression": "", "background": "day", "next": "2-3-text-0397" },
    { "id": "2-3-text-0397", "type": "narration", "speaker": "", "content": "可那种安静以前总带着空。", "expression": "", "background": "day", "next": "2-3-text-0398" },
    { "id": "2-3-text-0398", "type": "narration", "speaker": "", "content": "像房间太大，光线太足，反而把人衬得更像一个临时住客。", "expression": "", "background": "day", "next": "2-3-text-0399" },
    { "id": "2-3-text-0399", "type": "narration", "speaker": "", "content": "皖萱忽然侧过头看我。", "expression": "", "background": "day", "next": "2-3-text-0400" },
    { "id": "2-3-text-0400", "type": "dialogue", "speaker": "皖萱", "content": "人类，你明明有这么大的房子，为什么以前总是皱着眉头呢？", "expression": "", "background": "day", "next": "2-3-text-0401" },
    { "id": "2-3-text-0401", "type": "narration", "speaker": "", "content": "我怔了一下。", "expression": "", "background": "day", "next": "2-3-text-0402" },
    { "id": "2-3-text-0402", "type": "narration", "speaker": "", "content": "她说的是“以前”。", "expression": "", "background": "day", "next": "2-3-text-0403" },
    { "id": "2-3-text-0403", "type": "narration", "speaker": "", "content": "说明在她眼里，我现在已经和以前不一样了。", "expression": "", "background": "day", "next": "2-3-text-0404" },
    { "id": "2-3-text-0404", "type": "narration", "speaker": "", "content": "我靠在沙发上，想了想。", "expression": "", "background": "day", "next": "2-3-text-0405" },
    { "id": "2-3-text-0405", "type": "dialogue", "speaker": "我", "content": "因为太安静了。", "expression": "", "background": "day", "next": "2-3-text-0406" },
    { "id": "2-3-text-0406", "type": "dialogue", "speaker": "皖萱", "content": "现在也很安静。", "expression": "", "background": "day", "next": "2-3-text-0407" },
    { "id": "2-3-text-0407", "type": "dialogue", "speaker": "我", "content": "不一样。", "expression": "", "background": "day", "next": "2-3-text-0408" },
    { "id": "2-3-text-0408", "type": "narration", "speaker": "", "content": "她抱着靠枕，等我往下说。", "expression": "", "background": "day", "next": "2-3-text-0409" },
    { "id": "2-3-text-0409", "type": "narration", "speaker": "", "content": "我看着天花板上被窗框切开的光影，慢慢开口。", "expression": "", "background": "day", "next": "2-3-text-0410" },
    { "id": "2-3-text-0410", "type": "dialogue", "speaker": "我", "content": "以前的安静像空房子。", "expression": "", "background": "day", "next": "2-3-text-0411" },
    { "id": "2-3-text-0411", "type": "narration", "speaker": "", "content": "东西很多，声音也有，可都跟我没什么关系。", "expression": "", "background": "day", "next": "2-3-text-0412" },
    { "id": "2-3-text-0412", "type": "narration", "speaker": "", "content": "现在的安静……", "expression": "", "background": "day", "next": "2-3-text-0413" },
    { "id": "2-3-text-0413", "type": "narration", "speaker": "", "content": "我停了停，偏头看她。", "expression": "", "background": "day", "next": "2-3-text-0414" },
    { "id": "2-3-text-0414", "type": "dialogue", "speaker": "我", "content": "现在像是有人在旁边，所以不需要一直说话，也不会觉得空。", "expression": "", "background": "day", "next": "2-3-text-0415" },
    { "id": "2-3-text-0415", "type": "narration", "speaker": "", "content": "她眨了眨眼，像是在认真理解这句话。", "expression": "", "background": "day", "next": "2-3-text-0416" },
    { "id": "2-3-text-0416", "type": "narration", "speaker": "", "content": "接着，她抱着靠枕，慢吞吞地点头。", "expression": "", "background": "day", "next": "2-3-text-0417" },
    { "id": "2-3-text-0417", "type": "dialogue", "speaker": "皖萱", "content": "我懂了。", "expression": "", "background": "day", "next": "2-3-text-0418" },
    { "id": "2-3-text-0418", "type": "dialogue", "speaker": "我", "content": "你懂什么了？", "expression": "", "background": "day", "next": "2-3-text-0419" },
    { "id": "2-3-text-0419", "type": "dialogue", "speaker": "皖萱", "content": "房子原来不是用来装家具的。", "expression": "", "background": "day", "next": "2-3-text-0420" },
    { "id": "2-3-text-0420", "type": "narration", "speaker": "", "content": "她看着我，眼神很软。", "expression": "", "background": "day", "next": "2-3-text-0421" },
    { "id": "2-3-text-0421", "type": "dialogue", "speaker": "皖萱", "content": "是用来装笑声的。", "expression": "", "background": "day", "next": "2-3-text-0422" },
    { "id": "2-3-text-0422", "type": "narration", "speaker": "", "content": "那句话落下来的时候，窗外正好有一阵风吹过。", "expression": "", "background": "day", "next": "2-3-text-0423" },
    { "id": "2-3-text-0423", "type": "narration", "speaker": "", "content": "阳台上的风铃轻轻响了一下，很短，很清。", "expression": "", "background": "day", "next": "2-3-text-0424" },
    { "id": "2-3-text-0424", "type": "narration", "speaker": "", "content": "我望着她，忽然不知道该回什么。", "expression": "", "background": "day", "next": "2-3-text-0425" },
    { "id": "2-3-text-0425", "type": "narration", "speaker": "", "content": "因为那一瞬间，我几乎真的看见了。", "expression": "", "background": "day", "next": "2-3-text-0426" },
    { "id": "2-3-text-0426", "type": "narration", "speaker": "", "content": "看见这座房子之前那些过于整齐、过于清楚的轮廓，慢慢被另一个人的存在填满。客房里多出来的拖鞋，冰箱门上新贴的便签，沙发边她随手放下的靠枕，还有空气里时不时浮起来的、带着甜味和热气的生活感。", "expression": "", "background": "day", "next": "2-3-text-0427" },
    { "id": "2-3-text-0427", "type": "narration", "speaker": "", "content": "原来空旷并不是孤独的证明。", "expression": "", "background": "day", "next": "2-3-text-0428" },
    { "id": "2-3-text-0428", "type": "narration", "speaker": "", "content": "它只是为另一个人的声音，提前留好了位置。", "expression": "", "background": "day", "next": "2-3-text-0429" },
    { "id": "2-3-text-0429", "type": "narration", "speaker": "", "content": "那天下午后来什么也没发生。", "expression": "", "background": "day", "next": "2-3-text-0430" },
    { "id": "2-3-text-0430", "type": "narration", "speaker": "", "content": "我们只是吃完了布丁和曲奇，在阳光最暖的时候，各自占着沙发的一角发呆。皖萱抱着靠枕睡着了一小会儿，呼吸很轻，睫毛落在眼下，安静得像一片停在室内的雪。", "expression": "", "background": "day", "next": "2-3-text-0431" },
    { "id": "2-3-text-0431", "type": "narration", "speaker": "", "content": "我没叫醒她。", "expression": "", "background": "day", "next": "2-3-text-0432" },
    { "id": "2-3-text-0432", "type": "narration", "speaker": "", "content": "只把空调温度调高一点，顺手把滑到她肩头的薄毯往上拉了拉。", "expression": "", "background": "day", "next": "2-3-text-0433" },
    { "id": "2-3-text-0433", "type": "narration", "speaker": "", "content": "那时候我忽然想到，如果所谓幸福真的有具体形状，或许未必总是热烈的。", "expression": "", "background": "day", "next": "2-3-text-0434" },
    { "id": "2-3-text-0434", "type": "narration", "speaker": "", "content": "它也可能只是一个漫长午后里，甜点吃到一半，有人安心地在你身边睡着。", "expression": "", "background": "day", "next": "2-4" },
    { "id": "2-4", "type": "marker", "markerTitle": "深夜煮面与不小心说出口的话", "next": "2-4-text-0436" },
    { "id": "2-4-text-0436", "type": "narration", "speaker": "", "content": "人一旦开始习惯和另一个人分享生活，连深夜都会长出新的轮廓。", "expression": "", "background": "night", "stageNote": "【场景】厨房 / 深夜\n【BG】只开一盏小灯的客厅与厨房\n【BGM】极轻钢琴，近乎无", "next": "2-4-text-0437" },
    { "id": "2-4-text-0437", "type": "narration", "speaker": "", "content": "那天我工作到很晚。", "expression": "", "background": "night", "next": "2-4-text-0438" },
    { "id": "2-4-text-0438", "type": "narration", "speaker": "", "content": "文件关掉时已经过了零点，肩膀酸得发沉，眼睛也有点干。客厅只开着一盏落地灯，暖黄色的光落在地板上，周围反而显得更暗。", "expression": "", "background": "night", "next": "2-4-text-0439" },
    { "id": "2-4-text-0439", "type": "narration", "speaker": "", "content": "我正准备去倒杯水，就看见厨房里亮着灯。", "expression": "", "background": "night", "next": "2-4-text-0440" },
    { "id": "2-4-text-0440", "type": "narration", "speaker": "", "content": "皖萱穿着宽大的家居外套，站在料理台前，头发随意挽起一点，几缕碎发垂在颈侧。她正低头盯着锅，锅里是已经烧开的水，白雾一阵一阵往上扑。", "expression": "", "background": "night", "next": "2-4-text-0441" },
    { "id": "2-4-text-0441", "type": "narration", "speaker": "", "content": "我有点意外。", "expression": "", "background": "night", "next": "2-4-text-0442" },
    { "id": "2-4-text-0442", "type": "dialogue", "speaker": "我", "content": "你还没睡？", "expression": "", "background": "night", "next": "2-4-text-0443" },
    { "id": "2-4-text-0443", "type": "narration", "speaker": "", "content": "她回头，看见我，像是被抓包了一样，动作停顿了半秒。", "expression": "", "background": "night", "next": "2-4-text-0444" },
    { "id": "2-4-text-0444", "type": "dialogue", "speaker": "皖萱", "content": "我本来睡了。", "expression": "", "background": "night", "next": "2-4-text-0445" },
    { "id": "2-4-text-0445", "type": "dialogue", "speaker": "我", "content": "那现在在做什么？", "expression": "", "background": "night", "next": "2-4-text-0446" },
    { "id": "2-4-text-0446", "type": "dialogue", "speaker": "皖萱", "content": "被饿醒了。", "expression": "", "background": "night", "next": "2-4-text-0447" },
    { "id": "2-4-text-0447", "type": "narration", "speaker": "", "content": "我没忍住笑了一声。", "expression": "", "background": "night", "next": "2-4-text-0448" },
    { "id": "2-4-text-0448", "type": "dialogue", "speaker": "我", "content": "天使也会有夜宵需求？", "expression": "", "background": "night", "next": "2-4-text-0449" },
    { "id": "2-4-text-0449", "type": "dialogue", "speaker": "皖萱", "content": "在完成高强度陪伴型观察任务时，适当加餐是合理的。", "expression": "", "background": "night", "next": "2-4-text-0450" },
    { "id": "2-4-text-0450", "type": "narration", "speaker": "", "content": "料理台上摆着很朴素的材料：挂面、鸡蛋、两棵小青菜，还有中午剩下的一点叉烧。", "expression": "", "background": "night", "next": "2-4-text-0451" },
    { "id": "2-4-text-0451", "type": "narration", "speaker": "", "content": "我走过去，替她把火调小一点。", "expression": "", "background": "night", "next": "2-4-text-0452" },
    { "id": "2-4-text-0452", "type": "narration", "speaker": "", "content": "锅里的水已经翻滚得很厉害，蒸汽带着金属锅壁被久热烘出来的味道扑在脸上。她把面放进去时，干燥的面条先是僵直，接着在热水里一点点软下来，慢慢沉进锅底。白色雾气把她的侧脸熏得有些模糊。", "expression": "", "background": "night", "next": "2-4-text-0453" },
    { "id": "2-4-text-0453", "type": "dialogue", "speaker": "我", "content": "怎么不叫我？", "expression": "", "background": "night", "next": "2-4-text-0454" },
    { "id": "2-4-text-0454", "type": "dialogue", "speaker": "皖萱", "content": "你看起来很累。", "expression": "", "background": "night", "next": "2-4-text-0455" },
    { "id": "2-4-text-0455", "type": "narration", "speaker": "", "content": "我一怔。", "expression": "", "background": "night", "next": "2-4-text-0456" },
    { "id": "2-4-text-0456", "type": "dialogue", "speaker": "皖萱", "content": "而且煮面看起来不是很难。", "expression": "", "background": "night", "next": "2-4-text-0457" },
    { "id": "2-4-text-0457", "type": "narration", "speaker": "", "content": "如果我连这个都做不好，调查报告会显得我很没用。", "expression": "", "background": "night", "next": "2-4-text-0458" },
    { "id": "2-4-text-0458", "type": "narration", "speaker": "", "content": "我看着她，忽然不知道先在意哪句。", "expression": "", "background": "night", "next": "2-4-text-0459" },
    { "id": "2-4-text-0459", "type": "narration", "speaker": "", "content": "是“你看起来很累”，还是“我不想显得没用”。", "expression": "", "background": "night", "next": "2-4-text-0460" },
    { "id": "2-4-text-0460", "type": "narration", "speaker": "", "content": "我伸手把青菜切好，又把剩下那点叉烧切成薄片。她站在旁边看，偶尔递一下碗，动作熟练得比刚来时自然很多。", "expression": "", "background": "night", "next": "2-4-text-0461" },
    { "id": "2-4-text-0461", "type": "narration", "speaker": "", "content": "很快，厨房里就有了面的香。", "expression": "", "background": "night", "next": "2-4-text-0462" },
    { "id": "2-4-text-0462", "type": "narration", "speaker": "", "content": "那是很朴素的味道。", "expression": "", "background": "night", "next": "2-4-text-0463" },
    { "id": "2-4-text-0463", "type": "narration", "speaker": "", "content": "不昂贵，也不浓烈。只是热水、面粉、蛋液和一点肉香混在一起，在夜里显得格外实在。青菜焯过后带出一点清甜，叉烧受热后把表面的酱香重新逼了出来，鸡蛋在汤里散开，成了柔软的金白色絮状。", "expression": "", "background": "night", "next": "2-4-text-0464" },
    { "id": "2-4-text-0464", "type": "narration", "speaker": "", "content": "面盛进碗里时，热气几乎把视线都烫弯了。", "expression": "", "background": "night", "next": "2-4-text-0465" },
    { "id": "2-4-text-0465", "type": "narration", "speaker": "", "content": "我们端着碗坐到餐桌边。", "expression": "", "background": "night", "next": "2-4-text-0466" },
    { "id": "2-4-text-0466", "type": "narration", "speaker": "", "content": "桌上没有白天那么多讲究的摆盘，也没有特意准备的配菜。就只是两碗面，和两双筷子。", "expression": "", "background": "night", "next": "2-4-text-0467" },
    { "id": "2-4-text-0467", "type": "narration", "speaker": "", "content": "皖萱先喝了一口汤。", "expression": "", "background": "night", "next": "2-4-text-0468" },
    { "id": "2-4-text-0468", "type": "narration", "speaker": "", "content": "她停住了。", "expression": "", "background": "night", "next": "2-4-text-0469" },
    { "id": "2-4-text-0469", "type": "dialogue", "speaker": "皖萱", "content": "……这个好适合晚上。", "expression": "", "background": "night", "next": "2-4-text-0470" },
    { "id": "2-4-text-0470", "type": "dialogue", "speaker": "我", "content": "为什么？", "expression": "", "background": "night", "next": "2-4-text-0471" },
    { "id": "2-4-text-0471", "type": "dialogue", "speaker": "皖萱", "content": "因为它不需要惊讶。", "expression": "", "background": "night", "next": "2-4-text-0472" },
    { "id": "2-4-text-0472", "type": "narration", "speaker": "", "content": "她捧着碗，掌心贴着碗壁，像捧着一团温度。", "expression": "", "background": "night", "next": "2-4-text-0473" },
    { "id": "2-4-text-0473", "type": "dialogue", "speaker": "皖萱", "content": "白天吃的东西，有时候会让人很开心，很兴奋，很想立刻说“好吃”。", "expression": "", "background": "night", "next": "2-4-text-0474" },
    { "id": "2-4-text-0474", "type": "narration", "speaker": "", "content": "可是这个不是。", "expression": "", "background": "night", "next": "2-4-text-0475" },
    { "id": "2-4-text-0475", "type": "narration", "speaker": "", "content": "这个是你喝下去以后，会觉得“啊，今晚可以好好结束了”。", "expression": "", "background": "night", "next": "2-4-text-0476" },
    { "id": "2-4-text-0476", "type": "narration", "speaker": "", "content": "我低头吃了一口面。", "expression": "", "background": "night", "next": "2-4-text-0477" },
    { "id": "2-4-text-0477", "type": "narration", "speaker": "", "content": "面条煮得刚好，不硬，也没坨。汤底因为叉烧和鸡蛋多了一点温厚的鲜味，青菜把整碗面的味道提亮了一些。确实没有什么惊艳的地方，可它像一只手，把深夜里那些没来得及落下去的疲惫，慢慢按平。", "expression": "", "background": "night", "next": "2-4-text-0478" },
    { "id": "2-4-text-0478", "type": "narration", "speaker": "", "content": "我忽然想起以前那些自己熬夜的晚上。", "expression": "", "background": "night", "next": "2-4-text-0479" },
    { "id": "2-4-text-0479", "type": "narration", "speaker": "", "content": "多数时候，我懒得煮面，饿了就随便翻点饼干，或者干脆倒头就睡。第二天起来胃里空得发疼，也懒得在意。", "expression": "", "background": "night", "next": "2-4-text-0480" },
    { "id": "2-4-text-0480", "type": "narration", "speaker": "", "content": "可现在不一样了。", "expression": "", "background": "night", "next": "2-4-text-0481" },
    { "id": "2-4-text-0481", "type": "narration", "speaker": "", "content": "现在深夜的厨房会亮灯，会有人站在锅边，被饿醒后第一反应不是忍着，而是想把一碗热的东西端上桌。", "expression": "", "background": "night", "next": "2-4-text-0482" },
    { "id": "2-4-text-0482", "type": "narration", "speaker": "", "content": "皖萱咬着面，忽然抬头。", "expression": "", "background": "night", "next": "2-4-text-0483" },
    { "id": "2-4-text-0483", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "2-4-text-0484" },
    { "id": "2-4-text-0484", "type": "dialogue", "speaker": "我", "content": "嗯？", "expression": "", "background": "night", "next": "2-4-text-0485" },
    { "id": "2-4-text-0485", "type": "dialogue", "speaker": "皖萱", "content": "如果我以后回去天界了，还会想念这个味道吗？", "expression": "", "background": "night", "next": "2-4-text-0486" },
    { "id": "2-4-text-0486", "type": "narration", "speaker": "", "content": "我的筷子停住。", "expression": "", "background": "night", "next": "2-4-text-0487" },
    { "id": "2-4-text-0487", "type": "narration", "speaker": "", "content": "那是她第一次把“回去”这个词放到我们中间。", "expression": "", "background": "night", "next": "2-4-text-0488" },
    { "id": "2-4-text-0488", "type": "narration", "speaker": "", "content": "明明只是很轻的一句，像面汤表面浮起的一层热气，可它碰到皮肤时，还是会烫一下。", "expression": "", "background": "night", "next": "2-4-text-0489" },
    { "id": "2-4-text-0489", "type": "narration", "speaker": "", "content": "我低头看着碗里缓缓晃动的汤面，过了两秒才开口。", "expression": "", "background": "night", "next": "2-4-text-0490" },
    { "id": "2-4-text-0490", "type": "dialogue", "speaker": "我", "content": "应该会吧。", "expression": "", "background": "night", "next": "2-4-text-0491" },
    { "id": "2-4-text-0491", "type": "dialogue", "speaker": "皖萱", "content": "为什么？", "expression": "", "background": "night", "next": "2-4-text-0492" },
    { "id": "2-4-text-0492", "type": "dialogue", "speaker": "我", "content": "因为好吃的东西，本来就会让人记很久。", "expression": "", "background": "night", "next": "2-4-text-0493" },
    { "id": "2-4-text-0493", "type": "narration", "speaker": "", "content": "她没说话，像在认真思考这个答案够不够。", "expression": "", "background": "night", "next": "2-4-text-0494" },
    { "id": "2-4-text-0494", "type": "narration", "speaker": "", "content": "过了一会儿，她又轻声问：", "expression": "", "background": "night", "next": "2-4-text-0495" },
    { "id": "2-4-text-0495", "type": "dialogue", "speaker": "皖萱", "content": "那你呢？", "expression": "", "background": "night", "next": "2-4-text-0496" },
    { "id": "2-4-text-0496", "type": "narration", "speaker": "", "content": "如果以后吃到差不多的面，也会想起今晚吗？", "expression": "", "background": "night", "next": "2-4-text-0497" },
    { "id": "2-4-text-0497", "type": "narration", "speaker": "", "content": "厨房的灯很暖，照得她眼睛里那点光像被热气泡过，柔软得过分。", "expression": "", "background": "night", "next": "2-4-text-0498" },
    { "id": "2-4-text-0498", "type": "narration", "speaker": "", "content": "我本来可以随便回答一句“会吧”。", "expression": "", "background": "night", "next": "2-4-text-0499" },
    { "id": "2-4-text-0499", "type": "narration", "speaker": "", "content": "可也不知道为什么，那个瞬间，我没有糊弄过去。", "expression": "", "background": "night", "next": "2-4-text-0500" },
    { "id": "2-4-text-0500", "type": "dialogue", "speaker": "我", "content": "会。", "expression": "", "background": "night", "next": "2-4-text-0501" },
    { "id": "2-4-text-0501", "type": "narration", "speaker": "", "content": "她看着我。", "expression": "", "background": "night", "next": "2-4-text-0502" },
    { "id": "2-4-text-0502", "type": "dialogue", "speaker": "我", "content": "因为不是面的问题。", "expression": "", "background": "night", "next": "2-4-text-0503" },
    { "id": "2-4-text-0503", "type": "dialogue", "speaker": "皖萱", "content": "那是什么问题？", "expression": "", "background": "night", "next": "2-4-text-0504" },
    { "id": "2-4-text-0504", "type": "narration", "speaker": "", "content": "我张了张口。", "expression": "", "background": "night", "next": "2-4-text-0505" },
    { "id": "2-4-text-0505", "type": "narration", "speaker": "", "content": "有些话在脑子里时很模糊，真的要说出来，才知道原来它们已经在那里待了很久。", "expression": "", "background": "night", "next": "2-4-text-0506" },
    { "id": "2-4-text-0506", "type": "dialogue", "speaker": "我", "content": "因为是你陪我吃的。", "expression": "", "background": "night", "next": "2-4-text-0507" },
    { "id": "2-4-text-0507", "type": "narration", "speaker": "", "content": "空气像忽然静了一下。", "expression": "", "background": "night", "next": "2-4-text-0508" },
    { "id": "2-4-text-0508", "type": "narration", "speaker": "", "content": "她握着筷子的手慢慢收紧，耳尖一点一点红起来。", "expression": "", "background": "night", "next": "2-4-text-0509" },
    { "id": "2-4-text-0509", "type": "narration", "speaker": "", "content": "我说完才后知后觉地意识到，这句话几乎已经越过了“普通一起生活的室友”该有的边界。", "expression": "", "background": "night", "next": "2-4-text-0510" },
    { "id": "2-4-text-0510", "type": "narration", "speaker": "", "content": "可奇怪的是，我并不后悔。", "expression": "", "background": "night", "next": "2-4-text-0511" },
    { "id": "2-4-text-0511", "type": "narration", "speaker": "", "content": "她低下头，小口小口继续吃面，像在努力压住什么情绪。过了好一会儿，她才很轻地“嗯”了一声。", "expression": "", "background": "night", "next": "2-4-text-0512" },
    { "id": "2-4-text-0512", "type": "dialogue", "speaker": "皖萱", "content": "那我就放心了。", "expression": "", "background": "night", "next": "2-4-text-0513" },
    { "id": "2-4-text-0513", "type": "dialogue", "speaker": "我", "content": "放心什么？", "expression": "", "background": "night", "next": "2-4-text-0514" },
    { "id": "2-4-text-0514", "type": "narration", "speaker": "", "content": "她抬起头，对我笑。", "expression": "", "background": "night", "next": "2-4-text-0515" },
    { "id": "2-4-text-0515", "type": "narration", "speaker": "", "content": "那笑很浅，也很软，像夜里刚刚晾凉一点的汤面表面，还留着不会烫人的热。", "expression": "", "background": "night", "next": "2-4-text-0516" },
    { "id": "2-4-text-0516", "type": "dialogue", "speaker": "皖萱", "content": "说明我没有白来。", "expression": "", "background": "night", "next": "2-4-text-0517" },
    { "id": "2-4-text-0517", "type": "narration", "speaker": "", "content": "那一晚后来我们谁都没再提刚才那段对话。", "expression": "", "background": "night", "next": "2-4-text-0518" },
    { "id": "2-4-text-0518", "type": "narration", "speaker": "", "content": "只是把面安安静静吃完，又一前一后把锅和碗洗了。", "expression": "", "background": "night", "next": "2-4-text-0519" },
    { "id": "2-4-text-0519", "type": "narration", "speaker": "", "content": "可我回到房间躺下以后，鼻腔里还残留着面汤的热气，耳边也总像反复响起她那句“如果我以后回去天界了”。", "expression": "", "background": "night", "next": "2-4-text-0520" },
    { "id": "2-4-text-0520", "type": "narration", "speaker": "", "content": "我翻了个身，看着窗帘缝里渗进来的很淡的一点夜色，第一次清楚地意识到——", "expression": "", "background": "night", "next": "2-4-text-0521" },
    { "id": "2-4-text-0521", "type": "narration", "speaker": "", "content": "我已经开始害怕这个“三十天”的期限了。", "expression": "", "background": "night", "next": "2-5" },
    { "id": "2-5", "type": "marker", "markerTitle": "雨夜便利店与逐渐成形的依赖", "next": "2-5-text-0523" },
    { "id": "2-5-text-0523", "type": "narration", "speaker": "", "content": "又过了几天，家里的牛奶和鸡蛋见底。", "expression": "", "background": "night", "stageNote": "【场景】小区便利店 / 夜 / 雨后\n【BG】街灯、潮湿路面、便利店暖光\n【BGM】轻快中带一点柔软", "next": "2-5-text-0524" },
    { "id": "2-5-text-0524", "type": "narration", "speaker": "", "content": "晚上我准备出门去一趟便利店，刚拿起钥匙，皖萱就从沙发上抬起头。", "expression": "", "background": "night", "next": "2-5-text-0525" },
    { "id": "2-5-text-0525", "type": "dialogue", "speaker": "皖萱", "content": "你要去哪里？", "expression": "", "background": "night", "next": "2-5-text-0526" },
    { "id": "2-5-text-0526", "type": "dialogue", "speaker": "我", "content": "楼下便利店。", "expression": "", "background": "night", "next": "2-5-text-0527" },
    { "id": "2-5-text-0527", "type": "narration", "speaker": "", "content": "买点东西。", "expression": "", "background": "night", "next": "2-5-text-0528" },
    { "id": "2-5-text-0528", "type": "narration", "speaker": "", "content": "她眨了眨眼，立刻站起身。", "expression": "", "background": "night", "next": "2-5-text-0529" },
    { "id": "2-5-text-0529", "type": "dialogue", "speaker": "皖萱", "content": "我也去。", "expression": "", "background": "night", "next": "2-5-text-0530" },
    { "id": "2-5-text-0530", "type": "narration", "speaker": "", "content": "雨刚停。", "expression": "", "background": "night", "next": "2-5-text-0531" },
    { "id": "2-5-text-0531", "type": "narration", "speaker": "", "content": "楼下的路面还湿，街灯照上去，像在黑色地砖上薄薄铺了一层金。空气里有雨后的凉，夹着一点草木和潮土的气味。皖萱走在我旁边，步子不快，时不时低头看那些积在路边的小水洼。", "expression": "", "background": "night", "next": "2-5-text-0532" },
    { "id": "2-5-text-0532", "type": "narration", "speaker": "", "content": "便利店门一推开，熟悉的冷气和食物香就一起涌出来。", "expression": "", "background": "night", "next": "2-5-text-0533" },
    { "id": "2-5-text-0533", "type": "narration", "speaker": "", "content": "加热柜里关东煮正咕嘟咕嘟冒泡，萝卜和鱼丸在浅色汤底里浮沉，玻璃柜门上结着一层淡雾。面包区有刚补货的菠萝包，空气里混着一点甜甜的奶香。咖啡机运作时发出低低的机械声，像这座城市夜里最普通也最可靠的呼吸。", "expression": "", "background": "night", "next": "2-5-text-0534" },
    { "id": "2-5-text-0534", "type": "narration", "speaker": "", "content": "皖萱站在门口，像被一整个小型幸福生态圈包围住了。", "expression": "", "background": "night", "next": "2-5-text-0535" },
    { "id": "2-5-text-0535", "type": "dialogue", "speaker": "皖萱", "content": "这里也很厉害。", "expression": "", "background": "night", "next": "2-5-text-0536" },
    { "id": "2-5-text-0536", "type": "dialogue", "speaker": "我", "content": "便利店而已。", "expression": "", "background": "night", "next": "2-5-text-0537" },
    { "id": "2-5-text-0537", "type": "dialogue", "speaker": "皖萱", "content": "“而已”这个词，你总是用得太轻了。", "expression": "", "background": "night", "next": "2-5-text-0538" },
    { "id": "2-5-text-0538", "type": "narration", "speaker": "", "content": "她说完，就被加热柜吸引过去了。", "expression": "", "background": "night", "next": "2-5-text-0539" },
    { "id": "2-5-text-0539", "type": "narration", "speaker": "", "content": "她盯着关东煮看了很久。", "expression": "", "background": "night", "next": "2-5-text-0540" },
    { "id": "2-5-text-0540", "type": "narration", "speaker": "", "content": "萝卜炖得半透明，边角圆润，吸饱了汤汁，连颜色都比原本深了一点。鱼豆腐表面鼓鼓的，白萝卜旁边还漂着海带结，汤面上升起的蒸汽里有很淡的柴鱼和酱油香。", "expression": "", "background": "night", "next": "2-5-text-0541" },
    { "id": "2-5-text-0541", "type": "dialogue", "speaker": "皖萱", "content": "这个闻起来像晚上会原谅人的味道。", "expression": "", "background": "night", "next": "2-5-text-0542" },
    { "id": "2-5-text-0542", "type": "narration", "speaker": "", "content": "我转头看她。", "expression": "", "background": "night", "next": "2-5-text-0543" },
    { "id": "2-5-text-0543", "type": "dialogue", "speaker": "我", "content": "你最近的形容越来越离谱了。", "expression": "", "background": "night", "next": "2-5-text-0544" },
    { "id": "2-5-text-0544", "type": "dialogue", "speaker": "皖萱", "content": "那你要不要试试被原谅一下？", "expression": "", "background": "night", "next": "2-5-text-0545" },
    { "id": "2-5-text-0545", "type": "narration", "speaker": "", "content": "最后牛奶、鸡蛋、吐司之外，我们又多买了一杯热关东煮、一只菠萝包，还有两支冰淇淋。", "expression": "", "background": "night", "next": "2-5-text-0546" },
    { "id": "2-5-text-0546", "type": "narration", "speaker": "", "content": "理由是“研究样本不能太单一”。", "expression": "", "background": "night", "next": "2-5-text-0547" },
    { "id": "2-5-text-0547", "type": "narration", "speaker": "", "content": "我们没有立刻回家，而是在便利店外面的长椅上坐了会儿。", "expression": "", "background": "night", "next": "2-5-text-0548" },
    { "id": "2-5-text-0548", "type": "narration", "speaker": "", "content": "夜风里还带着一点潮，塑料勺伸进纸杯里时，能感觉到汤底的热透过杯壁慢慢往掌心里渗。", "expression": "", "background": "night", "next": "2-5-text-0549" },
    { "id": "2-5-text-0549", "type": "narration", "speaker": "", "content": "皖萱先咬了一口萝卜。", "expression": "", "background": "night", "next": "2-5-text-0550" },
    { "id": "2-5-text-0550", "type": "narration", "speaker": "", "content": "炖透的萝卜几乎不需要用力，牙齿一碰就散，里面全是热汤。它本身几乎没有棱角，只剩下被高汤慢慢煨进身体里的鲜和一点微微的甜。热气从舌尖一直滚到喉咙，很慢，却很稳。", "expression": "", "background": "night", "next": "2-5-text-0551" },
    { "id": "2-5-text-0551", "type": "dialogue", "speaker": "皖萱", "content": "真的会原谅人。", "expression": "", "background": "night", "next": "2-5-text-0552" },
    { "id": "2-5-text-0552", "type": "dialogue", "speaker": "我", "content": "为什么是“原谅”？", "expression": "", "background": "night", "next": "2-5-text-0553" },
    { "id": "2-5-text-0553", "type": "dialogue", "speaker": "皖萱", "content": "因为白天不管过得多乱，晚上吃到这个，就会觉得“算了，也没有那么糟”。", "expression": "", "background": "night", "next": "2-5-text-0554" },
    { "id": "2-5-text-0554", "type": "narration", "speaker": "", "content": "我低头喝了一口汤。", "expression": "", "background": "night", "next": "2-5-text-0555" },
    { "id": "2-5-text-0555", "type": "narration", "speaker": "", "content": "咸淡正好，暖意贴着胃一路往下，确实很像一种缓慢的安抚。", "expression": "", "background": "night", "next": "2-5-text-0556" },
    { "id": "2-5-text-0556", "type": "narration", "speaker": "", "content": "长椅边的地面还没完全干，一点一点映着店里的白光。人偶尔从旁边路过，脚步都很匆忙。可我们坐在那里，捧着一杯便宜却很热的关东煮，时间忽然慢了很多。", "expression": "", "background": "night", "next": "2-5-text-0557" },
    { "id": "2-5-text-0557", "type": "narration", "speaker": "", "content": "皖萱舔了一下勺尖沾到的汤，忽然转头看我。", "expression": "", "background": "night", "next": "2-5-text-0558" },
    { "id": "2-5-text-0558", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "2-5-text-0559" },
    { "id": "2-5-text-0559", "type": "dialogue", "speaker": "我", "content": "嗯？", "expression": "", "background": "night", "next": "2-5-text-0560" },
    { "id": "2-5-text-0560", "type": "dialogue", "speaker": "皖萱", "content": "如果有一天，我不在这里了。", "expression": "", "background": "night", "next": "2-5-text-0561" },
    { "id": "2-5-text-0561", "type": "narration", "speaker": "", "content": "你还会不会自己下来买这个？", "expression": "", "background": "night", "next": "2-5-text-0562" },
    { "id": "2-5-text-0562", "type": "narration", "speaker": "", "content": "又来了。", "expression": "", "background": "night", "next": "2-5-text-0563" },
    { "id": "2-5-text-0563", "type": "narration", "speaker": "", "content": "她近来总会在某些安静得过分的时候，把“离开”轻轻摆到我面前。", "expression": "", "background": "night", "next": "2-5-text-0564" },
    { "id": "2-5-text-0564", "type": "narration", "speaker": "", "content": "像在试探，也像在提前练习告别。", "expression": "", "background": "night", "next": "2-5-text-0565" },
    { "id": "2-5-text-0565", "type": "narration", "speaker": "", "content": "我看着纸杯里缓缓晃开的热汤，过了片刻才回答。", "expression": "", "background": "night", "next": "2-5-text-0566" },
    { "id": "2-5-text-0566", "type": "dialogue", "speaker": "我", "content": "会买。", "expression": "", "background": "night", "next": "2-5-text-0567" },
    { "id": "2-5-text-0567", "type": "narration", "speaker": "", "content": "她安静地等我说完。", "expression": "", "background": "night", "next": "2-5-text-0568" },
    { "id": "2-5-text-0568", "type": "dialogue", "speaker": "我", "content": "但大概不会坐在这里慢慢吃。", "expression": "", "background": "night", "next": "2-5-text-0569" },
    { "id": "2-5-text-0569", "type": "narration", "speaker": "", "content": "她的睫毛轻轻颤了一下。", "expression": "", "background": "night", "next": "2-5-text-0570" },
    { "id": "2-5-text-0570", "type": "dialogue", "speaker": "皖萱", "content": "为什么？", "expression": "", "background": "night", "next": "2-5-text-0571" },
    { "id": "2-5-text-0571", "type": "dialogue", "speaker": "我", "content": "因为一个人坐着的时候，热的东西凉得会比较快。", "expression": "", "background": "night", "next": "2-5-text-0572" },
    { "id": "2-5-text-0572", "type": "narration", "speaker": "", "content": "她望着我，很久没说话。", "expression": "", "background": "night", "next": "2-5-text-0573" },
    { "id": "2-5-text-0573", "type": "narration", "speaker": "", "content": "夜风吹起她耳侧一点碎发，便利店的暖光落进她眼睛里，把那层一向干净的光照得有些潮。", "expression": "", "background": "night", "next": "2-5-text-0574" },
    { "id": "2-5-text-0574", "type": "narration", "speaker": "", "content": "最后，她把纸杯往我这边推了一点。", "expression": "", "background": "night", "next": "2-5-text-0575" },
    { "id": "2-5-text-0575", "type": "dialogue", "speaker": "皖萱", "content": "那你再多吃一块。", "expression": "", "background": "night", "next": "2-5-text-0576" },
    { "id": "2-5-text-0576", "type": "dialogue", "speaker": "我", "content": "什么逻辑？", "expression": "", "background": "night", "next": "2-5-text-0577" },
    { "id": "2-5-text-0577", "type": "dialogue", "speaker": "皖萱", "content": "趁我还在，先把“会一起坐着吃”的份额补足一点。", "expression": "", "background": "night", "next": "2-5-text-0578" },
    { "id": "2-5-text-0578", "type": "narration", "speaker": "", "content": "我怔了一下，忽然说不出话。", "expression": "", "background": "night", "next": "2-5-text-0579" },
    { "id": "2-5-text-0579", "type": "narration", "speaker": "", "content": "于是我真的又夹了一块鱼豆腐。", "expression": "", "background": "night", "next": "2-5-text-0580" },
    { "id": "2-5-text-0580", "type": "narration", "speaker": "", "content": "鱼豆腐吸了汤，比看上去更热一点。表面柔软，里面却还有一点弹，豆香和鱼浆的鲜味混在一起，并不复杂，却很踏实。", "expression": "", "background": "night", "next": "2-5-text-0581" },
    { "id": "2-5-text-0581", "type": "narration", "speaker": "", "content": "皖萱看着我吃，忽然笑了。", "expression": "", "background": "night", "next": "2-5-text-0582" },
    { "id": "2-5-text-0582", "type": "narration", "speaker": "", "content": "那笑和第一次吃草莓蛋糕时不一样，也和吃炸鸡、喝奶茶时的兴奋不同。", "expression": "", "background": "night", "next": "2-5-text-0583" },
    { "id": "2-5-text-0583", "type": "narration", "speaker": "", "content": "它更安静一点，像已经不再只是“食物真好吃”，而是“原来和你一起吃这些，真的会让我舍不得”。", "expression": "", "background": "night", "next": "2-5-text-0584" },
    { "id": "2-5-text-0584", "type": "narration", "speaker": "", "content": "回去的路上，她的步子放得很慢。", "expression": "", "background": "night", "next": "2-5-text-0585" },
    { "id": "2-5-text-0585", "type": "narration", "speaker": "", "content": "走到楼下时，她忽然很自然地抓住了我的袖口。", "expression": "", "background": "night", "next": "2-5-text-0586" },
    { "id": "2-5-text-0586", "type": "narration", "speaker": "", "content": "动作很轻，几乎不像要拉住谁，更像只是给自己找一个顺手的支点。", "expression": "", "background": "night", "next": "2-5-text-0587" },
    { "id": "2-5-text-0587", "type": "narration", "speaker": "", "content": "我低头看了一眼。", "expression": "", "background": "night", "next": "2-5-text-0588" },
    { "id": "2-5-text-0588", "type": "narration", "speaker": "", "content": "她像是意识到什么，想松开，却又停住。", "expression": "", "background": "night", "next": "2-5-text-0589" },
    { "id": "2-5-text-0589", "type": "dialogue", "speaker": "皖萱", "content": "地有点滑。", "expression": "", "background": "night", "next": "2-5-text-0590" },
    { "id": "2-5-text-0590", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "2-5-text-0591" },
    { "id": "2-5-text-0591", "type": "narration", "speaker": "", "content": "我没有拆穿，只是放慢了脚步。", "expression": "", "background": "night", "next": "2-5-text-0592" },
    { "id": "2-5-text-0592", "type": "narration", "speaker": "", "content": "那一点布料被牵住的触感很轻。", "expression": "", "background": "night", "next": "2-5-text-0593" },
    { "id": "2-5-text-0593", "type": "narration", "speaker": "", "content": "可我却觉得，自己心里某个原本一直悬着的地方，也被她这样轻轻拉住了一下。", "expression": "", "background": "night", "next": "2-6" },
    { "id": "2-6", "type": "marker", "markerTitle": "第二幕收束：被悄悄改写的日常", "next": "2-6-text-0595" },
    { "id": "2-6-text-0595", "type": "narration", "speaker": "", "content": "——冰箱门上多出一张张便签，字迹一开始工整得过分，后来慢慢掺进一点随手写下的小抱怨。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 连续蒙太奇\n【演出】多个日常片段快速切换", "next": "2-6-text-0596" },
    { "id": "2-6-text-0596", "type": "narration", "speaker": "", "content": "“牛奶要补。”", "expression": "", "background": "night", "next": "2-6-text-0597" },
    { "id": "2-6-text-0597", "type": "narration", "speaker": "", "content": "“草莓很好吃，可以再买。”", "expression": "", "background": "night", "next": "2-6-text-0598" },
    { "id": "2-6-text-0598", "type": "narration", "speaker": "", "content": "“不要把布丁藏在蔬菜后面，我已经发现了。”", "expression": "", "background": "night", "next": "2-6-text-0599" },
    { "id": "2-6-text-0599", "type": "narration", "speaker": "", "content": "——她学会了用手机点单，却还是会在付款前举着屏幕问我：“这个算不算太贪心？”", "expression": "", "background": "night", "next": "2-6-text-0600" },
    { "id": "2-6-text-0600", "type": "narration", "speaker": "", "content": "——我工作时，她抱着零食坐在旁边，小口小口啃曲奇，偶尔把一块递到我唇边，理直气壮地说“补充脑力”。", "expression": "", "background": "night", "next": "2-6-text-0601" },
    { "id": "2-6-text-0601", "type": "narration", "speaker": "", "content": "——晚上一起整理购物袋，她会把冰箱里的东西分门别类摆好，然后对着满满当当的冷藏层露出一种近乎满足的表情。", "expression": "", "background": "night", "next": "2-6-text-0602" },
    { "id": "2-6-text-0602", "type": "narration", "speaker": "", "content": "——某个晴天，她站在阳台给多肉浇水。水珠落在叶片上，阳光照过去，像一串很小的玻璃珠。她回头叫我看，我竟然真的停下手里的事走过去，只为了看那几滴水。", "expression": "", "background": "night", "next": "2-6-text-0603" },
    { "id": "2-6-text-0603", "type": "narration", "speaker": "", "content": "——有时候她会在我起晚的清晨先热好牛奶，有时候我会在她午睡醒来前把甜点切成正好入口的小块。", "expression": "", "background": "night", "next": "2-6-text-0604" },
    { "id": "2-6-text-0604", "type": "narration", "speaker": "", "content": "这些事都很小。", "expression": "", "background": "night", "next": "2-6-text-0605" },
    { "id": "2-6-text-0605", "type": "narration", "speaker": "", "content": "小到放进任何一段叙事里，都像可有可无的边角。", "expression": "", "background": "night", "next": "2-6-text-0606" },
    { "id": "2-6-text-0606", "type": "narration", "speaker": "", "content": "可正是这些边角，慢慢把我的生活改写成了另一种样子。", "expression": "", "background": "night", "next": "2-6-text-0607" },
    { "id": "2-6-text-0607", "type": "narration", "speaker": "", "content": "以前的我，习惯了一个人解决一切。", "expression": "", "background": "night", "next": "2-6-text-0608" },
    { "id": "2-6-text-0608", "type": "narration", "speaker": "", "content": "饿了就吃，困了就睡，忙完就沉默着把一天收好。没有谁会等我坐下吃饭，也没有谁会对着冰箱里的最后一盒布丁认真犹豫要不要留给我。", "expression": "", "background": "night", "next": "2-6-text-0609" },
    { "id": "2-6-text-0609", "type": "narration", "speaker": "", "content": "可现在，连“回家”这个动作都有了更清楚的意义。", "expression": "", "background": "night", "next": "2-6-text-0610" },
    { "id": "2-6-text-0610", "type": "narration", "speaker": "", "content": "因为我知道，门后面多半会有灯。", "expression": "", "background": "night", "next": "2-6-text-0611" },
    { "id": "2-6-text-0611", "type": "narration", "speaker": "", "content": "有时还有食物的香气。", "expression": "", "background": "night", "next": "2-6-text-0612" },
    { "id": "2-6-text-0612", "type": "narration", "speaker": "", "content": "以及一个会在看见我时抬起头、很自然地问一句“今天累不累”的人。", "expression": "", "background": "night", "next": "2-6-text-0613" },
    { "id": "2-6-text-0613", "type": "narration", "speaker": "", "content": "我后来才明白，所谓依赖，并不总是在某个瞬间轰然降临。", "expression": "", "background": "night", "next": "2-6-text-0614" },
    { "id": "2-6-text-0614", "type": "narration", "speaker": "", "content": "它更像是被一餐一饭、一日一夜慢慢熬出来的。", "expression": "", "background": "night", "next": "2-6-text-0615" },
    { "id": "2-6-text-0615", "type": "narration", "speaker": "", "content": "像汤，小火，时间久了，就会有味道。", "expression": "", "background": "night", "next": "2-6-text-0616" },
    { "id": "2-6-text-0616", "type": "narration", "speaker": "", "content": "第二幕到这里，天界召回的影子还没有真正落下来。", "expression": "", "background": "night", "next": "2-6-text-0617" },
    { "id": "2-6-text-0617", "type": "narration", "speaker": "", "content": "可我已经在那些过分平静、过分温柔的日常里，隐约听见了某种倒计时。", "expression": "", "background": "night", "next": "2-6-text-0618" },
    { "id": "2-6-text-0618", "type": "narration", "speaker": "", "content": "因为越是习惯，越会害怕失去。", "expression": "", "background": "night", "next": "2-6-text-0619" },
    { "id": "2-6-text-0619", "type": "narration", "speaker": "", "content": "而越是幸福，越会明白“幸福为什么让人想留住”。", "expression": "", "background": "night", "next": "第三幕-交汇——来自-Yui-的深夜电波" },
    { "id": "第三幕-交汇——来自-Yui-的深夜电波", "type": "marker", "markerTitle": "第三幕：交汇——来自 Yui 的深夜电波", "next": "3-1" },
    { "id": "3-1", "type": "marker", "markerTitle": "温度最高的那个夜晚", "next": "3-1-text-0622" },
    { "id": "3-1-text-0622", "type": "narration", "speaker": "", "content": "进入六月以后，夜晚开始有了些初夏的味道。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 深夜 / 初夏\n【BG】夜色中的客厅，茶几上有夜宵，电视微亮\n【BGM】前段无，后段转为微妙的电子氛围", "next": "3-1-text-0623" },
    { "id": "3-1-text-0623", "type": "narration", "speaker": "", "content": "窗没关严，风从缝隙里一点点钻进来，带着很淡的草木热气和城市深夜特有的空旷。空调开得不低，厨房里刚煮好的乌冬面却还在往上冒热。", "expression": "", "background": "night", "next": "3-1-text-0624" },
    { "id": "3-1-text-0624", "type": "narration", "speaker": "", "content": "那天晚上本来没什么特别。", "expression": "", "background": "night", "next": "3-1-text-0625" },
    { "id": "3-1-text-0625", "type": "narration", "speaker": "", "content": "我把工作收尾得比平时早一些，皖萱则因为下午多吃了一份抹茶千层，晚餐时难得表现出一点“反省中的克制”，只喝了半碗汤，结果到十一点多就开始盯着冰箱发呆。", "expression": "", "background": "night", "next": "3-1-text-0626" },
    { "id": "3-1-text-0626", "type": "narration", "speaker": "", "content": "我站在她身后，看她一脸严肃地拉开冰箱门，又缓慢关上。", "expression": "", "background": "night", "next": "3-1-text-0627" },
    { "id": "3-1-text-0627", "type": "dialogue", "speaker": "我", "content": "你这样看，它也不会自己变出夜宵。", "expression": "", "background": "night", "next": "3-1-text-0628" },
    { "id": "3-1-text-0628", "type": "dialogue", "speaker": "皖萱", "content": "我是在给它压力。", "expression": "", "background": "night", "next": "3-1-text-0629" },
    { "id": "3-1-text-0629", "type": "dialogue", "speaker": "我", "content": "有用吗？", "expression": "", "background": "night", "next": "3-1-text-0630" },
    { "id": "3-1-text-0630", "type": "dialogue", "speaker": "皖萱", "content": "暂时没有。", "expression": "", "background": "night", "next": "3-1-text-0631" },
    { "id": "3-1-text-0631", "type": "narration", "speaker": "", "content": "我没忍住笑，最后还是从冷冻层里翻出两包乌冬面，又切了点火腿和香菇，顺手打了一个溏心蛋。", "expression": "", "background": "night", "next": "3-1-text-0632" },
    { "id": "3-1-text-0632", "type": "narration", "speaker": "", "content": "汤底很简单。", "expression": "", "background": "night", "next": "3-1-text-0633" },
    { "id": "3-1-text-0633", "type": "narration", "speaker": "", "content": "木鱼花高汤，加一点酱油和味醂。可越是简单的东西，越容易在深夜显出温柔。锅滚起来的时候，空气里先有一股很淡的鲜，像水本身忽然被赋予了性格。香菇一煮软，气味就沉了一层；火腿片下锅后浮起来一点肉香，最后把面放进去，整间厨房都被那种湿润而安静的热气填满。", "expression": "", "background": "night", "next": "3-1-text-0634" },
    { "id": "3-1-text-0634", "type": "narration", "speaker": "", "content": "皖萱站在旁边，像值夜班一样认真守着锅。", "expression": "", "background": "night", "next": "3-1-text-0635" },
    { "id": "3-1-text-0635", "type": "dialogue", "speaker": "皖萱", "content": "我发现，夜宵和正餐是不一样的。", "expression": "", "background": "night", "next": "3-1-text-0636" },
    { "id": "3-1-text-0636", "type": "dialogue", "speaker": "我", "content": "哪里不一样？", "expression": "", "background": "night", "next": "3-1-text-0637" },
    { "id": "3-1-text-0637", "type": "dialogue", "speaker": "皖萱", "content": "正餐像约定。夜宵像偏爱。", "expression": "", "background": "night", "next": "3-1-text-0638" },
    { "id": "3-1-text-0638", "type": "narration", "speaker": "", "content": "我的动作停了一下。", "expression": "", "background": "night", "next": "3-1-text-0639" },
    { "id": "3-1-text-0639", "type": "dialogue", "speaker": "我", "content": "这个结论挺厉害。", "expression": "", "background": "night", "next": "3-1-text-0640" },
    { "id": "3-1-text-0640", "type": "dialogue", "speaker": "皖萱", "content": "因为正餐本来就应该吃。", "expression": "", "background": "night", "next": "3-1-text-0641" },
    { "id": "3-1-text-0641", "type": "narration", "speaker": "", "content": "但夜里还愿意为了一个人开灯、烧水、等锅开——", "expression": "", "background": "night", "next": "3-1-text-0642" },
    { "id": "3-1-text-0642", "type": "narration", "speaker": "", "content": "她说到这里，看了我一眼。", "expression": "", "background": "night", "next": "3-1-text-0643" },
    { "id": "3-1-text-0643", "type": "dialogue", "speaker": "皖萱", "content": "这个比较像“我想让你现在过得好一点”。", "expression": "", "background": "night", "next": "3-1-text-0644" },
    { "id": "3-1-text-0644", "type": "narration", "speaker": "", "content": "我低头把面捞进碗里，没有立刻接话。", "expression": "", "background": "night", "next": "3-1-text-0645" },
    { "id": "3-1-text-0645", "type": "narration", "speaker": "", "content": "有些话她说出来，总像无意。", "expression": "", "background": "night", "next": "3-1-text-0646" },
    { "id": "3-1-text-0646", "type": "narration", "speaker": "", "content": "可越是无意，越让人没法装作听不懂。", "expression": "", "background": "night", "next": "3-1-text-0647" },
    { "id": "3-1-text-0647", "type": "narration", "speaker": "", "content": "我们把乌冬面端到客厅。", "expression": "", "background": "night", "next": "3-1-text-0648" },
    { "id": "3-1-text-0648", "type": "narration", "speaker": "", "content": "茶几被临时征用成小餐桌，两只碗并排放着，热气把电视屏幕下方映得有点模糊。面条浸在浅褐色汤里，表面浮着葱花，溏心蛋切开后，半凝的蛋黄正缓缓往外流。香菇吸了汤汁，颜色比刚下锅时更深，火腿边缘微卷，像被夜色烫出了一圈柔软。", "expression": "", "background": "night", "next": "3-1-text-0649" },
    { "id": "3-1-text-0649", "type": "narration", "speaker": "", "content": "皖萱先喝了口汤。", "expression": "", "background": "night", "next": "3-1-text-0650" },
    { "id": "3-1-text-0650", "type": "narration", "speaker": "", "content": "她眼睛一下子就柔下来了。", "expression": "", "background": "night", "next": "3-1-text-0651" },
    { "id": "3-1-text-0651", "type": "dialogue", "speaker": "皖萱", "content": "这个像夜里有人替你把被子盖好。", "expression": "", "background": "night", "next": "3-1-text-0652" },
    { "id": "3-1-text-0652", "type": "dialogue", "speaker": "我", "content": "你现在已经完全不正常形容食物了。", "expression": "", "background": "night", "next": "3-1-text-0653" },
    { "id": "3-1-text-0653", "type": "dialogue", "speaker": "皖萱", "content": "可是它真的很像。", "expression": "", "background": "night", "next": "3-1-text-0654" },
    { "id": "3-1-text-0654", "type": "narration", "speaker": "", "content": "她低头咬面。", "expression": "", "background": "night", "next": "3-1-text-0655" },
    { "id": "3-1-text-0655", "type": "narration", "speaker": "", "content": "乌冬面比普通挂面更厚，更弹，牙齿咬下去会有很实在的回馈。热汤包着面身一起滑进口中，木鱼和酱油的鲜味不张扬，只是稳稳垫在底下，给每一口都托住一个柔和的收尾。蛋黄则把整个味道裹得更圆润，像月光里被泡软的一点金。", "expression": "", "background": "night", "next": "3-1-text-0656" },
    { "id": "3-1-text-0656", "type": "narration", "speaker": "", "content": "她吃得很认真，也很慢。", "expression": "", "background": "night", "next": "3-1-text-0657" },
    { "id": "3-1-text-0657", "type": "narration", "speaker": "", "content": "而我看着她，忽然有一种很奇怪的感觉。", "expression": "", "background": "night", "next": "3-1-text-0658" },
    { "id": "3-1-text-0658", "type": "narration", "speaker": "", "content": "不是“这样的夜宵真好吃”。", "expression": "", "background": "night", "next": "3-1-text-0659" },
    { "id": "3-1-text-0659", "type": "narration", "speaker": "", "content": "而是“如果这一刻能够停久一点就好了”。", "expression": "", "background": "night", "next": "3-1-text-0660" },
    { "id": "3-1-text-0660", "type": "narration", "speaker": "", "content": "这念头刚冒出来，我就有些无奈地意识到，自己最近越来越像在偷时间过日子。", "expression": "", "background": "night", "next": "3-1-text-0661" },
    { "id": "3-1-text-0661", "type": "narration", "speaker": "", "content": "像明知道假期会结束的人，偏偏在每一个平常时刻里都尝出一点倒数的味道。", "expression": "", "background": "night", "next": "3-1-text-0662" },
    { "id": "3-1-text-0662", "type": "narration", "speaker": "", "content": "皖萱吃到一半，抬头看我。", "expression": "", "background": "night", "next": "3-1-text-0663" },
    { "id": "3-1-text-0663", "type": "dialogue", "speaker": "皖萱", "content": "你今天有点安静。", "expression": "", "background": "night", "next": "3-1-text-0664" },
    { "id": "3-1-text-0664", "type": "dialogue", "speaker": "我", "content": "我平时也不算吵吧。", "expression": "", "background": "night", "next": "3-1-text-0665" },
    { "id": "3-1-text-0665", "type": "dialogue", "speaker": "皖萱", "content": "不一样。", "expression": "", "background": "night", "next": "3-1-text-0666" },
    { "id": "3-1-text-0666", "type": "narration", "speaker": "", "content": "今天的安静像有事。", "expression": "", "background": "night", "next": "3-1-text-0667" },
    { "id": "3-1-text-0667", "type": "narration", "speaker": "", "content": "我笑了笑。", "expression": "", "background": "night", "next": "3-1-text-0668" },
    { "id": "3-1-text-0668", "type": "dialogue", "speaker": "我", "content": "你这个观察能力，放在别的地方也挺厉害。", "expression": "", "background": "night", "next": "3-1-text-0669" },
    { "id": "3-1-text-0669", "type": "dialogue", "speaker": "皖萱", "content": "所以我才是实习天使。", "expression": "", "background": "night", "next": "3-1-text-0670" },
    { "id": "3-1-text-0670", "type": "narration", "speaker": "", "content": "她说完，又低头吸了一口面，热气把她睫毛都熏得有些湿。", "expression": "", "background": "night", "next": "3-1-text-0671" },
    { "id": "3-1-text-0671", "type": "narration", "speaker": "", "content": "我看着她，还是没把那句“我只是突然在想，你还能在这里待多久”说出口。", "expression": "", "background": "night", "next": "3-1-text-0672" },
    { "id": "3-1-text-0672", "type": "narration", "speaker": "", "content": "因为那样太像把快乐提前弄坏。", "expression": "", "background": "night", "next": "3-1-text-0673" },
    { "id": "3-1-text-0673", "type": "narration", "speaker": "", "content": "而我现在，竟然已经开始舍不得去碰任何可能让她露出难过表情的话题。", "expression": "", "background": "night", "next": "3-1-text-0674" },
    { "id": "3-1-text-0674", "type": "narration", "speaker": "", "content": "夜很深。", "expression": "", "background": "night", "next": "3-1-text-0675" },
    { "id": "3-1-text-0675", "type": "narration", "speaker": "", "content": "茶几上只亮着一盏小灯，乌冬面的热气和客厅里柔软的暗交叠在一起，像把整个房间包进了一层只属于深夜的壳。外面偶尔有车声远远划过去，又很快沉下去。安静里只剩筷子碰碗沿的轻响，还有她小口喝汤时几乎听不见的呼吸。", "expression": "", "background": "night", "next": "3-1-text-0676" },
    { "id": "3-1-text-0676", "type": "narration", "speaker": "", "content": "那大概是皖萱来到这里以后，我们最靠近“平凡夫妻夜宵”的一个夜晚。", "expression": "", "background": "night", "next": "3-1-text-0677" },
    { "id": "3-1-text-0677", "type": "narration", "speaker": "", "content": "也正因为太平凡，太温暖，后来想起来时，才会显得格外像某种命运在拐弯之前，故意给出的缓冲。", "expression": "", "background": "night", "next": "3-2" },
    { "id": "3-2", "type": "marker", "markerTitle": "被随手打开的直播", "next": "3-2-text-0679" },
    { "id": "3-2-text-0679", "type": "narration", "speaker": "", "content": "面吃到差不多的时候，皖萱已经明显进入了那种“幸福过量后的迟钝状态”。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 深夜延续\n【演出】乌冬面快吃完，气氛慵懒，电视成为第三视角", "next": "3-2-text-0680" },
    { "id": "3-2-text-0680", "type": "narration", "speaker": "", "content": "她抱着靠枕，半靠在沙发一角，脚尖缩在裙摆下面，整个人都像被热汤泡软了。", "expression": "", "background": "night", "next": "3-2-text-0681" },
    { "id": "3-2-text-0681", "type": "narration", "speaker": "", "content": "我收了碗筷回来时，她正盯着电视黑掉的屏幕发呆。", "expression": "", "background": "night", "next": "3-2-text-0682" },
    { "id": "3-2-text-0682", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "3-2-text-0683" },
    { "id": "3-2-text-0683", "type": "dialogue", "speaker": "我", "content": "嗯？", "expression": "", "background": "night", "next": "3-2-text-0684" },
    { "id": "3-2-text-0684", "type": "dialogue", "speaker": "皖萱", "content": "你们晚上吃完夜宵之后，一般还会做什么？", "expression": "", "background": "night", "next": "3-2-text-0685" },
    { "id": "3-2-text-0685", "type": "dialogue", "speaker": "我", "content": "看会儿东西，或者直接睡。", "expression": "", "background": "night", "next": "3-2-text-0686" },
    { "id": "3-2-text-0686", "type": "dialogue", "speaker": "皖萱", "content": "那今天看会儿东西吧。", "expression": "", "background": "night", "next": "3-2-text-0687" },
    { "id": "3-2-text-0687", "type": "narration", "speaker": "", "content": "我拿起遥控器，随手开了电视。", "expression": "", "background": "night", "next": "3-2-text-0688" },
    { "id": "3-2-text-0688", "type": "narration", "speaker": "", "content": "屏幕亮起的一瞬间，客厅的暗被切开一点，彩色的光轻轻落在她脸上。首页推送滑过去时，她看什么都新鲜，连广告都能盯上几秒。我本来只是想找个轻松综艺放着当背景音，手指却不知怎么划进了直播区。", "expression": "", "background": "night", "next": "3-2-text-0689" },
    { "id": "3-2-text-0689", "type": "narration", "speaker": "", "content": "大概是平台首页推荐。", "expression": "", "background": "night", "next": "3-2-text-0690" },
    { "id": "3-2-text-0690", "type": "narration", "speaker": "", "content": "一个粉白配色的封面正卡在最显眼的位置，标题写着：", "expression": "", "background": "night", "next": "3-2-text-0691" },
    { "id": "3-2-text-0691", "type": "narration", "speaker": "", "content": "我没多想，随手点了进去。", "expression": "", "background": "night", "stageNote": "【Yui 夜间奇迹杂谈】睡不着的人，来这里领取一点未来吧~", "next": "3-2-text-0692" },
    { "id": "3-2-text-0692", "type": "narration", "speaker": "", "content": "直播画面打开。", "expression": "", "background": "night", "next": "3-2-text-0693" },
    { "id": "3-2-text-0693", "type": "narration", "speaker": "", "content": "屏幕里的少女有着过分鲜明的存在感。", "expression": "", "background": "night", "next": "3-2-text-0694" },
    { "id": "3-2-text-0694", "type": "narration", "speaker": "", "content": "她的头发带着一点不真实的亮泽，发尾像沾了星屑，眼睛大而灵动，笑起来时像故意把整个画面都点亮。她穿着风格夸张却不惹人厌的舞台感服装，耳边挂着小小的装饰星星，背景则像漂浮在霓虹和夜空中间的电子房间。", "expression": "", "background": "night", "next": "3-2-text-0695" },
    { "id": "3-2-text-0695", "type": "narration", "speaker": "", "content": "她正在和弹幕聊天。", "expression": "", "background": "night", "next": "3-2-text-0696" },
    { "id": "3-2-text-0696", "type": "narration", "speaker": "", "content": "语速很快，尾音带一点俏皮的上扬，明明是对着镜头说话，却有种她随时会从屏幕里跳出来敲你脑门的生动。", "expression": "", "background": "night", "next": "3-2-text-0697" },
    { "id": "3-2-text-0697", "type": "dialogue", "speaker": "Yui", "content": "晚上好晚上好——还没睡的大家，都是在和明天做一点点温柔的对抗吧？", "expression": "", "background": "night", "next": "3-2-text-0698" },
    { "id": "3-2-text-0698", "type": "narration", "speaker": "", "content": "来，让我看看今天谁最需要奇迹加班——", "expression": "", "background": "night", "next": "3-2-text-0699" },
    { "id": "3-2-text-0699", "type": "narration", "speaker": "", "content": "弹幕飞快滚动。", "expression": "", "background": "night", "next": "3-2-text-0700" },
    { "id": "3-2-text-0700", "type": "narration", "speaker": "", "content": "皖萱显然被这种信息密度震了一下。", "expression": "", "background": "night", "next": "3-2-text-0701" },
    { "id": "3-2-text-0701", "type": "dialogue", "speaker": "皖萱", "content": "她一个人要同时和这么多人说话？", "expression": "", "background": "night", "next": "3-2-text-0702" },
    { "id": "3-2-text-0702", "type": "dialogue", "speaker": "我", "content": "算是吧。", "expression": "", "background": "night", "next": "3-2-text-0703" },
    { "id": "3-2-text-0703", "type": "narration", "speaker": "", "content": "虚拟主播。", "expression": "", "background": "night", "next": "3-2-text-0704" },
    { "id": "3-2-text-0704", "type": "dialogue", "speaker": "皖萱", "content": "“虚拟”为什么会这么有精神？", "expression": "", "background": "night", "next": "3-2-text-0705" },
    { "id": "3-2-text-0705", "type": "dialogue", "speaker": "我", "content": "可能因为她靠这个吃饭。", "expression": "", "background": "night", "next": "3-2-text-0706" },
    { "id": "3-2-text-0706", "type": "narration", "speaker": "", "content": "皖萱点点头，似懂非懂，视线却没有离开屏幕。", "expression": "", "background": "night", "next": "3-2-text-0707" },
    { "id": "3-2-text-0707", "type": "narration", "speaker": "", "content": "Yui还在闹。", "expression": "", "background": "night", "next": "3-2-text-0708" },
    { "id": "3-2-text-0708", "type": "narration", "speaker": "", "content": "她一会儿念弹幕，一会儿吐槽今天点的外卖翻车，一会儿又突然唱两句不着调的副歌，整个人像一团带电的糖。", "expression": "", "background": "night", "next": "3-2-text-0709" },
    { "id": "3-2-text-0709", "type": "narration", "speaker": "", "content": "皖萱一开始看得很认真，后来神情慢慢从“观察”变成了“适应”，再从“适应”变成一点不自觉的放松。她抱着靠枕，把下巴压在上面，眼睛随着屏幕光一闪一闪。", "expression": "", "background": "night", "next": "3-2-text-0710" },
    { "id": "3-2-text-0710", "type": "narration", "speaker": "", "content": "我原本并不怎么看直播。", "expression": "", "background": "night", "next": "3-2-text-0711" },
    { "id": "3-2-text-0711", "type": "narration", "speaker": "", "content": "可那晚也不知道为什么，没有急着关。", "expression": "", "background": "night", "next": "3-2-text-0712" },
    { "id": "3-2-text-0712", "type": "narration", "speaker": "", "content": "也许是夜宵之后人的神经本来就会松一点，也许是客厅里这种“有人在、电视开着、夜还没结束”的氛围太适合放任时间往后流。", "expression": "", "background": "night", "next": "3-2-text-0713" },
    { "id": "3-2-text-0713", "type": "narration", "speaker": "", "content": "Yui正说着今天的杂谈主题。", "expression": "", "background": "night", "next": "3-2-text-0714" },
    { "id": "3-2-text-0714", "type": "dialogue", "speaker": "Yui", "content": "今天我们来聊“最普通、但一想起来就很想回去的瞬间”——", "expression": "", "background": "night", "next": "3-2-text-0715" },
    { "id": "3-2-text-0715", "type": "narration", "speaker": "", "content": "比如便利店门口的关东煮、比如冬天被窝里偷偷吃的烤红薯、比如明明很困了还要给自己煮一碗面……", "expression": "", "background": "night", "next": "3-2-text-0716" },
    { "id": "3-2-text-0716", "type": "narration", "speaker": "", "content": "我下意识看了皖萱一眼。", "expression": "", "background": "night", "next": "3-2-text-0717" },
    { "id": "3-2-text-0717", "type": "narration", "speaker": "", "content": "她也正好偏头看我。", "expression": "", "background": "night", "next": "3-2-text-0718" },
    { "id": "3-2-text-0718", "type": "narration", "speaker": "", "content": "两个人都顿了一下。", "expression": "", "background": "night", "next": "3-2-text-0719" },
    { "id": "3-2-text-0719", "type": "narration", "speaker": "", "content": "这巧合来得太刚好，以至于像某种轻微的恶作剧。", "expression": "", "background": "night", "next": "3-2-text-0720" },
    { "id": "3-2-text-0720", "type": "dialogue", "speaker": "皖萱", "content": "她说的有点对。", "expression": "", "background": "night", "next": "3-2-text-0721" },
    { "id": "3-2-text-0721", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "3-2-text-0722" },
    { "id": "3-2-text-0722", "type": "dialogue", "speaker": "皖萱", "content": "可是“普通”原来这么厉害啊。", "expression": "", "background": "night", "next": "3-2-text-0723" },
    { "id": "3-2-text-0723", "type": "narration", "speaker": "", "content": "我还没接话，Yui突然在屏幕里往前凑近了一点。", "expression": "", "background": "night", "next": "3-2-text-0724" },
    { "id": "3-2-text-0724", "type": "narration", "speaker": "", "content": "就像临时看到了什么让她在意的东西。", "expression": "", "background": "night", "next": "3-2-text-0725" },
    { "id": "3-2-text-0725", "type": "narration", "speaker": "", "content": "她原本轻快跳脱的节奏，毫无征兆地慢了一拍。", "expression": "", "background": "night", "next": "3-3" },
    { "id": "3-3", "type": "marker", "markerTitle": "Yui 的注视", "next": "3-3-text-0727" },
    { "id": "3-3-text-0727", "type": "narration", "speaker": "", "content": "直播里，弹幕还在飞。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 深夜 / 氛围转折\n【演出】UI 隐去、背景音压低、Yui 直视镜头", "next": "3-3-text-0728" },
    { "id": "3-3-text-0728", "type": "narration", "speaker": "", "content": "可Yui没有立刻接下一条。", "expression": "", "background": "night", "next": "3-3-text-0729" },
    { "id": "3-3-text-0729", "type": "narration", "speaker": "", "content": "她看着镜头。", "expression": "", "background": "night", "next": "3-3-text-0730" },
    { "id": "3-3-text-0730", "type": "narration", "speaker": "", "content": "不是那种营业式的“看向观众”，而像是真的越过了屏幕，忽然在无数个夜里精准看见了某一个具体的人。", "expression": "", "background": "night", "next": "3-3-text-0731" },
    { "id": "3-3-text-0731", "type": "narration", "speaker": "", "content": "客厅里明明没有任何变化，我却莫名觉得后背一凉。", "expression": "", "background": "night", "next": "3-3-text-0732" },
    { "id": "3-3-text-0732", "type": "narration", "speaker": "", "content": "皖萱也坐直了一点。", "expression": "", "background": "night", "next": "3-3-text-0733" },
    { "id": "3-3-text-0733", "type": "narration", "speaker": "", "content": "刚才还松松抱着靠枕的手，不知不觉收紧了。", "expression": "", "background": "night", "next": "3-3-text-0734" },
    { "id": "3-3-text-0734", "type": "narration", "speaker": "", "content": "Yui缓缓眨了一下眼，唇边还是笑着的，语气却和前几分钟完全不一样了。", "expression": "", "background": "night", "next": "3-3-text-0735" },
    { "id": "3-3-text-0735", "type": "dialogue", "speaker": "Yui", "content": "……啊。", "expression": "", "background": "night", "next": "3-3-text-0736" },
    { "id": "3-3-text-0736", "type": "narration", "speaker": "", "content": "发现你了哦。", "expression": "", "background": "night", "next": "3-3-text-0737" },
    { "id": "3-3-text-0737", "type": "narration", "speaker": "", "content": "我皱了皱眉，下意识以为这是她惯常的直播互动套路。", "expression": "", "background": "night", "next": "3-3-text-0738" },
    { "id": "3-3-text-0738", "type": "narration", "speaker": "", "content": "可下一句出来的时候，连我都没办法继续把它归进“巧合”里。", "expression": "", "background": "night", "next": "3-3-text-0739" },
    { "id": "3-3-text-0739", "type": "narration", "speaker": "", "content": "Yui轻轻歪头。", "expression": "", "background": "night", "next": "3-3-text-0740" },
    { "id": "3-3-text-0740", "type": "dialogue", "speaker": "Yui", "content": "躲在温暖房间里偷吃夜宵的天使小姐。", "expression": "", "background": "night", "next": "3-3-text-0741" },
    { "id": "3-3-text-0741", "type": "narration", "speaker": "", "content": "空气像被谁按了暂停。", "expression": "", "background": "night", "next": "3-3-text-0742" },
    { "id": "3-3-text-0742", "type": "narration", "speaker": "", "content": "我猛地转头看向皖萱。", "expression": "", "background": "night", "next": "3-3-text-0743" },
    { "id": "3-3-text-0743", "type": "narration", "speaker": "", "content": "她的瞳孔明显缩了一下，脸上的血色在一瞬间褪得很干净。那不是惊讶得可爱的小反应，而是真正意义上的被点中、被认出、被从安全的日常里突然拽回某个更大的秩序中的错愕。", "expression": "", "background": "night", "next": "3-3-text-0744" },
    { "id": "3-3-text-0744", "type": "dialogue", "speaker": "皖萱", "content": "……", "expression": "", "background": "night", "next": "3-3-text-0745" },
    { "id": "3-3-text-0745", "type": "narration", "speaker": "", "content": "Yui的目光像没有偏移，仍旧稳稳落在屏幕这头。", "expression": "", "background": "night", "next": "3-3-text-0746" },
    { "id": "3-3-text-0746", "type": "dialogue", "speaker": "Yui", "content": "还有那位——", "expression": "", "background": "night", "next": "3-3-text-0747" },
    { "id": "3-3-text-0747", "type": "narration", "speaker": "", "content": "一直在替她把夜晚煮热、把孤单放凉的你。", "expression": "", "background": "night", "next": "3-3-text-0748" },
    { "id": "3-3-text-0748", "type": "narration", "speaker": "", "content": "我喉咙微微发紧。", "expression": "", "background": "night", "next": "3-3-text-0749" },
    { "id": "3-3-text-0749", "type": "narration", "speaker": "", "content": "弹幕还在滚，可那些内容此刻像都成了没有意义的背景噪点。Yui的声音不大，却奇怪地压过了一切。", "expression": "", "background": "night", "next": "3-3-text-0750" },
    { "id": "3-3-text-0750", "type": "narration", "speaker": "", "content": "她微微笑起来，那笑意还是轻盈的，却像故意把一句玩笑包在预言外面。", "expression": "", "background": "night", "next": "3-3-text-0751" },
    { "id": "3-3-text-0751", "type": "dialogue", "speaker": "Yui", "content": "不用那么紧张啦。", "expression": "", "background": "night", "next": "3-3-text-0752" },
    { "id": "3-3-text-0752", "type": "narration", "speaker": "", "content": "能被我看见的事，通常都已经在故事里了。", "expression": "", "background": "night", "next": "3-3-text-0753" },
    { "id": "3-3-text-0753", "type": "narration", "speaker": "", "content": "皖萱坐得更直了。", "expression": "", "background": "night", "next": "3-3-text-0754" },
    { "id": "3-3-text-0754", "type": "narration", "speaker": "", "content": "她望着屏幕，声音很轻，轻得像怕惊动什么。", "expression": "", "background": "night", "next": "3-3-text-0755" },
    { "id": "3-3-text-0755", "type": "dialogue", "speaker": "皖萱", "content": "你是谁？", "expression": "", "background": "night", "next": "3-3-text-0756" },
    { "id": "3-3-text-0756", "type": "narration", "speaker": "", "content": "当然，直播里的Yui不可能真的听见她说话。", "expression": "", "background": "night", "next": "3-3-text-0757" },
    { "id": "3-3-text-0757", "type": "narration", "speaker": "", "content": "可偏偏下一秒，像是回答似的，Yui抬起一根手指，抵在唇边。", "expression": "", "background": "night", "next": "3-3-text-0758" },
    { "id": "3-3-text-0758", "type": "dialogue", "speaker": "Yui", "content": "嘘。", "expression": "", "background": "night", "next": "3-3-text-0759" },
    { "id": "3-3-text-0759", "type": "narration", "speaker": "", "content": "还不到自我介绍的时候。", "expression": "", "background": "night", "next": "3-3-text-0760" },
    { "id": "3-3-text-0760", "type": "narration", "speaker": "", "content": "我手背上的汗毛几乎立起来。", "expression": "", "background": "night", "next": "3-3-text-0761" },
    { "id": "3-3-text-0761", "type": "narration", "speaker": "", "content": "这种程度，已经不是“撞话题”能解释的了。", "expression": "", "background": "night", "next": "3-3-text-0762" },
    { "id": "3-3-text-0762", "type": "narration", "speaker": "", "content": "屏幕里，Yui慢慢往后靠回椅背，像是重新坐回她那个五光十色、热闹而遥远的直播间里。但她看向这边的那种穿透感没有消失。", "expression": "", "background": "night", "next": "3-3-text-0763" },
    { "id": "3-3-text-0763", "type": "dialogue", "speaker": "Yui", "content": "我只是来提醒一句。", "expression": "", "background": "night", "next": "3-3-text-0764" },
    { "id": "3-3-text-0764", "type": "narration", "speaker": "", "content": "她的声音忽然变得很轻。", "expression": "", "background": "night", "next": "3-3-text-0765" },
    { "id": "3-3-text-0765", "type": "narration", "speaker": "", "content": "轻得像糖纸被夜风吹过，却又字字清楚。", "expression": "", "background": "night", "next": "3-3-text-0766" },
    { "id": "3-3-text-0766", "type": "dialogue", "speaker": "Yui", "content": "这种平凡的甜味，是通往未来的入场券。", "expression": "", "background": "night", "next": "3-3-text-0767" },
    { "id": "3-3-text-0767", "type": "narration", "speaker": "", "content": "她停了一拍，眼睛弯起来。", "expression": "", "background": "night", "next": "3-3-text-0768" },
    { "id": "3-3-text-0768", "type": "dialogue", "speaker": "Yui", "content": "所以，天使小姐——", "expression": "", "background": "night", "next": "3-3-text-0769" },
    { "id": "3-3-text-0769", "type": "narration", "speaker": "", "content": "如果你已经开始舍不得，就别再把“调查”当借口啦。", "expression": "", "background": "night", "next": "3-3-text-0770" },
    { "id": "3-3-text-0770", "type": "narration", "speaker": "", "content": "皖萱像被这句话钉在了原地。", "expression": "", "background": "night", "next": "3-3-text-0771" },
    { "id": "3-3-text-0771", "type": "narration", "speaker": "", "content": "我从来没见过她露出这样的表情。", "expression": "", "background": "night", "next": "3-3-text-0772" },
    { "id": "3-3-text-0772", "type": "narration", "speaker": "", "content": "不是单纯的害羞，也不是委屈，更不是平时那种因为被戳中心思而短暂慌乱的可爱。那是一种更深的、夹杂着被看穿和无法回避的沉默。", "expression": "", "background": "night", "next": "3-3-text-0773" },
    { "id": "3-3-text-0773", "type": "narration", "speaker": "", "content": "她低下头。", "expression": "", "background": "night", "next": "3-3-text-0774" },
    { "id": "3-3-text-0774", "type": "narration", "speaker": "", "content": "再抬起来时，眼睛里那层惯常干净明亮的光，已经明显动摇了。", "expression": "", "background": "night", "next": "3-3-text-0775" },
    { "id": "3-3-text-0775", "type": "narration", "speaker": "", "content": "Yui却像什么都没发生过一样，重新用那种轻快得过分的语气收了尾。", "expression": "", "background": "night", "next": "3-3-text-0776" },
    { "id": "3-3-text-0776", "type": "dialogue", "speaker": "Yui", "content": "好啦，今晚的奇迹配送到此结束——", "expression": "", "background": "night", "next": "3-3-text-0777" },
    { "id": "3-3-text-0777", "type": "narration", "speaker": "", "content": "我们在下一个故事见吧~", "expression": "", "background": "night", "next": "3-3-text-0778" },
    { "id": "3-3-text-0778", "type": "narration", "speaker": "", "content": "她冲镜头眨了下眼。", "expression": "", "background": "night", "next": "3-3-text-0779" },
    { "id": "3-3-text-0779", "type": "narration", "speaker": "", "content": "下一秒，直播恢复原本的热闹节奏。", "expression": "", "background": "night", "next": "3-3-text-0780" },
    { "id": "3-3-text-0780", "type": "narration", "speaker": "", "content": "BGM重新响起，弹幕飞得更快，Yui开始若无其事地接下一条留言，像刚才那短短几十秒从来没有发生过。", "expression": "", "background": "night", "next": "3-3-text-0781" },
    { "id": "3-3-text-0781", "type": "narration", "speaker": "", "content": "可客厅里已经完全安静下来。", "expression": "", "background": "night", "next": "3-3-text-0782" },
    { "id": "3-3-text-0782", "type": "narration", "speaker": "", "content": "连空气都像不再是刚才那团柔软的夜宵热气。", "expression": "", "background": "night", "next": "3-3-text-0783" },
    { "id": "3-3-text-0783", "type": "narration", "speaker": "", "content": "它变得清醒、微凉，甚至有一点陌生。", "expression": "", "background": "night", "next": "3-4" },
    { "id": "3-4", "type": "marker", "markerTitle": "被点破之后的沉默", "next": "3-4-text-0785" },
    { "id": "3-4-text-0785", "type": "narration", "speaker": "", "content": "我最先做的事，是按掉电视。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 深夜 / 直播已关\n【BGM】无", "next": "3-4-text-0786" },
    { "id": "3-4-text-0786", "type": "narration", "speaker": "", "content": "屏幕熄灭后，客厅重新掉回昏暗里。刚才那片鲜亮到近乎吵闹的电子光像潮水一样退下去，只剩沙发边那盏小灯还亮着，把皖萱的影子照得很安静。", "expression": "", "background": "night", "next": "3-4-text-0787" },
    { "id": "3-4-text-0787", "type": "narration", "speaker": "", "content": "她低着头，手指还抓着靠枕边角，没有说话。", "expression": "", "background": "night", "next": "3-4-text-0788" },
    { "id": "3-4-text-0788", "type": "narration", "speaker": "", "content": "我也沉默了几秒，才开口。", "expression": "", "background": "night", "next": "3-4-text-0789" },
    { "id": "3-4-text-0789", "type": "dialogue", "speaker": "我", "content": "你认识她？", "expression": "", "background": "night", "next": "3-4-text-0790" },
    { "id": "3-4-text-0790", "type": "narration", "speaker": "", "content": "皖萱轻轻摇头。", "expression": "", "background": "night", "next": "3-4-text-0791" },
    { "id": "3-4-text-0791", "type": "dialogue", "speaker": "皖萱", "content": "不认识。", "expression": "", "background": "night", "next": "3-4-text-0792" },
    { "id": "3-4-text-0792", "type": "dialogue", "speaker": "我", "content": "那她刚才说的……", "expression": "", "background": "night", "next": "3-4-text-0793" },
    { "id": "3-4-text-0793", "type": "dialogue", "speaker": "皖萱", "content": "我不知道。", "expression": "", "background": "night", "next": "3-4-text-0794" },
    { "id": "3-4-text-0794", "type": "narration", "speaker": "", "content": "她的声音很轻，但不是敷衍。", "expression": "", "background": "night", "next": "3-4-text-0795" },
    { "id": "3-4-text-0795", "type": "narration", "speaker": "", "content": "更像连她自己也真的没办法给出答案。", "expression": "", "background": "night", "next": "3-4-text-0796" },
    { "id": "3-4-text-0796", "type": "narration", "speaker": "", "content": "我看着她。", "expression": "", "background": "night", "next": "3-4-text-0797" },
    { "id": "3-4-text-0797", "type": "narration", "speaker": "", "content": "从她落到我家阳台开始，这一个月里发生的很多事都不符合常识。可那些“不符合常识”大多是柔软的、可接纳的，像羽毛、光圈、或者一顿顿说不清原理却很真切的陪伴。", "expression": "", "background": "night", "next": "3-4-text-0798" },
    { "id": "3-4-text-0798", "type": "narration", "speaker": "", "content": "只有刚才那一刻不一样。", "expression": "", "background": "night", "next": "3-4-text-0799" },
    { "id": "3-4-text-0799", "type": "narration", "speaker": "", "content": "那不是温柔的奇迹，而像是有人从更高、更远的地方，忽然把“你们并不只属于这个房间”这件事冷不丁提醒了一遍。", "expression": "", "background": "night", "next": "3-4-text-0800" },
    { "id": "3-4-text-0800", "type": "narration", "speaker": "", "content": "我走到茶几边，把她刚才几乎没碰完的那杯温水推到她手边。", "expression": "", "background": "night", "next": "3-4-text-0801" },
    { "id": "3-4-text-0801", "type": "dialogue", "speaker": "我", "content": "先喝点水。", "expression": "", "background": "night", "next": "3-4-text-0802" },
    { "id": "3-4-text-0802", "type": "narration", "speaker": "", "content": "她听话地捧起来，喝了一小口。", "expression": "", "background": "night", "next": "3-4-text-0803" },
    { "id": "3-4-text-0803", "type": "narration", "speaker": "", "content": "杯壁的热度映在她手指上，竟让她看起来比刚才更脆弱一点。", "expression": "", "background": "night", "next": "3-4-text-0804" },
    { "id": "3-4-text-0804", "type": "narration", "speaker": "", "content": "过了好一会儿，她才低声开口。", "expression": "", "background": "night", "next": "3-4-text-0805" },
    { "id": "3-4-text-0805", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "3-4-text-0806" },
    { "id": "3-4-text-0806", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "3-4-text-0807" },
    { "id": "3-4-text-0807", "type": "dialogue", "speaker": "皖萱", "content": "如果有一天，你发现我不是你以为的那个样子……", "expression": "", "background": "night", "next": "3-4-text-0808" },
    { "id": "3-4-text-0808", "type": "narration", "speaker": "", "content": "她顿住，像不知道后面该怎么说。", "expression": "", "background": "night", "next": "3-4-text-0809" },
    { "id": "3-4-text-0809", "type": "narration", "speaker": "", "content": "我心里某个地方缓慢地沉了一下。", "expression": "", "background": "night", "next": "3-4-text-0810" },
    { "id": "3-4-text-0810", "type": "dialogue", "speaker": "我", "content": "比如？", "expression": "", "background": "night", "next": "3-4-text-0811" },
    { "id": "3-4-text-0811", "type": "dialogue", "speaker": "皖萱", "content": "比如，我没有我表现出来的这么厉害。", "expression": "", "background": "night", "next": "3-4-text-0812" },
    { "id": "3-4-text-0812", "type": "narration", "speaker": "", "content": "比如，我来这里的理由，不止是“调查幸福来源”。", "expression": "", "background": "night", "next": "3-4-text-0813" },
    { "id": "3-4-text-0813", "type": "narration", "speaker": "", "content": "比如……", "expression": "", "background": "night", "next": "3-4-text-0814" },
    { "id": "3-4-text-0814", "type": "narration", "speaker": "", "content": "她说到这里，睫毛轻轻颤了一下。", "expression": "", "background": "night", "next": "3-4-text-0815" },
    { "id": "3-4-text-0815", "type": "dialogue", "speaker": "皖萱", "content": "比如我其实早就不想只把这里当成临时停留的地方了。", "expression": "", "background": "night", "next": "3-4-text-0816" },
    { "id": "3-4-text-0816", "type": "narration", "speaker": "", "content": "我望着她，没有立刻说话。", "expression": "", "background": "night", "next": "3-4-text-0817" },
    { "id": "3-4-text-0817", "type": "narration", "speaker": "", "content": "她这些日子一直在用“调查”“任务”“报告”这种听起来轻飘飘又有安全距离的词，把自己留在这里的原因包好。像给心事裹上糖衣，只要不拆开，就可以继续假装一切都还只是实习天使的观察项目。", "expression": "", "background": "night", "next": "3-4-text-0818" },
    { "id": "3-4-text-0818", "type": "narration", "speaker": "", "content": "可Yui刚才那一句，几乎是把那层糖纸当场撕开了。", "expression": "", "background": "night", "next": "3-4-text-0819" },
    { "id": "3-4-text-0819", "type": "narration", "speaker": "", "content": "我在她面前蹲下来，和她视线平齐。", "expression": "", "background": "night", "next": "3-4-text-0820" },
    { "id": "3-4-text-0820", "type": "dialogue", "speaker": "我", "content": "那你想听我的答案吗？", "expression": "", "background": "night", "next": "3-4-text-0821" },
    { "id": "3-4-text-0821", "type": "narration", "speaker": "", "content": "她抬眼看我，眼底还残着刚才那阵慌乱没完全散掉的水色。", "expression": "", "background": "night", "next": "3-4-text-0822" },
    { "id": "3-4-text-0822", "type": "dialogue", "speaker": "皖萱", "content": "想。", "expression": "", "background": "night", "next": "3-4-text-0823" },
    { "id": "3-4-text-0823", "type": "dialogue", "speaker": "我", "content": "我从来没觉得你留在这里，只是为了写什么调查报告。", "expression": "", "background": "night", "next": "3-4-text-0824" },
    { "id": "3-4-text-0824", "type": "narration", "speaker": "", "content": "她怔住。", "expression": "", "background": "night", "next": "3-4-text-0825" },
    { "id": "3-4-text-0825", "type": "dialogue", "speaker": "我", "content": "一开始也许是。", "expression": "", "background": "night", "next": "3-4-text-0826" },
    { "id": "3-4-text-0826", "type": "narration", "speaker": "", "content": "后来不是了。", "expression": "", "background": "night", "next": "3-4-text-0827" },
    { "id": "3-4-text-0827", "type": "narration", "speaker": "", "content": "我看着她，一字一句，说得很慢。", "expression": "", "background": "night", "next": "3-4-text-0828" },
    { "id": "3-4-text-0828", "type": "dialogue", "speaker": "我", "content": "后来你会在下雨天期待门铃，会把最后一块炸鸡留给我，会在我熬夜的时候自己去厨房煮面，会因为怕我一个人吃关东煮凉得太快，就让我再多吃一块。", "expression": "", "background": "night", "next": "3-4-text-0829" },
    { "id": "3-4-text-0829", "type": "narration", "speaker": "", "content": "我停了停。", "expression": "", "background": "night", "next": "3-4-text-0830" },
    { "id": "3-4-text-0830", "type": "dialogue", "speaker": "我", "content": "这些都不像“任务”。", "expression": "", "background": "night", "next": "3-4-text-0831" },
    { "id": "3-4-text-0831", "type": "narration", "speaker": "", "content": "她的嘴唇轻轻动了一下，却没发出声音。", "expression": "", "background": "night", "next": "3-4-text-0832" },
    { "id": "3-4-text-0832", "type": "narration", "speaker": "", "content": "我继续说：", "expression": "", "background": "night", "next": "3-4-text-0833" },
    { "id": "3-4-text-0833", "type": "dialogue", "speaker": "我", "content": "而且说实话，皖萱。", "expression": "", "background": "night", "next": "3-4-text-0834" },
    { "id": "3-4-text-0834", "type": "narration", "speaker": "", "content": "就算你最开始真的是为了任务才接近我——", "expression": "", "background": "night", "next": "3-4-text-0835" },
    { "id": "3-4-text-0835", "type": "narration", "speaker": "", "content": "我望着她。", "expression": "", "background": "night", "next": "3-4-text-0836" },
    { "id": "3-4-text-0836", "type": "dialogue", "speaker": "我", "content": "到了现在，我也已经分不清是你在观察我，还是我在依赖你了。", "expression": "", "background": "night", "next": "3-4-text-0837" },
    { "id": "3-4-text-0837", "type": "narration", "speaker": "", "content": "那一瞬间，她眼睛里的光像被什么击中一样，轻轻晃了一下。", "expression": "", "background": "night", "next": "3-4-text-0838" },
    { "id": "3-4-text-0838", "type": "narration", "speaker": "", "content": "她抿着唇，低头看着手里的杯子，好久，才闷闷地开口。", "expression": "", "background": "night", "next": "3-4-text-0839" },
    { "id": "3-4-text-0839", "type": "dialogue", "speaker": "皖萱", "content": "……这样不公平。", "expression": "", "background": "night", "next": "3-4-text-0840" },
    { "id": "3-4-text-0840", "type": "dialogue", "speaker": "我", "content": "哪里不公平？", "expression": "", "background": "night", "next": "3-4-text-0841" },
    { "id": "3-4-text-0841", "type": "dialogue", "speaker": "皖萱", "content": "我明明还没有想好要不要告诉你全部。", "expression": "", "background": "night", "next": "3-4-text-0842" },
    { "id": "3-4-text-0842", "type": "narration", "speaker": "", "content": "你就先说这种话。", "expression": "", "background": "night", "next": "3-4-text-0843" },
    { "id": "3-4-text-0843", "type": "narration", "speaker": "", "content": "我笑了一下。", "expression": "", "background": "night", "next": "3-4-text-0844" },
    { "id": "3-4-text-0844", "type": "dialogue", "speaker": "我", "content": "那你慢慢想。", "expression": "", "background": "night", "next": "3-4-text-0845" },
    { "id": "3-4-text-0845", "type": "dialogue", "speaker": "皖萱", "content": "万一你等不到呢？", "expression": "", "background": "night", "next": "3-4-text-0846" },
    { "id": "3-4-text-0846", "type": "narration", "speaker": "", "content": "这句出来的时候，她声音轻得几乎像在自言自语。", "expression": "", "background": "night", "next": "3-4-text-0847" },
    { "id": "3-4-text-0847", "type": "narration", "speaker": "", "content": "可我还是听见了。", "expression": "", "background": "night", "next": "3-4-text-0848" },
    { "id": "3-4-text-0848", "type": "narration", "speaker": "", "content": "我胸口忽然一紧。", "expression": "", "background": "night", "next": "3-4-text-0849" },
    { "id": "3-4-text-0849", "type": "narration", "speaker": "", "content": "比起“她有秘密”，我更在意的是这句“等不到”。", "expression": "", "background": "night", "next": "3-4-text-0850" },
    { "id": "3-4-text-0850", "type": "narration", "speaker": "", "content": "这说明连她自己都已经很清楚，有什么东西正在逼近，而且那东西的轮廓，恐怕并不温柔。", "expression": "", "background": "night", "next": "3-4-text-0851" },
    { "id": "3-4-text-0851", "type": "narration", "speaker": "", "content": "我伸手，轻轻覆在她握着杯子的手背上。", "expression": "", "background": "night", "next": "3-4-text-0852" },
    { "id": "3-4-text-0852", "type": "narration", "speaker": "", "content": "她微微颤了一下，却没有躲。", "expression": "", "background": "night", "next": "3-4-text-0853" },
    { "id": "3-4-text-0853", "type": "dialogue", "speaker": "我", "content": "那就别让我等太久。", "expression": "", "background": "night", "next": "3-4-text-0854" },
    { "id": "3-4-text-0854", "type": "narration", "speaker": "", "content": "她垂着眼，过了很久，才极轻地点了一下头。", "expression": "", "background": "night", "next": "3-4-text-0855" },
    { "id": "3-4-text-0855", "type": "dialogue", "speaker": "皖萱", "content": "……嗯。", "expression": "", "background": "night", "next": "3-4-text-0856" },
    { "id": "3-4-text-0856", "type": "narration", "speaker": "", "content": "那天晚上，我们谁都没有继续追问Yui到底是谁。", "expression": "", "background": "night", "next": "3-4-text-0857" },
    { "id": "3-4-text-0857", "type": "narration", "speaker": "", "content": "因为直觉告诉我，那不是一个靠多问几句就能换来答案的存在。", "expression": "", "background": "night", "next": "3-4-text-0858" },
    { "id": "3-4-text-0858", "type": "narration", "speaker": "", "content": "可从那一刻开始，有什么东西已经彻底变了。", "expression": "", "background": "night", "next": "3-4-text-0859" },
    { "id": "3-4-text-0859", "type": "narration", "speaker": "", "content": "如果说第二幕的日常像一锅慢火煨出来的汤，那么第三幕这一夜，就是有人忽然把锅盖掀开了一条缝。", "expression": "", "background": "night", "next": "3-4-text-0860" },
    { "id": "3-4-text-0860", "type": "narration", "speaker": "", "content": "香气还在，温度也还在，可你已经看见底下有更深的火。", "expression": "", "background": "night", "next": "3-5" },
    { "id": "3-5", "type": "marker", "markerTitle": "阳台上的风与未说出口的决定", "next": "3-5-text-0862" },
    { "id": "3-5-text-0862", "type": "narration", "speaker": "", "content": "我半夜醒了一次。", "expression": "", "background": "night", "stageNote": "【场景】阳台 / 凌晨\n【BG】城市夜景，风稍大，月色冷淡\n【BGM】空灵钢琴", "next": "3-5-text-0863" },
    { "id": "3-5-text-0863", "type": "narration", "speaker": "", "content": "醒来的原因说不清，像是做了个没记住内容的梦，又像是潜意识一直记着客厅那场过于怪异的直播。", "expression": "", "background": "night", "next": "3-5-text-0864" },
    { "id": "3-5-text-0864", "type": "narration", "speaker": "", "content": "房间门开了一条缝。", "expression": "", "background": "night", "next": "3-5-text-0865" },
    { "id": "3-5-text-0865", "type": "narration", "speaker": "", "content": "外面没有全黑，阳台方向透进一点很淡的月光。", "expression": "", "background": "night", "next": "3-5-text-0866" },
    { "id": "3-5-text-0866", "type": "narration", "speaker": "", "content": "我起身走出去，果然看见皖萱站在阳台上。", "expression": "", "background": "night", "next": "3-5-text-0867" },
    { "id": "3-5-text-0867", "type": "narration", "speaker": "", "content": "她没穿拖鞋，白色裙摆被夜风吹得轻轻晃，头发散在肩背上，像月光本身长出的一截影子。她背对着我，手扶在栏杆上，仰头看着很远的地方。", "expression": "", "background": "night", "next": "3-5-text-0868" },
    { "id": "3-5-text-0868", "type": "narration", "speaker": "", "content": "我走近的时候，她没有回头。", "expression": "", "background": "night", "next": "3-5-text-0869" },
    { "id": "3-5-text-0869", "type": "narration", "speaker": "", "content": "像是早就知道我会来。", "expression": "", "background": "night", "next": "3-5-text-0870" },
    { "id": "3-5-text-0870", "type": "dialogue", "speaker": "我", "content": "睡不着？", "expression": "", "background": "night", "next": "3-5-text-0871" },
    { "id": "3-5-text-0871", "type": "dialogue", "speaker": "皖萱", "content": "嗯。", "expression": "", "background": "night", "next": "3-5-text-0872" },
    { "id": "3-5-text-0872", "type": "narration", "speaker": "", "content": "夜风从我们中间穿过去，带着一点高处特有的凉。城市还没完全睡，远处有零星车灯缓慢移动，像很迟才落下来的流星。", "expression": "", "background": "night", "next": "3-5-text-0873" },
    { "id": "3-5-text-0873", "type": "narration", "speaker": "", "content": "我站到她旁边。", "expression": "", "background": "night", "next": "3-5-text-0874" },
    { "id": "3-5-text-0874", "type": "dialogue", "speaker": "我", "content": "在想Yui的事？", "expression": "", "background": "night", "next": "3-5-text-0875" },
    { "id": "3-5-text-0875", "type": "narration", "speaker": "", "content": "她沉默了一会儿。", "expression": "", "background": "night", "next": "3-5-text-0876" },
    { "id": "3-5-text-0876", "type": "dialogue", "speaker": "皖萱", "content": "也在想我自己的事。", "expression": "", "background": "night", "next": "3-5-text-0877" },
    { "id": "3-5-text-0877", "type": "narration", "speaker": "", "content": "我没有催。", "expression": "", "background": "night", "next": "3-5-text-0878" },
    { "id": "3-5-text-0878", "type": "narration", "speaker": "", "content": "因为我知道，她如果愿意说，今晚大概就是会说的时候；如果不愿意，再多一句追问也只会把她逼得更远。", "expression": "", "background": "night", "next": "3-5-text-0879" },
    { "id": "3-5-text-0879", "type": "narration", "speaker": "", "content": "过了很久，她才轻声开口。", "expression": "", "background": "night", "next": "3-5-text-0880" },
    { "id": "3-5-text-0880", "type": "dialogue", "speaker": "皖萱", "content": "其实“调查幸福来源”是真的。", "expression": "", "background": "night", "next": "3-5-text-0881" },
    { "id": "3-5-text-0881", "type": "narration", "speaker": "", "content": "可是……不是全部。", "expression": "", "background": "night", "next": "3-5-text-0882" },
    { "id": "3-5-text-0882", "type": "narration", "speaker": "", "content": "我侧过头看她。", "expression": "", "background": "night", "next": "3-5-text-0883" },
    { "id": "3-5-text-0883", "type": "dialogue", "speaker": "皖萱", "content": "实习天使在下界之前，都要提交一个意向课题。", "expression": "", "background": "night", "next": "3-5-text-0884" },
    { "id": "3-5-text-0884", "type": "narration", "speaker": "", "content": "有人研究勇气，有人研究遗憾，有人研究人为什么明明会受伤，还要继续去喜欢什么东西。", "expression": "", "background": "night", "next": "3-5-text-0885" },
    { "id": "3-5-text-0885", "type": "narration", "speaker": "", "content": "她顿了顿。", "expression": "", "background": "night", "next": "3-5-text-0886" },
    { "id": "3-5-text-0886", "type": "dialogue", "speaker": "皖萱", "content": "而我写的是——“幸福到底有没有让人放弃羽翼的重量”。", "expression": "", "background": "night", "next": "3-5-text-0887" },
    { "id": "3-5-text-0887", "type": "narration", "speaker": "", "content": "我心口猛地一沉。", "expression": "", "background": "night", "next": "3-5-text-0888" },
    { "id": "3-5-text-0888", "type": "narration", "speaker": "", "content": "羽翼。", "expression": "", "background": "night", "next": "3-5-text-0889" },
    { "id": "3-5-text-0889", "type": "narration", "speaker": "", "content": "那不是比喻。", "expression": "", "background": "night", "next": "3-5-text-0890" },
    { "id": "3-5-text-0890", "type": "narration", "speaker": "", "content": "是她真正拥有、也真正可能失去的东西。", "expression": "", "background": "night", "next": "3-5-text-0891" },
    { "id": "3-5-text-0891", "type": "narration", "speaker": "", "content": "皖萱低头看着自己空着的手，语气很轻，像怕把这句话说重了，就会当场变成现实。", "expression": "", "background": "night", "next": "3-5-text-0892" },
    { "id": "3-5-text-0892", "type": "dialogue", "speaker": "皖萱", "content": "如果实习结束以后，我判定人间没有值得我留下的东西，我就会回去。", "expression": "", "background": "night", "next": "3-5-text-0893" },
    { "id": "3-5-text-0893", "type": "narration", "speaker": "", "content": "羽翼会保留，法力会保留，天界会承认我完成了任务。", "expression": "", "background": "night", "next": "3-5-text-0894" },
    { "id": "3-5-text-0894", "type": "narration", "speaker": "", "content": "她说到这里，停住了。", "expression": "", "background": "night", "next": "3-5-text-0895" },
    { "id": "3-5-text-0895", "type": "narration", "speaker": "", "content": "风吹起她额前的碎发，我第一次从她安静的侧脸里看见某种近乎无措的东西。", "expression": "", "background": "night", "next": "3-5-text-0896" },
    { "id": "3-5-text-0896", "type": "dialogue", "speaker": "皖萱", "content": "可如果我想留下。", "expression": "", "background": "night", "next": "3-5-text-0897" },
    { "id": "3-5-text-0897", "type": "narration", "speaker": "", "content": "我握住栏杆的手收紧了一点。", "expression": "", "background": "night", "next": "3-5-text-0898" },
    { "id": "3-5-text-0898", "type": "dialogue", "speaker": "皖萱", "content": "那就不是“实习结束回去交报告”这么简单了。", "expression": "", "background": "night", "next": "3-5-text-0899" },
    { "id": "3-5-text-0899", "type": "narration", "speaker": "", "content": "我需要主动放弃羽翼，放弃法力，也放弃原本的归处。", "expression": "", "background": "night", "next": "3-5-text-0900" },
    { "id": "3-5-text-0900", "type": "narration", "speaker": "", "content": "她抬起眼，看向夜空，声音轻得像被风一吹就会散。", "expression": "", "background": "night", "next": "3-5-text-0901" },
    { "id": "3-5-text-0901", "type": "dialogue", "speaker": "皖萱", "content": "会很疼。", "expression": "", "background": "night", "next": "3-5-text-0902" },
    { "id": "3-5-text-0902", "type": "narration", "speaker": "", "content": "而且一旦做了，就回不去了。", "expression": "", "background": "night", "next": "3-5-text-0903" },
    { "id": "3-5-text-0903", "type": "narration", "speaker": "", "content": "我一时间没有说话。", "expression": "", "background": "night", "next": "3-5-text-0904" },
    { "id": "3-5-text-0904", "type": "narration", "speaker": "", "content": "不是因为听不懂，而是因为太明白这意味着什么。", "expression": "", "background": "night", "next": "3-5-text-0905" },
    { "id": "3-5-text-0905", "type": "narration", "speaker": "", "content": "她不是在烦恼一场普通的分别，也不是在面对一段短暂关系该不该更进一步的犹豫。", "expression": "", "background": "night", "next": "3-5-text-0906" },
    { "id": "3-5-text-0906", "type": "narration", "speaker": "", "content": "她是在想，要不要为了留在人间、留在我身边，放弃她原本属于的整个世界。", "expression": "", "background": "night", "next": "3-5-text-0907" },
    { "id": "3-5-text-0907", "type": "narration", "speaker": "", "content": "而这种分量，重到让我甚至不敢立刻说出“留下来”三个字。", "expression": "", "background": "night", "next": "3-5-text-0908" },
    { "id": "3-5-text-0908", "type": "narration", "speaker": "", "content": "因为如果我现在说了，那几乎等于在用自己的舍不得，去向她索要一生一次的代价。", "expression": "", "background": "night", "next": "3-5-text-0909" },
    { "id": "3-5-text-0909", "type": "narration", "speaker": "", "content": "我望着她。", "expression": "", "background": "night", "next": "3-5-text-0910" },
    { "id": "3-5-text-0910", "type": "narration", "speaker": "", "content": "月光把她脸上的神情照得很清。", "expression": "", "background": "night", "next": "3-5-text-0911" },
    { "id": "3-5-text-0911", "type": "narration", "speaker": "", "content": "那不是一个在撒娇、在试探、在等人挽留的女孩。", "expression": "", "background": "night", "next": "3-5-text-0912" },
    { "id": "3-5-text-0912", "type": "narration", "speaker": "", "content": "那是一个真的站在选择前面、因为终于知道自己想要什么而开始害怕的人。", "expression": "", "background": "night", "next": "3-5-text-0913" },
    { "id": "3-5-text-0913", "type": "narration", "speaker": "", "content": "我深吸了一口气。", "expression": "", "background": "night", "next": "3-5-text-0914" },
    { "id": "3-5-text-0914", "type": "dialogue", "speaker": "我", "content": "所以你这段时间一直提起“如果我离开了”。", "expression": "", "background": "night", "next": "3-5-text-0915" },
    { "id": "3-5-text-0915", "type": "narration", "speaker": "", "content": "她轻轻点头。", "expression": "", "background": "night", "next": "3-5-text-0916" },
    { "id": "3-5-text-0916", "type": "dialogue", "speaker": "皖萱", "content": "我原本以为，只要我提前习惯一点，最后就不会那么难。", "expression": "", "background": "night", "next": "3-5-text-0917" },
    { "id": "3-5-text-0917", "type": "dialogue", "speaker": "我", "content": "那有用吗？", "expression": "", "background": "night", "next": "3-5-text-0918" },
    { "id": "3-5-text-0918", "type": "narration", "speaker": "", "content": "她沉默片刻，轻轻摇头。", "expression": "", "background": "night", "next": "3-5-text-0919" },
    { "id": "3-5-text-0919", "type": "dialogue", "speaker": "皖萱", "content": "没用。", "expression": "", "background": "night", "next": "3-5-text-0920" },
    { "id": "3-5-text-0920", "type": "narration", "speaker": "", "content": "说完这句，她终于转头看我。", "expression": "", "background": "night", "next": "3-5-text-0921" },
    { "id": "3-5-text-0921", "type": "narration", "speaker": "", "content": "眼睛里一点遮掩都没有，干净得几乎残忍。", "expression": "", "background": "night", "next": "3-5-text-0922" },
    { "id": "3-5-text-0922", "type": "dialogue", "speaker": "皖萱", "content": "因为我越提醒自己只是暂住，就越会在每一顿饭、每一个晚上、每一次你叫我名字的时候，变得更舍不得。", "expression": "", "background": "night", "next": "3-5-text-0923" },
    { "id": "3-5-text-0923", "type": "narration", "speaker": "", "content": "风好像忽然大了一点。", "expression": "", "background": "night", "next": "3-5-text-0924" },
    { "id": "3-5-text-0924", "type": "narration", "speaker": "", "content": "我站在原地，胸口像被什么缓慢而用力地攥住。", "expression": "", "background": "night", "next": "3-5-text-0925" },
    { "id": "3-5-text-0925", "type": "narration", "speaker": "", "content": "那一刻我才真正明白，Yui那句“如果你已经开始舍不得，就别再把调查当借口啦”为什么会让皖萱露出那样的表情。", "expression": "", "background": "night", "next": "3-5-text-0926" },
    { "id": "3-5-text-0926", "type": "narration", "speaker": "", "content": "因为她早就不是不知道自己的心意。", "expression": "", "background": "night", "next": "3-5-text-0927" },
    { "id": "3-5-text-0927", "type": "narration", "speaker": "", "content": "她只是还没有勇气承认，承认“喜欢”这件事，已经重到足以让她动摇羽翼。", "expression": "", "background": "night", "next": "3-5-text-0928" },
    { "id": "3-5-text-0928", "type": "narration", "speaker": "", "content": "我抬起手，犹豫了一下，最后还是轻轻碰了碰她的发顶。", "expression": "", "background": "night", "next": "3-5-text-0929" },
    { "id": "3-5-text-0929", "type": "narration", "speaker": "", "content": "动作很轻，像怕惊散什么。", "expression": "", "background": "night", "next": "3-5-text-0930" },
    { "id": "3-5-text-0930", "type": "dialogue", "speaker": "我", "content": "那今晚先别决定。", "expression": "", "background": "night", "next": "3-5-text-0931" },
    { "id": "3-5-text-0931", "type": "narration", "speaker": "", "content": "她怔了一下。", "expression": "", "background": "night", "next": "3-5-text-0932" },
    { "id": "3-5-text-0932", "type": "dialogue", "speaker": "我", "content": "这不是一顿夜宵该逼出来的答案。", "expression": "", "background": "night", "next": "3-5-text-0933" },
    { "id": "3-5-text-0933", "type": "narration", "speaker": "", "content": "也不是别人一句话就该让你立刻选完的一生。", "expression": "", "background": "night", "next": "3-5-text-0934" },
    { "id": "3-5-text-0934", "type": "narration", "speaker": "", "content": "她望着我，眼睫轻轻颤了一下。", "expression": "", "background": "night", "next": "3-5-text-0935" },
    { "id": "3-5-text-0935", "type": "dialogue", "speaker": "我", "content": "你可以慢一点。", "expression": "", "background": "night", "next": "3-5-text-0936" },
    { "id": "3-5-text-0936", "type": "narration", "speaker": "", "content": "至少，在你真的想清楚之前，我不会替你做这个决定。", "expression": "", "background": "night", "next": "3-5-text-0937" },
    { "id": "3-5-text-0937", "type": "narration", "speaker": "", "content": "这话说出口的时候，我心里其实也在疼。", "expression": "", "background": "night", "next": "3-5-text-0938" },
    { "id": "3-5-text-0938", "type": "narration", "speaker": "", "content": "因为我比谁都清楚，自己想说的根本不是这些。", "expression": "", "background": "night", "next": "3-5-text-0939" },
    { "id": "3-5-text-0939", "type": "narration", "speaker": "", "content": "我真正想说的是：", "expression": "", "background": "night", "next": "3-5-text-0940" },
    { "id": "3-5-text-0940", "type": "narration", "speaker": "", "content": "留下来。", "expression": "", "background": "night", "next": "3-5-text-0941" },
    { "id": "3-5-text-0941", "type": "narration", "speaker": "", "content": "别走。", "expression": "", "background": "night", "next": "3-5-text-0942" },
    { "id": "3-5-text-0942", "type": "narration", "speaker": "", "content": "如果失去羽翼会疼，那我会想办法把以后每一天都补给你。", "expression": "", "background": "night", "next": "3-5-text-0943" },
    { "id": "3-5-text-0943", "type": "narration", "speaker": "", "content": "可我最后还是没有那么说。", "expression": "", "background": "night", "next": "3-5-text-0944" },
    { "id": "3-5-text-0944", "type": "narration", "speaker": "", "content": "因为喜欢不该变成催促。", "expression": "", "background": "night", "next": "3-5-text-0945" },
    { "id": "3-5-text-0945", "type": "narration", "speaker": "", "content": "更不该变成一场温柔的绑架。", "expression": "", "background": "night", "next": "3-5-text-0946" },
    { "id": "3-5-text-0946", "type": "narration", "speaker": "", "content": "皖萱看着我，好久都没出声。", "expression": "", "background": "night", "next": "3-5-text-0947" },
    { "id": "3-5-text-0947", "type": "narration", "speaker": "", "content": "最后，她很轻很轻地笑了一下。", "expression": "", "background": "night", "next": "3-5-text-0948" },
    { "id": "3-5-text-0948", "type": "narration", "speaker": "", "content": "那笑里有疲惫，也有一点快要落下来的温柔。", "expression": "", "background": "night", "next": "3-5-text-0949" },
    { "id": "3-5-text-0949", "type": "dialogue", "speaker": "皖萱", "content": "你这样……会让我更难选的。", "expression": "", "background": "night", "next": "3-5-text-0950" },
    { "id": "3-5-text-0950", "type": "narration", "speaker": "", "content": "我也笑了。", "expression": "", "background": "night", "next": "3-5-text-0951" },
    { "id": "3-5-text-0951", "type": "dialogue", "speaker": "我", "content": "那没办法。", "expression": "", "background": "night", "next": "3-5-text-0952" },
    { "id": "3-5-text-0952", "type": "narration", "speaker": "", "content": "她低下头，肩膀轻轻抖了一下，像是笑了，也像是差一点要哭。", "expression": "", "background": "night", "next": "3-5-text-0953" },
    { "id": "3-5-text-0953", "type": "narration", "speaker": "", "content": "那一夜的风很凉。", "expression": "", "background": "night", "next": "3-5-text-0954" },
    { "id": "3-5-text-0954", "type": "narration", "speaker": "", "content": "可我们站在阳台上时，我却第一次觉得，真正让人发抖的不是夜里的温度。", "expression": "", "background": "night", "next": "3-5-text-0955" },
    { "id": "3-5-text-0955", "type": "narration", "speaker": "", "content": "而是终于看见了幸福的代价。", "expression": "", "background": "night", "next": "3-6" },
    { "id": "3-6", "type": "marker", "markerTitle": "第三幕收束：故事已经开始要求答案", "next": "3-6-text-0957" },
    { "id": "3-6-text-0957", "type": "narration", "speaker": "", "content": "——天快亮时，我们才各自回房。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 次日清晨前的蒙太奇\n【演出】夜尽将明，时间推进到新的阶段", "next": "3-6-text-0958" },
    { "id": "3-6-text-0958", "type": "narration", "speaker": "", "content": "——第二天早餐照常吃了，吐司、煎蛋和牛奶一样不少。可某些东西已经不同了。我们都在尽量若无其事，可越若无其事，越显得昨晚那些话仍旧横在中间。", "expression": "", "background": "night", "next": "3-6-text-0959" },
    { "id": "3-6-text-0959", "type": "narration", "speaker": "", "content": "——皖萱还是会笑，也还是会对新买回来的甜点眼睛发亮。只是偶尔发呆的时间变长了，像在心里反复拿起又放下什么。", "expression": "", "background": "night", "next": "3-6-text-0960" },
    { "id": "3-6-text-0960", "type": "narration", "speaker": "", "content": "——我开始注意她看向阳台、天空、甚至那片会发光的羽毛时的神情。那里头不再只有轻飘飘的天真，而多了一种正在靠近选择的人才会有的静。", "expression": "", "background": "night", "next": "3-6-text-0961" },
    { "id": "3-6-text-0961", "type": "narration", "speaker": "", "content": "——夜里再一起吃东西时，我们会比之前更安静一点。不是疏远，而是都在小心对待某种已经被说破、却还没真正落地的心意。", "expression": "", "background": "night", "next": "第四幕-抉择——放弃羽翼的理由" },
    { "id": "第四幕-抉择——放弃羽翼的理由", "type": "marker", "markerTitle": "第四幕：抉择——放弃羽翼的理由", "next": "4-1" },
    { "id": "4-1", "type": "marker", "markerTitle": "归还的钟声", "next": "4-1-text-0964" },
    { "id": "4-1-text-0964", "type": "narration", "speaker": "", "content": "那一天来得比我想象中更突然。", "expression": "", "background": "evening", "stageNote": "【场景】客厅 / 傍晚 / 雷雨将至\n【BG】天色压低，屋内昏暗，阳台外风大\n【BGM】低缓弦乐", "next": "4-1-text-0965" },
    { "id": "4-1-text-0965", "type": "narration", "speaker": "", "content": "下午四点左右，天色忽然暗了下来。", "expression": "", "background": "evening", "next": "4-1-text-0966" },
    { "id": "4-1-text-0966", "type": "narration", "speaker": "", "content": "原本还算明亮的客厅像被人从高处慢慢盖上一层灰蓝色的薄布，光线一点点收窄。窗外的风变大了，阳台上的风铃被吹得断断续续响，声音不再清脆，反而有些发空。", "expression": "", "background": "evening", "next": "4-1-text-0967" },
    { "id": "4-1-text-0967", "type": "narration", "speaker": "", "content": "皖萱那时正坐在地毯上，整理前几天拍下来的甜点照片，说是要给自己的“调查样本”做归档。我在一旁改文件，键盘敲到一半，忽然听见她那边传来一声极轻的抽气。", "expression": "", "background": "evening", "next": "4-1-text-0968" },
    { "id": "4-1-text-0968", "type": "narration", "speaker": "", "content": "我抬头。", "expression": "", "background": "evening", "next": "4-1-text-0969" },
    { "id": "4-1-text-0969", "type": "narration", "speaker": "", "content": "她手里那片平时用来联络的羽毛，正在发光。", "expression": "", "background": "evening", "next": "4-1-text-0970" },
    { "id": "4-1-text-0970", "type": "narration", "speaker": "", "content": "不是柔和的、像呼吸一样的光。", "expression": "", "background": "evening", "next": "4-1-text-0971" },
    { "id": "4-1-text-0971", "type": "narration", "speaker": "", "content": "而是一种过分稳定、过分冷静的白。", "expression": "", "background": "evening", "next": "4-1-text-0972" },
    { "id": "4-1-text-0972", "type": "narration", "speaker": "", "content": "皖萱盯着它，脸色一点一点白下去。", "expression": "", "background": "evening", "next": "4-1-text-0973" },
    { "id": "4-1-text-0973", "type": "narration", "speaker": "", "content": "我放下电脑，站起身走过去。", "expression": "", "background": "evening", "next": "4-1-text-0974" },
    { "id": "4-1-text-0974", "type": "dialogue", "speaker": "我", "content": "怎么了？", "expression": "", "background": "evening", "next": "4-1-text-0975" },
    { "id": "4-1-text-0975", "type": "narration", "speaker": "", "content": "她没有立刻回答。", "expression": "", "background": "evening", "next": "4-1-text-0976" },
    { "id": "4-1-text-0976", "type": "narration", "speaker": "", "content": "那片羽毛在她掌心微微震动，像很薄的一枚铃。紧接着，一道极细的声音从里面传出来。那声音听不出男女，只平直、清晰、没有情绪，像是某种早已写好的通知被准确念诵。", "expression": "", "background": "evening", "next": "4-1-text-0977" },
    { "id": "4-1-text-0977", "type": "narration", "speaker": "", "content": "“实习编号8964，期限已至。请于日落前完成返回准备。”", "expression": "", "background": "evening", "next": "4-1-text-0978" },
    { "id": "4-1-text-0978", "type": "narration", "speaker": "", "content": "客厅里一下子静下来。", "expression": "", "background": "evening", "next": "4-1-text-0979" },
    { "id": "4-1-text-0979", "type": "narration", "speaker": "", "content": "外面的风还在响，可我却觉得自己什么都听不见了。", "expression": "", "background": "evening", "next": "4-1-text-0980" },
    { "id": "4-1-text-0980", "type": "narration", "speaker": "", "content": "皖萱慢慢合拢手指，把那道光握住。", "expression": "", "background": "evening", "next": "4-1-text-0981" },
    { "id": "4-1-text-0981", "type": "narration", "speaker": "", "content": "动作很轻，像想把什么声音关回去。", "expression": "", "background": "evening", "next": "4-1-text-0982" },
    { "id": "4-1-text-0982", "type": "narration", "speaker": "", "content": "可来不及了。", "expression": "", "background": "evening", "next": "4-1-text-0983" },
    { "id": "4-1-text-0983", "type": "narration", "speaker": "", "content": "该听见的，我已经全部听见。", "expression": "", "background": "evening", "next": "4-1-text-0984" },
    { "id": "4-1-text-0984", "type": "narration", "speaker": "", "content": "我看着她。", "expression": "", "background": "evening", "next": "4-1-text-0985" },
    { "id": "4-1-text-0985", "type": "dialogue", "speaker": "我", "content": "……今天？", "expression": "", "background": "evening", "next": "4-1-text-0986" },
    { "id": "4-1-text-0986", "type": "narration", "speaker": "", "content": "她低着头，过了两秒，才很轻地点了一下。", "expression": "", "background": "evening", "next": "4-1-text-0987" },
    { "id": "4-1-text-0987", "type": "dialogue", "speaker": "皖萱", "content": "嗯。", "expression": "", "background": "evening", "next": "4-1-text-0988" },
    { "id": "4-1-text-0988", "type": "narration", "speaker": "", "content": "我胸口像被人猛地攥了一下。", "expression": "", "background": "evening", "next": "4-1-text-0989" },
    { "id": "4-1-text-0989", "type": "narration", "speaker": "", "content": "我明明早就知道会有这一天。", "expression": "", "background": "evening", "next": "4-1-text-0990" },
    { "id": "4-1-text-0990", "type": "narration", "speaker": "", "content": "从她说“三十个地面日”的第一天开始，从她半夜问我“如果我以后回去天界了”的时候开始，从Yui在直播里把那层伪装撕开以后开始，我其实一直都知道。", "expression": "", "background": "evening", "next": "4-1-text-0991" },
    { "id": "4-1-text-0991", "type": "narration", "speaker": "", "content": "可“知道”和“真的到了”原来是两回事。", "expression": "", "background": "evening", "next": "4-1-text-0992" },
    { "id": "4-1-text-0992", "type": "narration", "speaker": "", "content": "前者像天气预报里说傍晚会下雨。", "expression": "", "background": "evening", "next": "4-1-text-0993" },
    { "id": "4-1-text-0993", "type": "narration", "speaker": "", "content": "后者则是你真的站在窗边，看见乌云压下来，第一滴水已经砸在玻璃上。", "expression": "", "background": "evening", "next": "4-1-text-0994" },
    { "id": "4-1-text-0994", "type": "narration", "speaker": "", "content": "我喉咙发紧，想说点什么，却发现哪一句都太轻。", "expression": "", "background": "evening", "next": "4-1-text-0995" },
    { "id": "4-1-text-0995", "type": "narration", "speaker": "", "content": "皖萱把羽毛收回袖口里，站起身，努力冲我笑了一下。", "expression": "", "background": "evening", "next": "4-1-text-0996" },
    { "id": "4-1-text-0996", "type": "narration", "speaker": "", "content": "可那笑意太薄了，像一层快要碎掉的糖霜。", "expression": "", "background": "evening", "next": "4-1-text-0997" },
    { "id": "4-1-text-0997", "type": "dialogue", "speaker": "皖萱", "content": "我本来想……再晚一点告诉你的。", "expression": "", "background": "evening", "next": "4-1-text-0998" },
    { "id": "4-1-text-0998", "type": "dialogue", "speaker": "我", "content": "晚一点是多晚？", "expression": "", "background": "evening", "next": "4-1-text-0999" },
    { "id": "4-1-text-0999", "type": "narration", "speaker": "", "content": "她沉默。", "expression": "", "background": "evening", "next": "4-1-text-1000" },
    { "id": "4-1-text-1000", "type": "dialogue", "speaker": "我", "content": "等你已经站在阳台上，准备一句“我要走了”就结束？", "expression": "", "background": "evening", "next": "4-1-text-1001" },
    { "id": "4-1-text-1001", "type": "narration", "speaker": "", "content": "我的语气比想象中更冲一些。", "expression": "", "background": "evening", "next": "4-1-text-1002" },
    { "id": "4-1-text-1002", "type": "narration", "speaker": "", "content": "不是生气她隐瞒，更多是那种被现实突然当头砸下来的慌乱，找不到出口，只好先变成一点不好看的锋利。", "expression": "", "background": "evening", "next": "4-1-text-1003" },
    { "id": "4-1-text-1003", "type": "narration", "speaker": "", "content": "她明显愣了一下，接着垂下眼。", "expression": "", "background": "evening", "next": "4-1-text-1004" },
    { "id": "4-1-text-1004", "type": "dialogue", "speaker": "皖萱", "content": "对不起。", "expression": "", "background": "evening", "next": "4-1-text-1005" },
    { "id": "4-1-text-1005", "type": "narration", "speaker": "", "content": "那两个字一出来，我的火气一下就散了。", "expression": "", "background": "evening", "next": "4-1-text-1006" },
    { "id": "4-1-text-1006", "type": "narration", "speaker": "", "content": "因为她看起来比我更难受。", "expression": "", "background": "evening", "next": "4-1-text-1007" },
    { "id": "4-1-text-1007", "type": "narration", "speaker": "", "content": "她不是站在门外要离开的人。", "expression": "", "background": "evening", "next": "4-1-text-1008" },
    { "id": "4-1-text-1008", "type": "narration", "speaker": "", "content": "她是站在门槛上，不知道自己还能不能继续留下的人。", "expression": "", "background": "evening", "next": "4-1-text-1009" },
    { "id": "4-1-text-1009", "type": "narration", "speaker": "", "content": "我深吸了口气，强迫自己把声音放低一点。", "expression": "", "background": "evening", "next": "4-1-text-1010" },
    { "id": "4-1-text-1010", "type": "dialogue", "speaker": "我", "content": "所以现在呢？", "expression": "", "background": "evening", "next": "4-1-text-1011" },
    { "id": "4-1-text-1011", "type": "narration", "speaker": "", "content": "她抿了抿唇。", "expression": "", "background": "evening", "next": "4-1-text-1012" },
    { "id": "4-1-text-1012", "type": "dialogue", "speaker": "皖萱", "content": "现在……我必须做决定了。", "expression": "", "background": "evening", "next": "4-1-text-1013" },
    { "id": "4-1-text-1013", "type": "narration", "speaker": "", "content": "风从阳台灌进来，把窗帘吹得轻轻鼓起。她站在那片灰暗的光里，白色裙摆边缘都像被风吹得发冷。那一瞬间，她看上去终于不再像这一个月里那个会为了炸鸡和奶茶发亮、会窝在懒人沙发里抱着靠枕发呆的女孩。", "expression": "", "background": "evening", "next": "4-1-text-1014" },
    { "id": "4-1-text-1014", "type": "narration", "speaker": "", "content": "她更像一个真正的天使。", "expression": "", "background": "evening", "next": "4-1-text-1015" },
    { "id": "4-1-text-1015", "type": "narration", "speaker": "", "content": "可也正因为这样，我才更清楚地意识到——", "expression": "", "background": "evening", "next": "4-1-text-1016" },
    { "id": "4-1-text-1016", "type": "narration", "speaker": "", "content": "如果她决定留下，她要失去的东西，远比我这段时间一直想象的更多。", "expression": "", "background": "evening", "next": "4-2" },
    { "id": "4-2", "type": "marker", "markerTitle": "最后的晚餐，或者最后一次普通傍晚", "next": "4-2-text-1018" },
    { "id": "4-2-text-1018", "type": "narration", "speaker": "", "content": "在真正做出决定之前，我们谁都没有再提“走”或者“留”。", "expression": "", "background": "evening", "stageNote": "【场景】厨房 / 傍晚过渡至夜\n【BG】天色压暗，室内亮灯，锅中热气明显\n【BGM】几乎无，只余环境音", "next": "4-2-text-1019" },
    { "id": "4-2-text-1019", "type": "narration", "speaker": "", "content": "像是心照不宣地想替这一天多留一点普通。", "expression": "", "background": "evening", "next": "4-2-text-1020" },
    { "id": "4-2-text-1020", "type": "narration", "speaker": "", "content": "我打开冰箱，看着里面那些被我们一点点填满、又一点点吃掉的食材，忽然问她：", "expression": "", "background": "evening", "next": "4-2-text-1021" },
    { "id": "4-2-text-1021", "type": "dialogue", "speaker": "我", "content": "晚饭想吃什么？", "expression": "", "background": "evening", "next": "4-2-text-1022" },
    { "id": "4-2-text-1022", "type": "narration", "speaker": "", "content": "皖萱站在厨房门口，明显怔了一下。", "expression": "", "background": "evening", "next": "4-2-text-1023" },
    { "id": "4-2-text-1023", "type": "dialogue", "speaker": "皖萱", "content": "现在？", "expression": "", "background": "evening", "next": "4-2-text-1024" },
    { "id": "4-2-text-1024", "type": "dialogue", "speaker": "我", "content": "不然呢。", "expression": "", "background": "evening", "next": "4-2-text-1025" },
    { "id": "4-2-text-1025", "type": "narration", "speaker": "", "content": "再怎么重要的选择，也不能空着肚子做。", "expression": "", "background": "evening", "next": "4-2-text-1026" },
    { "id": "4-2-text-1026", "type": "narration", "speaker": "", "content": "她看着我，眼圈似乎微微发红，可最后还是很轻地弯了一下眼睛。", "expression": "", "background": "evening", "next": "4-2-text-1027" },
    { "id": "4-2-text-1027", "type": "dialogue", "speaker": "皖萱", "content": "那……我可以点菜吗？", "expression": "", "background": "evening", "next": "4-2-text-1028" },
    { "id": "4-2-text-1028", "type": "dialogue", "speaker": "我", "content": "今天特批。", "expression": "", "background": "evening", "next": "4-2-text-1029" },
    { "id": "4-2-text-1029", "type": "narration", "speaker": "", "content": "她真的认真想了很久。", "expression": "", "background": "evening", "next": "4-2-text-1030" },
    { "id": "4-2-text-1030", "type": "narration", "speaker": "", "content": "最后报出来的，却不是蛋糕、炸鸡，也不是任何昂贵复杂的东西。", "expression": "", "background": "evening", "next": "4-2-text-1031" },
    { "id": "4-2-text-1031", "type": "dialogue", "speaker": "皖萱", "content": "我想吃饭团。", "expression": "", "background": "evening", "next": "4-2-text-1032" },
    { "id": "4-2-text-1032", "type": "narration", "speaker": "", "content": "还有味噌汤。", "expression": "", "background": "evening", "next": "4-2-text-1033" },
    { "id": "4-2-text-1033", "type": "narration", "speaker": "", "content": "如果可以的话，再加一个玉子烧。", "expression": "", "background": "evening", "next": "4-2-text-1034" },
    { "id": "4-2-text-1034", "type": "narration", "speaker": "", "content": "我看着她，没有立刻说话。", "expression": "", "background": "evening", "next": "4-2-text-1035" },
    { "id": "4-2-text-1035", "type": "narration", "speaker": "", "content": "这些，都是我们最早一起做过、一起吃过的东西。", "expression": "", "background": "evening", "next": "4-2-text-1036" },
    { "id": "4-2-text-1036", "type": "narration", "speaker": "", "content": "她大概也意识到了，声音慢慢小下去。", "expression": "", "background": "evening", "next": "4-2-text-1037" },
    { "id": "4-2-text-1037", "type": "dialogue", "speaker": "皖萱", "content": "是不是有点……太简单了？", "expression": "", "background": "evening", "next": "4-2-text-1038" },
    { "id": "4-2-text-1038", "type": "narration", "speaker": "", "content": "我摇头。", "expression": "", "background": "evening", "next": "4-2-text-1039" },
    { "id": "4-2-text-1039", "type": "dialogue", "speaker": "我", "content": "不会。", "expression": "", "background": "evening", "next": "4-2-text-1040" },
    { "id": "4-2-text-1040", "type": "narration", "speaker": "", "content": "正好。", "expression": "", "background": "evening", "next": "4-2-text-1041" },
    { "id": "4-2-text-1041", "type": "narration", "speaker": "", "content": "于是傍晚就在切菜、洗米、打蛋、开火的细碎声音里慢慢过去。", "expression": "", "background": "evening", "next": "4-2-text-1042" },
    { "id": "4-2-text-1042", "type": "narration", "speaker": "", "content": "米饭蒸熟的时候，厨房里再一次腾起那种很温柔的香。不是刺激味蕾的浓郁香气，只是带着谷物甜意的白雾，一点点漫开，像把整个空间重新洗过一遍。味噌汤的底很快煮好，海带和豆腐在浅色汤里安静浮沉；鸡蛋液倒进方锅时发出轻轻的“滋”声，薄薄一层先凝起来，再被我慢慢卷成柔软的层次。", "expression": "", "background": "evening", "next": "4-2-text-1043" },
    { "id": "4-2-text-1043", "type": "narration", "speaker": "", "content": "皖萱站在旁边，看着看着，忽然开口。", "expression": "", "background": "evening", "next": "4-2-text-1044" },
    { "id": "4-2-text-1044", "type": "dialogue", "speaker": "皖萱", "content": "原来最后最想吃的，不一定是最好吃的。", "expression": "", "background": "evening", "next": "4-2-text-1045" },
    { "id": "4-2-text-1045", "type": "narration", "speaker": "", "content": "我把玉子烧翻面，低声应了一句。", "expression": "", "background": "evening", "next": "4-2-text-1046" },
    { "id": "4-2-text-1046", "type": "dialogue", "speaker": "我", "content": "那是什么？", "expression": "", "background": "evening", "next": "4-2-text-1047" },
    { "id": "4-2-text-1047", "type": "dialogue", "speaker": "皖萱", "content": "是最像“回来过”的。", "expression": "", "background": "evening", "next": "4-2-text-1048" },
    { "id": "4-2-text-1048", "type": "narration", "speaker": "", "content": "我手上的动作停了一瞬。", "expression": "", "background": "evening", "next": "4-2-text-1049" },
    { "id": "4-2-text-1049", "type": "narration", "speaker": "", "content": "米饭晾到刚好能握的时候，她也走过来洗手。", "expression": "", "background": "evening", "next": "4-2-text-1050" },
    { "id": "4-2-text-1050", "type": "narration", "speaker": "", "content": "这次她没有像第一次那样手忙脚乱。", "expression": "", "background": "evening", "next": "4-2-text-1051" },
    { "id": "4-2-text-1051", "type": "narration", "speaker": "", "content": "她的动作熟练了很多，掌心也更知道该怎么去接住那团温热的米饭。可真正握起来的时候，她还是比平时慢。", "expression": "", "background": "evening", "next": "4-2-text-1052" },
    { "id": "4-2-text-1052", "type": "narration", "speaker": "", "content": "我知道，不是因为不会。", "expression": "", "background": "evening", "next": "4-2-text-1053" },
    { "id": "4-2-text-1053", "type": "narration", "speaker": "", "content": "是因为舍不得太快做完。", "expression": "", "background": "evening", "next": "4-2-text-1054" },
    { "id": "4-2-text-1054", "type": "narration", "speaker": "", "content": "饭团一个个摆在盘里，形状不算完全整齐，有两个边角还略微歪着。可那种不工整反而让它们显得更像“我们一起做出来的东西”。", "expression": "", "background": "evening", "next": "4-2-text-1055" },
    { "id": "4-2-text-1055", "type": "narration", "speaker": "", "content": "坐下吃饭时，外面已经开始下雨。", "expression": "", "background": "evening", "next": "4-2-text-1056" },
    { "id": "4-2-text-1056", "type": "narration", "speaker": "", "content": "雨点先是零零落落，后来很快密起来，打在阳台玻璃上，发出一阵又一阵细碎而连续的声响。客厅的灯开着，餐桌不大，饭团、玉子烧和味噌汤放在一起，热气把空气都熏得发软。", "expression": "", "background": "evening", "next": "4-2-text-1057" },
    { "id": "4-2-text-1057", "type": "narration", "speaker": "", "content": "皖萱先捧起汤碗。", "expression": "", "background": "evening", "next": "4-2-text-1058" },
    { "id": "4-2-text-1058", "type": "narration", "speaker": "", "content": "她喝了一口，闭了闭眼。", "expression": "", "background": "evening", "next": "4-2-text-1059" },
    { "id": "4-2-text-1059", "type": "dialogue", "speaker": "皖萱", "content": "还是这个味道。", "expression": "", "background": "evening", "next": "4-2-text-1060" },
    { "id": "4-2-text-1060", "type": "dialogue", "speaker": "我", "content": "不然呢。", "expression": "", "background": "evening", "next": "4-2-text-1061" },
    { "id": "4-2-text-1061", "type": "narration", "speaker": "", "content": "味噌汤总不能临时叛变。", "expression": "", "background": "evening", "next": "4-2-text-1062" },
    { "id": "4-2-text-1062", "type": "narration", "speaker": "", "content": "她被逗得笑了一下。", "expression": "", "background": "evening", "next": "4-2-text-1063" },
    { "id": "4-2-text-1063", "type": "narration", "speaker": "", "content": "然后，她咬了一口饭团。", "expression": "", "background": "evening", "next": "4-2-text-1064" },
    { "id": "4-2-text-1064", "type": "narration", "speaker": "", "content": "海苔微微回潮，没有第一次那样脆，却更贴合米饭。里面包着的金枪鱼和蛋黄酱咸香柔润，米粒带着掌心余温，越嚼越能尝到最普通也最安稳的甜。", "expression": "", "background": "evening", "next": "4-2-text-1065" },
    { "id": "4-2-text-1065", "type": "narration", "speaker": "", "content": "她慢慢咽下去，眼睛里竟然一点一点浮起水光。", "expression": "", "background": "evening", "next": "4-2-text-1066" },
    { "id": "4-2-text-1066", "type": "dialogue", "speaker": "皖萱", "content": "我第一次吃的时候，就觉得它很安静。", "expression": "", "background": "evening", "next": "4-2-text-1067" },
    { "id": "4-2-text-1067", "type": "narration", "speaker": "", "content": "我放下筷子，看着她。", "expression": "", "background": "evening", "next": "4-2-text-1068" },
    { "id": "4-2-text-1068", "type": "dialogue", "speaker": "皖萱", "content": "现在还是很安静。", "expression": "", "background": "evening", "next": "4-2-text-1069" },
    { "id": "4-2-text-1069", "type": "narration", "speaker": "", "content": "可是比那时候更难过一点。", "expression": "", "background": "evening", "next": "4-2-text-1070" },
    { "id": "4-2-text-1070", "type": "narration", "speaker": "", "content": "我没有说“别难过”。", "expression": "", "background": "evening", "next": "4-2-text-1071" },
    { "id": "4-2-text-1071", "type": "narration", "speaker": "", "content": "因为这种时候，安慰太像在否认她真正正在经历的东西。", "expression": "", "background": "evening", "next": "4-2-text-1072" },
    { "id": "4-2-text-1072", "type": "narration", "speaker": "", "content": "我只是伸手，把她面前那块她最喜欢的玉子烧往前推了一点。", "expression": "", "background": "evening", "next": "4-2-text-1073" },
    { "id": "4-2-text-1073", "type": "dialogue", "speaker": "我", "content": "先吃完。", "expression": "", "background": "evening", "next": "4-2-text-1074" },
    { "id": "4-2-text-1074", "type": "narration", "speaker": "", "content": "她低头“嗯”了一声，真的又咬了一口玉子烧。", "expression": "", "background": "evening", "next": "4-2-text-1075" },
    { "id": "4-2-text-1075", "type": "narration", "speaker": "", "content": "鸡蛋的甜和柔软在口中慢慢散开，表面微微焦香，里面却还是湿润的。她认真嚼着，像要把这顿饭的每一个味道都牢牢记住。", "expression": "", "background": "evening", "next": "4-2-text-1076" },
    { "id": "4-2-text-1076", "type": "narration", "speaker": "", "content": "我也低头吃了一口。", "expression": "", "background": "evening", "next": "4-2-text-1077" },
    { "id": "4-2-text-1077", "type": "narration", "speaker": "", "content": "明明这些东西我做过很多次，今天却每一种都尝得格外清楚。", "expression": "", "background": "evening", "next": "4-2-text-1078" },
    { "id": "4-2-text-1078", "type": "narration", "speaker": "", "content": "米饭的热，蛋液的甜，味噌的咸，海带和豆腐被热汤泡软后的安静口感。它们没有惊喜，也不喧哗，只是很稳定地存在，像日子本身。", "expression": "", "background": "evening", "next": "4-2-text-1079" },
    { "id": "4-2-text-1079", "type": "narration", "speaker": "", "content": "我忽然明白，为什么她最后会选这一顿。", "expression": "", "background": "evening", "next": "4-2-text-1080" },
    { "id": "4-2-text-1080", "type": "narration", "speaker": "", "content": "因为真正让人放不下的，往往不是最盛大的快乐。", "expression": "", "background": "evening", "next": "4-2-text-1081" },
    { "id": "4-2-text-1081", "type": "narration", "speaker": "", "content": "而是那些你以为以后还会有很多次，所以从来没认真告别过的平常。", "expression": "", "background": "evening", "next": "4-3" },
    { "id": "4-3", "type": "marker", "markerTitle": "玩家决策前：记忆回廊", "next": "4-3-text-1083" },
    { "id": "4-3-text-1083", "type": "narration", "speaker": "", "content": "晚饭结束以后，雨还没有停。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 夜 / 雨声不止\n【演出】进入视觉小说选择前的情绪总结段", "next": "4-3-text-1084" },
    { "id": "4-3-text-1084", "type": "narration", "speaker": "", "content": "我们把碗一起洗了，厨房收拾得很干净，像什么也没发生过。可回到客厅时，谁都知道，这已经不可能是一个普通的夜晚了。", "expression": "", "background": "night", "next": "4-3-text-1085" },
    { "id": "4-3-text-1085", "type": "narration", "speaker": "", "content": "皖萱站在阳台门前，背对着我。", "expression": "", "background": "night", "next": "4-3-text-1086" },
    { "id": "4-3-text-1086", "type": "narration", "speaker": "", "content": "窗外是一整片被雨水揉开的夜色。她白色的身影映在玻璃上，和外面的霓虹叠在一起，像随时会被冲淡。", "expression": "", "background": "night", "next": "4-3-text-1087" },
    { "id": "4-3-text-1087", "type": "narration", "speaker": "", "content": "我走到她身后两步的位置停下。", "expression": "", "background": "night", "next": "4-3-text-1088" },
    { "id": "4-3-text-1088", "type": "dialogue", "speaker": "我", "content": "还剩多久？", "expression": "", "background": "night", "next": "4-3-text-1089" },
    { "id": "4-3-text-1089", "type": "narration", "speaker": "", "content": "她没有回头。", "expression": "", "background": "night", "next": "4-3-text-1090" },
    { "id": "4-3-text-1090", "type": "dialogue", "speaker": "皖萱", "content": "日落已经过了。", "expression": "", "background": "night", "next": "4-3-text-1091" },
    { "id": "4-3-text-1091", "type": "narration", "speaker": "", "content": "严格来说，是“召回窗口”还没完全关上。", "expression": "", "background": "night", "next": "4-3-text-1092" },
    { "id": "4-3-text-1092", "type": "dialogue", "speaker": "我", "content": "如果关上会怎样？", "expression": "", "background": "night", "next": "4-3-text-1093" },
    { "id": "4-3-text-1093", "type": "dialogue", "speaker": "皖萱", "content": "如果我选择回去，就不能再拖了。", "expression": "", "background": "night", "next": "4-3-text-1094" },
    { "id": "4-3-text-1094", "type": "narration", "speaker": "", "content": "如果我选择留下……", "expression": "", "background": "night", "next": "4-3-text-1095" },
    { "id": "4-3-text-1095", "type": "narration", "speaker": "", "content": "她顿了顿，声音轻下来。", "expression": "", "background": "night", "next": "4-3-text-1096" },
    { "id": "4-3-text-1096", "type": "dialogue", "speaker": "皖萱", "content": "那也该在今晚之前决定。", "expression": "", "background": "night", "next": "4-3-text-1097" },
    { "id": "4-3-text-1097", "type": "narration", "speaker": "", "content": "客厅里只剩雨声。", "expression": "", "background": "night", "next": "4-3-text-1098" },
    { "id": "4-3-text-1098", "type": "narration", "speaker": "", "content": "我看着她的背影，脑子里却忽然涌上很多很零碎的画面。", "expression": "", "background": "night", "next": "4-3-text-1099" },
    { "id": "4-3-text-1099", "type": "narration", "speaker": "", "content": "第一口草莓蛋糕沾在她唇边的奶油。", "expression": "", "background": "night", "next": "4-3-text-1100" },
    { "id": "4-3-text-1100", "type": "narration", "speaker": "", "content": "她站在厨房门口说“幸福在生成的时候，会发出这样的声音”。", "expression": "", "background": "night", "next": "4-3-text-1101" },
    { "id": "4-3-text-1101", "type": "narration", "speaker": "", "content": "她把最后一块炸鸡留给我。", "expression": "", "background": "night", "next": "4-3-text-1102" },
    { "id": "4-3-text-1102", "type": "narration", "speaker": "", "content": "她在便利店门口捧着关东煮，说“晚上吃到这个，就会觉得算了，也没有那么糟”。", "expression": "", "background": "night", "next": "4-3-text-1103" },
    { "id": "4-3-text-1103", "type": "narration", "speaker": "", "content": "她半夜被饿醒，煮一碗面，问我以后会不会想起她。", "expression": "", "background": "night", "next": "4-3-text-1104" },
    { "id": "4-3-text-1104", "type": "narration", "speaker": "", "content": "原来所谓“回忆”，不是电影那样宏大的蒙太奇。", "expression": "", "background": "night", "next": "4-3-text-1105" },
    { "id": "4-3-text-1105", "type": "narration", "speaker": "", "content": "它更像食物残留在舌尖上的味道。", "expression": "", "background": "night", "next": "4-3-text-1106" },
    { "id": "4-3-text-1106", "type": "narration", "speaker": "", "content": "平时不觉得怎样，真要失去时，才发现原来早就一层一层渗进身体里，成了你的一部分。", "expression": "", "background": "night", "next": "4-3-text-1107" },
    { "id": "4-3-text-1107", "type": "narration", "speaker": "", "content": "皖萱终于转过身。", "expression": "", "background": "night", "next": "4-3-text-1108" },
    { "id": "4-3-text-1108", "type": "narration", "speaker": "", "content": "她看着我，神情很安静。", "expression": "", "background": "night", "next": "4-3-text-1109" },
    { "id": "4-3-text-1109", "type": "narration", "speaker": "", "content": "安静得像终于走到了无法再往后拖延的地方。", "expression": "", "background": "night", "next": "4-3-text-1110" },
    { "id": "4-3-text-1110", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "4-3-text-1111" },
    { "id": "4-3-text-1111", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "4-3-text-1112" },
    { "id": "4-3-text-1112", "type": "dialogue", "speaker": "皖萱", "content": "我现在必须问你一次。", "expression": "", "background": "night", "next": "4-3-text-1113" },
    { "id": "4-3-text-1113", "type": "narration", "speaker": "", "content": "而且，只能问这一次。", "expression": "", "background": "night", "next": "4-3-text-1114" },
    { "id": "4-3-text-1114", "type": "narration", "speaker": "", "content": "她深吸了一口气。", "expression": "", "background": "night", "next": "4-3-text-1115" },
    { "id": "4-3-text-1115", "type": "dialogue", "speaker": "皖萱", "content": "如果我留下来。", "expression": "", "background": "night", "next": "4-3-text-1116" },
    { "id": "4-3-text-1116", "type": "narration", "speaker": "", "content": "我会失去羽翼，失去法力，也失去天界最后给我的退路。", "expression": "", "background": "night", "next": "4-3-text-1117" },
    { "id": "4-3-text-1117", "type": "narration", "speaker": "", "content": "以后我可能会像真正的人类一样生病、受伤、变老，也会有很多做不到的事。", "expression": "", "background": "night", "next": "4-3-text-1118" },
    { "id": "4-3-text-1118", "type": "narration", "speaker": "", "content": "她看着我，眼底那层水光轻轻晃着。", "expression": "", "background": "night", "next": "4-3-text-1119" },
    { "id": "4-3-text-1119", "type": "dialogue", "speaker": "皖萱", "content": "这样的话，你还希望我留下吗？", "expression": "", "background": "night", "next": "结局分支-A-HE永不落幕的茶会" },
    { "id": "结局分支-A-HE永不落幕的茶会", "type": "marker", "markerTitle": "结局分支 A：HE《永不落幕的茶会》", "next": "5A-1" },
    { "id": "5A-1", "type": "marker", "markerTitle": "拉住她的手", "next": "4-3-choice" },
    { "id": "4-3-choice", "type": "choice", "choices": [{ "label": "拉住她：“留下来。”", "next": "5A-1" }, { "label": "松开手：“回去吧。”", "next": "5B-1" }] },
    { "id": "5A-1-text-1123", "type": "narration", "speaker": "", "content": "我的回答几乎没有经过思考。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 夜 / 雨声渐缓\n【BGM】压抑后缓慢抬升的温柔钢琴", "next": "5A-1-text-1124" },
    { "id": "5A-1-text-1124", "type": "narration", "speaker": "", "content": "或者说，这个答案其实早就写在了我每一次迟疑、每一次克制、每一次不敢逼她选的时候。", "expression": "", "background": "night", "next": "5A-1-text-1125" },
    { "id": "5A-1-text-1125", "type": "narration", "speaker": "", "content": "我朝她走过去。", "expression": "", "background": "night", "next": "5A-1-text-1126" },
    { "id": "5A-1-text-1126", "type": "narration", "speaker": "", "content": "一步。两步。", "expression": "", "background": "night", "next": "5A-1-text-1127" },
    { "id": "5A-1-text-1127", "type": "narration", "speaker": "", "content": "然后，在她准备移开视线之前，伸手握住了她的手腕。", "expression": "", "background": "night", "next": "5A-1-text-1128" },
    { "id": "5A-1-text-1128", "type": "narration", "speaker": "", "content": "她明显颤了一下。", "expression": "", "background": "night", "next": "5A-1-text-1129" },
    { "id": "5A-1-text-1129", "type": "dialogue", "speaker": "我", "content": "留下来。", "expression": "", "background": "night", "next": "5A-1-text-1130" },
    { "id": "5A-1-text-1130", "type": "narration", "speaker": "", "content": "这三个字一出口，我才发现自己的嗓子已经哑了。", "expression": "", "background": "night", "next": "5A-1-text-1131" },
    { "id": "5A-1-text-1131", "type": "narration", "speaker": "", "content": "我握着她的手，没有很用力，却也没有给她挣脱的余地。", "expression": "", "background": "night", "next": "5A-1-text-1132" },
    { "id": "5A-1-text-1132", "type": "narration", "speaker": "", "content": "像不是在困住她，而是在把自己所有不敢说得太满的舍不得，都安安稳稳放进这一点温度里。", "expression": "", "background": "night", "next": "5A-1-text-1133" },
    { "id": "5A-1-text-1133", "type": "dialogue", "speaker": "我", "content": "如果你回去了——", "expression": "", "background": "night", "next": "5A-1-text-1134" },
    { "id": "5A-1-text-1134", "type": "narration", "speaker": "", "content": "我停了一下，忽然笑了，笑得有点难看。", "expression": "", "background": "night", "next": "5A-1-text-1135" },
    { "id": "5A-1-text-1135", "type": "dialogue", "speaker": "我", "content": "谁来帮我消耗冰箱里的库存？", "expression": "", "background": "night", "next": "5A-1-text-1136" },
    { "id": "5A-1-text-1136", "type": "narration", "speaker": "", "content": "她怔住。", "expression": "", "background": "night", "next": "5A-1-text-1137" },
    { "id": "5A-1-text-1137", "type": "narration", "speaker": "", "content": "大概没想到在这种时候，我说出来的第一句会是这个。", "expression": "", "background": "night", "next": "5A-1-text-1138" },
    { "id": "5A-1-text-1138", "type": "narration", "speaker": "", "content": "可下一秒，她眼睛里那层晃了很久的水光，终于一下子碎开了。", "expression": "", "background": "night", "next": "5A-1-text-1139" },
    { "id": "5A-1-text-1139", "type": "dialogue", "speaker": "皖萱", "content": "……你这种时候还说这个。", "expression": "", "background": "night", "next": "5A-1-text-1140" },
    { "id": "5A-1-text-1140", "type": "narration", "speaker": "", "content": "我也红了眼，却还是尽量把语气放轻。", "expression": "", "background": "night", "next": "5A-1-text-1141" },
    { "id": "5A-1-text-1141", "type": "dialogue", "speaker": "我", "content": "因为如果我说得太认真，你可能会更害怕。", "expression": "", "background": "night", "next": "5A-1-text-1142" },
    { "id": "5A-1-text-1142", "type": "narration", "speaker": "", "content": "我望着她。", "expression": "", "background": "night", "next": "5A-1-text-1143" },
    { "id": "5A-1-text-1143", "type": "dialogue", "speaker": "我", "content": "可我还是得告诉你。", "expression": "", "background": "night", "next": "5A-1-text-1144" },
    { "id": "5A-1-text-1144", "type": "narration", "speaker": "", "content": "我深吸了一口气，把那些在心里绕了很多天的话，终于一寸一寸说出来。", "expression": "", "background": "night", "next": "5A-1-text-1145" },
    { "id": "5A-1-text-1145", "type": "dialogue", "speaker": "我", "content": "我希望你留下。", "expression": "", "background": "night", "next": "5A-1-text-1146" },
    { "id": "5A-1-text-1146", "type": "narration", "speaker": "", "content": "不是因为你是天使，不是因为你会发光，也不是因为你让我的生活突然变得像故事。", "expression": "", "background": "night", "next": "5A-1-text-1147" },
    { "id": "5A-1-text-1147", "type": "narration", "speaker": "", "content": "我握紧她的手。", "expression": "", "background": "night", "next": "5A-1-text-1148" },
    { "id": "5A-1-text-1148", "type": "dialogue", "speaker": "我", "content": "只是因为，是你。", "expression": "", "background": "night", "next": "5A-1-text-1149" },
    { "id": "5A-1-text-1149", "type": "narration", "speaker": "", "content": "她眼泪一下子掉下来。", "expression": "", "background": "night", "next": "5A-1-text-1150" },
    { "id": "5A-1-text-1150", "type": "narration", "speaker": "", "content": "不是嚎啕，也不是控制不住的崩溃。", "expression": "", "background": "night", "next": "5A-1-text-1151" },
    { "id": "5A-1-text-1151", "type": "narration", "speaker": "", "content": "只是很安静地、很快地顺着脸颊滑下去，像终于承认自己已经没办法再退回安全的地方。", "expression": "", "background": "night", "next": "5A-1-text-1152" },
    { "id": "5A-1-text-1152", "type": "dialogue", "speaker": "皖萱", "content": "可是会很疼。", "expression": "", "background": "night", "next": "5A-1-text-1153" },
    { "id": "5A-1-text-1153", "type": "dialogue", "speaker": "我", "content": "我知道。", "expression": "", "background": "night", "next": "5A-1-text-1154" },
    { "id": "5A-1-text-1154", "type": "dialogue", "speaker": "皖萱", "content": "而且以后我可能真的只是一个很普通的人类。", "expression": "", "background": "night", "next": "5A-1-text-1155" },
    { "id": "5A-1-text-1155", "type": "dialogue", "speaker": "我", "content": "那就普通地留在这里。", "expression": "", "background": "night", "next": "5A-1-text-1156" },
    { "id": "5A-1-text-1156", "type": "dialogue", "speaker": "皖萱", "content": "万一以后你后悔呢？", "expression": "", "background": "night", "next": "5A-1-text-1157" },
    { "id": "5A-1-text-1157", "type": "narration", "speaker": "", "content": "我摇头。", "expression": "", "background": "night", "next": "5A-1-text-1158" },
    { "id": "5A-1-text-1158", "type": "dialogue", "speaker": "我", "content": "你不是问过我，房子为什么以前总是那么安静吗？", "expression": "", "background": "night", "next": "5A-1-text-1159" },
    { "id": "5A-1-text-1159", "type": "narration", "speaker": "", "content": "她怔怔看着我。", "expression": "", "background": "night", "next": "5A-1-text-1160" },
    { "id": "5A-1-text-1160", "type": "dialogue", "speaker": "我", "content": "因为在你来之前，这里只是住处。", "expression": "", "background": "night", "next": "5A-1-text-1161" },
    { "id": "5A-1-text-1161", "type": "narration", "speaker": "", "content": "你来以后，它才慢慢变成了家。", "expression": "", "background": "night", "next": "5A-1-text-1162" },
    { "id": "5A-1-text-1162", "type": "narration", "speaker": "", "content": "我停了停。", "expression": "", "background": "night", "next": "5A-1-text-1163" },
    { "id": "5A-1-text-1163", "type": "dialogue", "speaker": "我", "content": "所以不是我在给你退路。", "expression": "", "background": "night", "next": "5A-1-text-1164" },
    { "id": "5A-1-text-1164", "type": "narration", "speaker": "", "content": "是你早就已经成了我的去处。", "expression": "", "background": "night", "next": "5A-1-text-1165" },
    { "id": "5A-1-text-1165", "type": "narration", "speaker": "", "content": "她像被这句话彻底击中，眼泪掉得更凶，却偏偏又笑了出来。", "expression": "", "background": "night", "next": "5A-1-text-1166" },
    { "id": "5A-1-text-1166", "type": "dialogue", "speaker": "皖萱", "content": "……太狡猾了。", "expression": "", "background": "night", "next": "5A-1-text-1167" },
    { "id": "5A-1-text-1167", "type": "narration", "speaker": "", "content": "我抬手替她擦掉眼泪，指腹碰到她脸侧时，仍旧像第一次替她拭掉面粉那样柔软。", "expression": "", "background": "night", "next": "5A-1-text-1168" },
    { "id": "5A-1-text-1168", "type": "dialogue", "speaker": "我", "content": "那你还要走吗？", "expression": "", "background": "night", "next": "5A-1-text-1169" },
    { "id": "5A-1-text-1169", "type": "narration", "speaker": "", "content": "她望着我。", "expression": "", "background": "night", "next": "5A-1-text-1170" },
    { "id": "5A-1-text-1170", "type": "narration", "speaker": "", "content": "很久，很认真，像要把我的表情、我的声音、这间屋子的光和雨声一起看进心里。", "expression": "", "background": "night", "next": "5A-1-text-1171" },
    { "id": "5A-1-text-1171", "type": "narration", "speaker": "", "content": "最后，她轻轻摇头。", "expression": "", "background": "night", "next": "5A-1-text-1172" },
    { "id": "5A-1-text-1172", "type": "dialogue", "speaker": "皖萱", "content": "不走了。", "expression": "", "background": "night", "next": "5A-2" },
    { "id": "5A-2", "type": "marker", "markerTitle": "失去羽翼的瞬间", "next": "5A-2-text-1174" },
    { "id": "5A-2-text-1174", "type": "narration", "speaker": "", "content": "决定说出口以后，很多事反而变得安静了。", "expression": "", "background": "night", "stageNote": "【场景】阳台 / 夜 / 雨停后微光\n【演出】光效、粒子、羽翼消散\n【BGM】由空灵转温暖", "next": "5A-2-text-1175" },
    { "id": "5A-2-text-1175", "type": "narration", "speaker": "", "content": "像一场拉扯了很久的风，终于找到了落点。", "expression": "", "background": "night", "next": "5A-2-text-1176" },
    { "id": "5A-2-text-1176", "type": "narration", "speaker": "", "content": "皖萱站到阳台中央。", "expression": "", "background": "night", "next": "5A-2-text-1177" },
    { "id": "5A-2-text-1177", "type": "narration", "speaker": "", "content": "雨不知什么时候小了，只剩檐角还在往下滴水。云层后面隐约透出一点月光，把湿漉漉的栏杆照得发亮。", "expression": "", "background": "night", "next": "5A-2-text-1178" },
    { "id": "5A-2-text-1178", "type": "narration", "speaker": "", "content": "她回头看我。", "expression": "", "background": "night", "next": "5A-2-text-1179" },
    { "id": "5A-2-text-1179", "type": "narration", "speaker": "", "content": "第一次，没有用任何“调查”“任务”或者“实习天使”的理由把自己藏起来。", "expression": "", "background": "night", "next": "5A-2-text-1180" },
    { "id": "5A-2-text-1180", "type": "dialogue", "speaker": "皖萱", "content": "那我开始了。", "expression": "", "background": "night", "next": "5A-2-text-1181" },
    { "id": "5A-2-text-1181", "type": "narration", "speaker": "", "content": "我点头。", "expression": "", "background": "night", "next": "5A-2-text-1182" },
    { "id": "5A-2-text-1182", "type": "narration", "speaker": "", "content": "喉咙紧得发不出别的话，只能朝她伸出手。", "expression": "", "background": "night", "next": "5A-2-text-1183" },
    { "id": "5A-2-text-1183", "type": "narration", "speaker": "", "content": "她看了看，走过来，把自己的手放进我掌心。", "expression": "", "background": "night", "next": "5A-2-text-1184" },
    { "id": "5A-2-text-1184", "type": "narration", "speaker": "", "content": "下一秒，她背后的羽翼缓缓展开。", "expression": "", "background": "night", "next": "5A-2-text-1185" },
    { "id": "5A-2-text-1185", "type": "narration", "speaker": "", "content": "不像第一次落进我家阳台时那样带着一点狼狈的凌乱，而是完整、安静、近乎圣洁地舒展在夜里。每一片羽都像薄薄的光铸成，边缘泛着极淡的金，轻得像碰一下就会化开。", "expression": "", "background": "night", "next": "5A-2-text-1186" },
    { "id": "5A-2-text-1186", "type": "narration", "speaker": "", "content": "可很快，那光开始发颤。", "expression": "", "background": "night", "next": "5A-2-text-1187" },
    { "id": "5A-2-text-1187", "type": "narration", "speaker": "", "content": "皖萱皱起眉，指尖一下收紧。", "expression": "", "background": "night", "next": "5A-2-text-1188" },
    { "id": "5A-2-text-1188", "type": "narration", "speaker": "", "content": "我立刻握住她的手。", "expression": "", "background": "night", "next": "5A-2-text-1189" },
    { "id": "5A-2-text-1189", "type": "narration", "speaker": "", "content": "她说过，会疼。", "expression": "", "background": "night", "next": "5A-2-text-1190" },
    { "id": "5A-2-text-1190", "type": "narration", "speaker": "", "content": "可真正看见的时候，我才明白“疼”原来可以这样明显地写在一个人身上。", "expression": "", "background": "night", "next": "5A-2-text-1191" },
    { "id": "5A-2-text-1191", "type": "narration", "speaker": "", "content": "她背后的光一寸一寸碎开，像有人从羽翼最深处缓慢抽走支撑它存在的力量。最先散掉的是边缘，那些细小的光粒脱离羽面，浮到空中，又很快像萤火一样无声熄灭。接着是中间。原本完整的羽翼逐渐透明，像一场雪正在被夜风吹散。", "expression": "", "background": "night", "next": "5A-2-text-1192" },
    { "id": "5A-2-text-1192", "type": "narration", "speaker": "", "content": "皖萱咬着唇，肩膀微微发抖，额角很快沁出细密的汗。", "expression": "", "background": "night", "next": "5A-2-text-1193" },
    { "id": "5A-2-text-1193", "type": "narration", "speaker": "", "content": "我心里一紧，下意识想把她拉回来。", "expression": "", "background": "night", "next": "5A-2-text-1194" },
    { "id": "5A-2-text-1194", "type": "dialogue", "speaker": "我", "content": "皖萱——", "expression": "", "background": "night", "next": "5A-2-text-1195" },
    { "id": "5A-2-text-1195", "type": "narration", "speaker": "", "content": "她却摇头。", "expression": "", "background": "night", "next": "5A-2-text-1196" },
    { "id": "5A-2-text-1196", "type": "dialogue", "speaker": "皖萱", "content": "别松手。", "expression": "", "background": "night", "next": "5A-2-text-1197" },
    { "id": "5A-2-text-1197", "type": "narration", "speaker": "", "content": "于是我只能握得更紧。", "expression": "", "background": "night", "next": "5A-2-text-1198" },
    { "id": "5A-2-text-1198", "type": "narration", "speaker": "", "content": "她整个人都在发颤，可眼神却没有退。", "expression": "", "background": "night", "next": "5A-2-text-1199" },
    { "id": "5A-2-text-1199", "type": "narration", "speaker": "", "content": "那里面有疼，也有害怕，可更多的是某种终于决定之后的执拗。", "expression": "", "background": "night", "next": "5A-2-text-1200" },
    { "id": "5A-2-text-1200", "type": "narration", "speaker": "", "content": "像她第一次认真学着捏饭团时那样，明明知道会散，也还是小心又固执地想把它握成形。", "expression": "", "background": "night", "next": "5A-2-text-1201" },
    { "id": "5A-2-text-1201", "type": "narration", "speaker": "", "content": "最后一片光羽碎掉的时候，夜里忽然安静得可怕。", "expression": "", "background": "night", "next": "5A-2-text-1202" },
    { "id": "5A-2-text-1202", "type": "narration", "speaker": "", "content": "那圈一直很淡、像金色呼吸一样悬在她头顶的光，也随之裂开。", "expression": "", "background": "night", "next": "5A-2-text-1203" },
    { "id": "5A-2-text-1203", "type": "narration", "speaker": "", "content": "没有轰然破碎的声响，只是很轻地震了一下，然后像被风吹散的糖霜，化成一小片一小片细碎的亮粉，落下来，落到她的发梢、肩头，也落到我们交握的手上。", "expression": "", "background": "night", "next": "5A-2-text-1204" },
    { "id": "5A-2-text-1204", "type": "narration", "speaker": "", "content": "温温的。", "expression": "", "background": "night", "next": "5A-2-text-1205" },
    { "id": "5A-2-text-1205", "type": "narration", "speaker": "", "content": "一点也不冷。", "expression": "", "background": "night", "next": "5A-2-text-1206" },
    { "id": "5A-2-text-1206", "type": "narration", "speaker": "", "content": "皖萱腿一软，整个人向前倒下来。", "expression": "", "background": "night", "next": "5A-2-text-1207" },
    { "id": "5A-2-text-1207", "type": "narration", "speaker": "", "content": "我立刻接住她。", "expression": "", "background": "night", "next": "5A-2-text-1208" },
    { "id": "5A-2-text-1208", "type": "narration", "speaker": "", "content": "她撞进我怀里的那一下很轻，却让我胸口猛地发热。她呼吸有些乱，脸色苍白，可额头贴在我肩上时，却像终于从某种悬空已久的地方，真正落到了实处。", "expression": "", "background": "night", "next": "5A-2-text-1209" },
    { "id": "5A-2-text-1209", "type": "narration", "speaker": "", "content": "过了很久，她才很轻地开口。", "expression": "", "background": "night", "next": "5A-2-text-1210" },
    { "id": "5A-2-text-1210", "type": "dialogue", "speaker": "皖萱", "content": "……好像，真的回不去了。", "expression": "", "background": "night", "next": "5A-2-text-1211" },
    { "id": "5A-2-text-1211", "type": "narration", "speaker": "", "content": "我低头，把她抱紧了一点。", "expression": "", "background": "night", "next": "5A-2-text-1212" },
    { "id": "5A-2-text-1212", "type": "dialogue", "speaker": "我", "content": "那就别回了。", "expression": "", "background": "night", "next": "5A-2-text-1213" },
    { "id": "5A-2-text-1213", "type": "narration", "speaker": "", "content": "她在我怀里安静了几秒，忽然笑了一下。", "expression": "", "background": "night", "next": "5A-2-text-1214" },
    { "id": "5A-2-text-1214", "type": "narration", "speaker": "", "content": "那笑很轻，带着疲惫，也带着刚哭过后的鼻音。", "expression": "", "background": "night", "next": "5A-2-text-1215" },
    { "id": "5A-2-text-1215", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "5A-2-text-1216" },
    { "id": "5A-2-text-1216", "type": "dialogue", "speaker": "我", "content": "嗯？", "expression": "", "background": "night", "next": "5A-2-text-1217" },
    { "id": "5A-2-text-1217", "type": "dialogue", "speaker": "皖萱", "content": "我现在应该算……正式入职你家了吗？", "expression": "", "background": "night", "next": "5A-2-text-1218" },
    { "id": "5A-2-text-1218", "type": "narration", "speaker": "", "content": "我没忍住，笑出来。", "expression": "", "background": "night", "next": "5A-2-text-1219" },
    { "id": "5A-2-text-1219", "type": "narration", "speaker": "", "content": "眼眶明明还热着，笑意却先一步跑了出来。", "expression": "", "background": "night", "next": "5A-2-text-1220" },
    { "id": "5A-2-text-1220", "type": "dialogue", "speaker": "我", "content": "试用期满，直接转正。", "expression": "", "background": "night", "next": "5A-2-text-1221" },
    { "id": "5A-2-text-1221", "type": "narration", "speaker": "", "content": "她埋在我肩头，闷闷笑了一声。", "expression": "", "background": "night", "next": "5A-2-text-1222" },
    { "id": "5A-2-text-1222", "type": "narration", "speaker": "", "content": "那一刻我忽然觉得，所谓奇迹也许不是“天使为你停留”。", "expression": "", "background": "night", "next": "5A-2-text-1223" },
    { "id": "5A-2-text-1223", "type": "narration", "speaker": "", "content": "而是她明明失去了羽翼，却反而终于找到了落脚的地方。", "expression": "", "background": "night", "next": "5A-3" },
    { "id": "5A-3", "type": "marker", "markerTitle": "谢幕：永不落幕的茶会", "next": "5A-3-text-1225" },
    { "id": "5A-3-text-1225", "type": "narration", "speaker": "", "content": "几天之后，生活重新恢复了平稳。", "expression": "", "background": "day", "stageNote": "【场景】客厅 / 数日后 / 午后晴\n【BG】和第一幕呼应的客厅，但更有生活感\n【BGM】温暖明亮", "next": "5A-3-text-1226" },
    { "id": "5A-3-text-1226", "type": "narration", "speaker": "", "content": "不，严格来说，不是“恢复”。", "expression": "", "background": "day", "next": "5A-3-text-1227" },
    { "id": "5A-3-text-1227", "type": "narration", "speaker": "", "content": "而是进入了另一种新的稳定。", "expression": "", "background": "day", "next": "5A-3-text-1228" },
    { "id": "5A-3-text-1228", "type": "narration", "speaker": "", "content": "皖萱的光环消失了，羽翼也不见了。她不再能随手变出一点发光的羽毛，也不再会在阳台边缘站得像从高处来的人。", "expression": "", "background": "day", "next": "5A-3-text-1229" },
    { "id": "5A-3-text-1229", "type": "narration", "speaker": "", "content": "她开始真的会犯困，会赖床，会因为切洋葱被辣得眼眶发红，也会在天气变凉时比以前更早把自己裹进毛毯里。", "expression": "", "background": "day", "next": "5A-3-text-1230" },
    { "id": "5A-3-text-1230", "type": "narration", "speaker": "", "content": "可奇怪的是，这些变化并没有让她离“天使”更远。", "expression": "", "background": "day", "next": "5A-3-text-1231" },
    { "id": "5A-3-text-1231", "type": "narration", "speaker": "", "content": "反而让我更清楚地意识到，原来我喜欢的，从来就不是她身上那些超出常理的部分。", "expression": "", "background": "day", "next": "5A-3-text-1232" },
    { "id": "5A-3-text-1232", "type": "narration", "speaker": "", "content": "而是她会在喝到热汤时眼睛发亮，会把喜欢的最后一口犹豫着留给我，会认真记下“幸福原来会在门铃响起之前先变甜”。", "expression": "", "background": "day", "next": "5A-3-text-1233" },
    { "id": "5A-3-text-1233", "type": "narration", "speaker": "", "content": "午后的茶几上又摆回了熟悉的下午茶。", "expression": "", "background": "day", "next": "5A-3-text-1234" },
    { "id": "5A-3-text-1234", "type": "narration", "speaker": "", "content": "这一次是草莓蛋糕。", "expression": "", "background": "day", "next": "5A-3-text-1235" },
    { "id": "5A-3-text-1235", "type": "narration", "speaker": "", "content": "和第一天那块很像。", "expression": "", "background": "day", "next": "5A-3-text-1236" },
    { "id": "5A-3-text-1236", "type": "narration", "speaker": "", "content": "一样柔软的奶油，一样新鲜的草莓，一样被玻璃窗外落进来的阳光照得发亮。", "expression": "", "background": "day", "next": "5A-3-text-1237" },
    { "id": "5A-3-text-1237", "type": "narration", "speaker": "", "content": "只是坐在我对面的人，已经不会再因为那句“可以近距离观察吗”而小心试探。", "expression": "", "background": "day", "next": "5A-3-text-1238" },
    { "id": "5A-3-text-1238", "type": "narration", "speaker": "", "content": "她叉起一小块蛋糕，先自己吃了一口。", "expression": "", "background": "day", "next": "5A-3-text-1239" },
    { "id": "5A-3-text-1239", "type": "narration", "speaker": "", "content": "然后想了想，又把另一口递到我嘴边。", "expression": "", "background": "day", "next": "5A-3-text-1240" },
    { "id": "5A-3-text-1240", "type": "dialogue", "speaker": "皖萱", "content": "张嘴。", "expression": "", "background": "day", "next": "5A-3-text-1241" },
    { "id": "5A-3-text-1241", "type": "narration", "speaker": "", "content": "我看着她。", "expression": "", "background": "day", "next": "5A-3-text-1242" },
    { "id": "5A-3-text-1242", "type": "dialogue", "speaker": "我", "content": "这算什么？", "expression": "", "background": "day", "next": "5A-3-text-1243" },
    { "id": "5A-3-text-1243", "type": "dialogue", "speaker": "皖萱", "content": "回访调查。", "expression": "", "background": "day", "next": "5A-3-text-1244" },
    { "id": "5A-3-text-1244", "type": "narration", "speaker": "", "content": "我失笑，还是低头把那口蛋糕吃了。", "expression": "", "background": "day", "next": "5A-3-text-1245" },
    { "id": "5A-3-text-1245", "type": "narration", "speaker": "", "content": "奶油依旧柔软，草莓依旧带一点恰到好处的酸，蛋糕胚细得像一碰就会散。味道和第一天其实没什么不同。", "expression": "", "background": "day", "next": "5A-3-text-1246" },
    { "id": "5A-3-text-1246", "type": "narration", "speaker": "", "content": "可咽下去的时候，我却清楚地知道，它已经和那时完全不一样了。", "expression": "", "background": "day", "next": "5A-3-text-1247" },
    { "id": "5A-3-text-1247", "type": "narration", "speaker": "", "content": "因为现在我抬头的时候，有人就在我对面。", "expression": "", "background": "day", "next": "5A-3-text-1248" },
    { "id": "5A-3-text-1248", "type": "narration", "speaker": "", "content": "她撑着下巴看我，眼睛里有种很安稳的亮。", "expression": "", "background": "day", "next": "5A-3-text-1249" },
    { "id": "5A-3-text-1249", "type": "dialogue", "speaker": "皖萱", "content": "怎么样？", "expression": "", "background": "day", "next": "5A-3-text-1250" },
    { "id": "5A-3-text-1250", "type": "dialogue", "speaker": "我", "content": "好吃。", "expression": "", "background": "day", "next": "5A-3-text-1251" },
    { "id": "5A-3-text-1251", "type": "narration", "speaker": "", "content": "她眨了眨眼。", "expression": "", "background": "day", "next": "5A-3-text-1252" },
    { "id": "5A-3-text-1252", "type": "dialogue", "speaker": "皖萱", "content": "只是“好吃”？", "expression": "", "background": "day", "next": "5A-3-text-1253" },
    { "id": "5A-3-text-1253", "type": "narration", "speaker": "", "content": "我看着她，故意慢了两秒。", "expression": "", "background": "day", "next": "5A-3-text-1254" },
    { "id": "5A-3-text-1254", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "day", "next": "5A-3-text-1255" },
    { "id": "5A-3-text-1255", "type": "narration", "speaker": "", "content": "比第一天好吃。", "expression": "", "background": "day", "next": "5A-3-text-1256" },
    { "id": "5A-3-text-1256", "type": "narration", "speaker": "", "content": "她明显高兴了，又努力装得若无其事。", "expression": "", "background": "day", "next": "5A-3-text-1257" },
    { "id": "5A-3-text-1257", "type": "dialogue", "speaker": "皖萱", "content": "因为保存条件更好吗？", "expression": "", "background": "day", "next": "5A-3-text-1258" },
    { "id": "5A-3-text-1258", "type": "dialogue", "speaker": "我", "content": "因为这次不是一个人吃。", "expression": "", "background": "day", "next": "5A-3-text-1259" },
    { "id": "5A-3-text-1259", "type": "narration", "speaker": "", "content": "她愣了一下，耳尖很快红起来。", "expression": "", "background": "day", "next": "5A-3-text-1260" },
    { "id": "5A-3-text-1260", "type": "narration", "speaker": "", "content": "可最后还是没躲开，只小声嘟囔了一句：", "expression": "", "background": "day", "next": "5A-3-text-1261" },
    { "id": "5A-3-text-1261", "type": "dialogue", "speaker": "皖萱", "content": "那以后也不会让你一个人吃了。", "expression": "", "background": "day", "next": "5A-3-text-1262" },
    { "id": "5A-3-text-1262", "type": "narration", "speaker": "", "content": "阳光落在她发梢上，风铃在阳台边轻轻响。", "expression": "", "background": "day", "next": "5A-3-text-1263" },
    { "id": "5A-3-text-1263", "type": "narration", "speaker": "", "content": "冰箱里照例塞着很多库存，餐桌上还摆着今晚准备做的菜。窗外是再普通不过的城市，屋里是再普通不过的下午茶。", "expression": "", "background": "day", "next": "5A-3-text-1264" },
    { "id": "5A-3-text-1264", "type": "narration", "speaker": "", "content": "可我知道，所谓幸福的来源，答案大概就在这里。", "expression": "", "background": "day", "next": "5A-3-text-1265" },
    { "id": "5A-3-text-1265", "type": "narration", "speaker": "", "content": "不是某一个瞬间有多盛大。", "expression": "", "background": "day", "next": "5A-3-text-1266" },
    { "id": "5A-3-text-1266", "type": "narration", "speaker": "", "content": "而是你终于有了一个人，愿意把所有平凡的甜味，都陪你慢慢吃完。", "expression": "", "background": "day", "next": "5A-3-text-1267" },
    { "id": "5A-3-text-1267", "type": "narration", "speaker": "", "content": "后来我偶尔也会想起那一夜碎成光粉的羽翼。", "expression": "", "background": "day", "stageNote": "【HE 结尾旁白】", "next": "5A-3-text-1268" },
    { "id": "5A-3-text-1268", "type": "narration", "speaker": "", "content": "它们没有真的消失。", "expression": "", "background": "day", "next": "5A-3-text-1269" },
    { "id": "5A-3-text-1269", "type": "narration", "speaker": "", "content": "只是换了一种方式，留在了这间屋子的空气里。", "expression": "", "background": "day", "next": "5A-3-text-1270" },
    { "id": "5A-3-text-1270", "type": "narration", "speaker": "", "content": "留在每一顿热饭、每一次门铃、每一个有人等着你回家的晚上。", "expression": "", "background": "day", "next": "5A-3-text-1271" },
    { "id": "5A-3-text-1271", "type": "narration", "speaker": "", "content": "故事到这里并没有结束。", "expression": "", "background": "day", "next": "5A-3-text-1272" },
    { "id": "5A-3-text-1272", "type": "narration", "speaker": "", "content": "因为茶会还在继续。", "expression": "", "background": "day", "next": "5A-3-text-1273" },
    { "id": "5A-3-text-1273", "type": "narration", "speaker": "", "content": "而只要她还坐在我对面，这场关于陪伴、食物和人间的调查，就永远不会落幕。", "expression": "", "background": "day", "next": "ending-he" },
    { "id": "结局分支-B-飞升结局把甜味带回去的人", "type": "marker", "markerTitle": "结局分支 B：飞升结局《把甜味带回去的人》", "next": "5B-1" },
    { "id": "5B-1", "type": "marker", "markerTitle": "松开手", "next": "5B-1-text-1276" },
    { "id": "5B-1-text-1276", "type": "narration", "speaker": "", "content": "我看着她，喉咙像被什么堵住。", "expression": "", "background": "night", "stageNote": "【场景】客厅 / 夜 / 雨未停\n【BGM】克制、空旷", "next": "5B-1-text-1277" },
    { "id": "5B-1-text-1277", "type": "narration", "speaker": "", "content": "“留下来”这三个字明明已经冲到嘴边，可最后，我还是没有说出口。", "expression": "", "background": "night", "next": "5B-1-text-1278" },
    { "id": "5B-1-text-1278", "type": "narration", "speaker": "", "content": "因为我看见了她眼里的害怕。", "expression": "", "background": "night", "next": "5B-1-text-1279" },
    { "id": "5B-1-text-1279", "type": "narration", "speaker": "", "content": "也终于真正明白，她要为了这个答案付出的，不是“短暂离别”那么轻的代价。", "expression": "", "background": "night", "next": "5B-1-text-1280" },
    { "id": "5B-1-text-1280", "type": "narration", "speaker": "", "content": "我喜欢她。", "expression": "", "background": "night", "next": "5B-1-text-1281" },
    { "id": "5B-1-text-1281", "type": "narration", "speaker": "", "content": "正因为喜欢，才没办法在知道全部分量以后，还理所当然地开口要她留下。", "expression": "", "background": "night", "next": "5B-1-text-1282" },
    { "id": "5B-1-text-1282", "type": "narration", "speaker": "", "content": "我慢慢抬起手。", "expression": "", "background": "night", "next": "5B-1-text-1283" },
    { "id": "5B-1-text-1283", "type": "narration", "speaker": "", "content": "却不是去拉住她。", "expression": "", "background": "night", "next": "5B-1-text-1284" },
    { "id": "5B-1-text-1284", "type": "narration", "speaker": "", "content": "而是很轻地，替她把额前被风吹乱的碎发拨到耳后。", "expression": "", "background": "night", "next": "5B-1-text-1285" },
    { "id": "5B-1-text-1285", "type": "dialogue", "speaker": "我", "content": "回去吧。", "expression": "", "background": "night", "next": "5B-1-text-1286" },
    { "id": "5B-1-text-1286", "type": "narration", "speaker": "", "content": "她的呼吸一下子停住。", "expression": "", "background": "night", "next": "5B-1-text-1287" },
    { "id": "5B-1-text-1287", "type": "narration", "speaker": "", "content": "我笑了笑，笑意很淡，却尽量稳。", "expression": "", "background": "night", "next": "5B-1-text-1288" },
    { "id": "5B-1-text-1288", "type": "dialogue", "speaker": "我", "content": "不是因为我不想让你留。", "expression": "", "background": "night", "next": "5B-1-text-1289" },
    { "id": "5B-1-text-1289", "type": "narration", "speaker": "", "content": "恰好相反。", "expression": "", "background": "night", "next": "5B-1-text-1290" },
    { "id": "5B-1-text-1290", "type": "narration", "speaker": "", "content": "我望着她，声音很轻。", "expression": "", "background": "night", "next": "5B-1-text-1291" },
    { "id": "5B-1-text-1291", "type": "dialogue", "speaker": "我", "content": "就是因为太想了，所以才不能替你说这句话。", "expression": "", "background": "night", "next": "5B-1-text-1292" },
    { "id": "5B-1-text-1292", "type": "narration", "speaker": "", "content": "她眼眶几乎立刻红了。", "expression": "", "background": "night", "next": "5B-1-text-1293" },
    { "id": "5B-1-text-1293", "type": "dialogue", "speaker": "皖萱", "content": "可是——", "expression": "", "background": "night", "next": "5B-1-text-1294" },
    { "id": "5B-1-text-1294", "type": "narration", "speaker": "", "content": "我摇头。", "expression": "", "background": "night", "next": "5B-1-text-1295" },
    { "id": "5B-1-text-1295", "type": "dialogue", "speaker": "我", "content": "皖萱。", "expression": "", "background": "night", "next": "5B-1-text-1296" },
    { "id": "5B-1-text-1296", "type": "narration", "speaker": "", "content": "如果你留下，是因为你自己真的决定好了，那很好。", "expression": "", "background": "night", "next": "5B-1-text-1297" },
    { "id": "5B-1-text-1297", "type": "narration", "speaker": "", "content": "可如果是因为我舍不得，所以你才硬逼自己折掉羽翼……", "expression": "", "background": "night", "next": "5B-1-text-1298" },
    { "id": "5B-1-text-1298", "type": "narration", "speaker": "", "content": "我停了一下。", "expression": "", "background": "night", "next": "5B-1-text-1299" },
    { "id": "5B-1-text-1299", "type": "dialogue", "speaker": "我", "content": "那我以后每一次看着你，都会觉得自己偷走了你本来能拥有的天空。", "expression": "", "background": "night", "next": "5B-1-text-1300" },
    { "id": "5B-1-text-1300", "type": "narration", "speaker": "", "content": "她咬住唇，眼泪一下子掉下来。", "expression": "", "background": "night", "next": "5B-1-text-1301" },
    { "id": "5B-1-text-1301", "type": "dialogue", "speaker": "皖萱", "content": "你明明这样说，会让我更难走。", "expression": "", "background": "night", "next": "5B-1-text-1302" },
    { "id": "5B-1-text-1302", "type": "narration", "speaker": "", "content": "我苦笑。", "expression": "", "background": "night", "next": "5B-1-text-1303" },
    { "id": "5B-1-text-1303", "type": "dialogue", "speaker": "我", "content": "我知道。", "expression": "", "background": "night", "next": "5B-1-text-1304" },
    { "id": "5B-1-text-1304", "type": "narration", "speaker": "", "content": "我伸手替她擦掉眼泪。", "expression": "", "background": "night", "next": "5B-1-text-1305" },
    { "id": "5B-1-text-1305", "type": "dialogue", "speaker": "我", "content": "可真正喜欢一个人，大概不是把她留在身边。", "expression": "", "background": "night", "next": "5B-1-text-1306" },
    { "id": "5B-1-text-1306", "type": "narration", "speaker": "", "content": "是就算很想，也不愿意让她带着后悔留下。", "expression": "", "background": "night", "next": "5B-1-text-1307" },
    { "id": "5B-1-text-1307", "type": "narration", "speaker": "", "content": "她看着我，泪光晃得厉害，像有很多话想说，最后却都咽了回去。", "expression": "", "background": "night", "next": "5B-1-text-1308" },
    { "id": "5B-1-text-1308", "type": "narration", "speaker": "", "content": "过了很久，她才轻轻点头。", "expression": "", "background": "night", "next": "5B-1-text-1309" },
    { "id": "5B-1-text-1309", "type": "dialogue", "speaker": "皖萱", "content": "……好。", "expression": "", "background": "night", "next": "5B-1-text-1310" },
    { "id": "5B-1-text-1310", "type": "narration", "speaker": "", "content": "那一个“好”轻得像羽毛。", "expression": "", "background": "night", "next": "5B-1-text-1311" },
    { "id": "5B-1-text-1311", "type": "narration", "speaker": "", "content": "却比任何东西都重。", "expression": "", "background": "night", "next": "5B-2" },
    { "id": "5B-2", "type": "marker", "markerTitle": "归还羽翼", "next": "5B-2-text-1313" },
    { "id": "5B-2-text-1313", "type": "narration", "speaker": "", "content": "她走到阳台中央。", "expression": "", "background": "night", "stageNote": "【场景】阳台 / 夜 / 云层开裂\n【演出】羽翼重新明亮，升空前的告别\n【BGM】空灵而温柔", "next": "5B-2-text-1314" },
    { "id": "5B-2-text-1314", "type": "narration", "speaker": "", "content": "和HE里不同，这一次，她背后的羽翼不是破碎，而是缓慢地重新明亮起来。那光先从脊背深处透出，再一点一点顺着羽脉铺开，像长夜里终于被擦亮的晨星。", "expression": "", "background": "night", "next": "5B-2-text-1315" },
    { "id": "5B-2-text-1315", "type": "narration", "speaker": "", "content": "头顶那圈很淡的金色光环也重新稳定下来，像某种被确认的身份，温柔而遥远。", "expression": "", "background": "night", "next": "5B-2-text-1316" },
    { "id": "5B-2-text-1316", "type": "narration", "speaker": "", "content": "我站在原地，看着她被那片光包围。", "expression": "", "background": "night", "next": "5B-2-text-1317" },
    { "id": "5B-2-text-1317", "type": "narration", "speaker": "", "content": "明明我第一次见她时，就知道她不是属于这里的人。", "expression": "", "background": "night", "next": "5B-2-text-1318" },
    { "id": "5B-2-text-1318", "type": "narration", "speaker": "", "content": "可直到这一刻，我才真正意识到，她原来一直离天空这么近。", "expression": "", "background": "night", "next": "5B-2-text-1319" },
    { "id": "5B-2-text-1319", "type": "narration", "speaker": "", "content": "皖萱回过头看我。", "expression": "", "background": "night", "next": "5B-2-text-1320" },
    { "id": "5B-2-text-1320", "type": "narration", "speaker": "", "content": "她眼里还有泪，可神情却慢慢安静下来了。", "expression": "", "background": "night", "next": "5B-2-text-1321" },
    { "id": "5B-2-text-1321", "type": "narration", "speaker": "", "content": "那种安静不像释怀，更像终于把一块压在心上很久的石头抱稳了。", "expression": "", "background": "night", "next": "5B-2-text-1322" },
    { "id": "5B-2-text-1322", "type": "dialogue", "speaker": "皖萱", "content": "人类。", "expression": "", "background": "night", "next": "5B-2-text-1323" },
    { "id": "5B-2-text-1323", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "5B-2-text-1324" },
    { "id": "5B-2-text-1324", "type": "dialogue", "speaker": "皖萱", "content": "我以后可能会想你想到很烦。", "expression": "", "background": "night", "next": "5B-2-text-1325" },
    { "id": "5B-2-text-1325", "type": "narration", "speaker": "", "content": "我被她这句话逗得鼻子一酸，还是笑了。", "expression": "", "background": "night", "next": "5B-2-text-1326" },
    { "id": "5B-2-text-1326", "type": "dialogue", "speaker": "我", "content": "那就烦着。", "expression": "", "background": "night", "next": "5B-2-text-1327" },
    { "id": "5B-2-text-1327", "type": "narration", "speaker": "", "content": "她也笑了，眼泪却跟着掉下来。", "expression": "", "background": "night", "next": "5B-2-text-1328" },
    { "id": "5B-2-text-1328", "type": "dialogue", "speaker": "皖萱", "content": "还有这里的蛋糕、饭团、味噌汤、关东煮、奶茶、乌冬面……", "expression": "", "background": "night", "next": "5B-2-text-1329" },
    { "id": "5B-2-text-1329", "type": "dialogue", "speaker": "我", "content": "你干脆直接说你想念冰箱库存。", "expression": "", "background": "night", "next": "5B-2-text-1330" },
    { "id": "5B-2-text-1330", "type": "dialogue", "speaker": "皖萱", "content": "那个也会。", "expression": "", "background": "night", "next": "5B-2-text-1331" },
    { "id": "5B-2-text-1331", "type": "narration", "speaker": "", "content": "她低下头，像在努力把情绪压住。", "expression": "", "background": "night", "next": "5B-2-text-1332" },
    { "id": "5B-2-text-1332", "type": "narration", "speaker": "", "content": "过了片刻，才重新抬眼看我。", "expression": "", "background": "night", "next": "5B-2-text-1333" },
    { "id": "5B-2-text-1333", "type": "dialogue", "speaker": "皖萱", "content": "可是我会把这些都带回去。", "expression": "", "background": "night", "next": "5B-2-text-1334" },
    { "id": "5B-2-text-1334", "type": "narration", "speaker": "", "content": "我怔了一下。", "expression": "", "background": "night", "next": "5B-2-text-1335" },
    { "id": "5B-2-text-1335", "type": "dialogue", "speaker": "皖萱", "content": "我会把“下雨天门铃响之前就变甜的等待”、", "expression": "", "background": "night", "next": "5B-2-text-1336" },
    { "id": "5B-2-text-1336", "type": "narration", "speaker": "", "content": "把“半夜有一碗面就能让人觉得今晚可以好好结束”、", "expression": "", "background": "night", "next": "5B-2-text-1337" },
    { "id": "5B-2-text-1337", "type": "narration", "speaker": "", "content": "把“原来房子是用来装笑声的”这些事情，都带回去。", "expression": "", "background": "night", "next": "5B-2-text-1338" },
    { "id": "5B-2-text-1338", "type": "narration", "speaker": "", "content": "她看着我，眼神干净又认真。", "expression": "", "background": "night", "next": "5B-2-text-1339" },
    { "id": "5B-2-text-1339", "type": "dialogue", "speaker": "皖萱", "content": "这样的话，我写的报告就不会只是报告了。", "expression": "", "background": "night", "next": "5B-2-text-1340" },
    { "id": "5B-2-text-1340", "type": "narration", "speaker": "", "content": "我喉咙发紧，几乎说不出完整的话。", "expression": "", "background": "night", "next": "5B-2-text-1341" },
    { "id": "5B-2-text-1341", "type": "dialogue", "speaker": "我", "content": "嗯。", "expression": "", "background": "night", "next": "5B-2-text-1342" },
    { "id": "5B-2-text-1342", "type": "narration", "speaker": "", "content": "她向前一步，轻轻抱了我一下。", "expression": "", "background": "night", "next": "5B-2-text-1343" },
    { "id": "5B-2-text-1343", "type": "narration", "speaker": "", "content": "那拥抱很轻，像怕一用力就真的舍不得走了。她身上还有熟悉的、被这间屋子和一日三餐浸透的暖香，不再只是初见时那种空灵干净的味道，而是多了很多属于人间、属于我们的温度。", "expression": "", "background": "night", "next": "5B-2-text-1344" },
    { "id": "5B-2-text-1344", "type": "dialogue", "speaker": "皖萱", "content": "谢谢你。", "expression": "", "background": "night", "next": "5B-2-text-1345" },
    { "id": "5B-2-text-1345", "type": "narration", "speaker": "", "content": "我抬手回抱住她，很慢地收紧。", "expression": "", "background": "night", "next": "5B-2-text-1346" },
    { "id": "5B-2-text-1346", "type": "dialogue", "speaker": "我", "content": "谢谢你来过。", "expression": "", "background": "night", "next": "5B-2-text-1347" },
    { "id": "5B-2-text-1347", "type": "narration", "speaker": "", "content": "她埋在我肩头，很轻地吸了下鼻子。", "expression": "", "background": "night", "next": "5B-2-text-1348" },
    { "id": "5B-2-text-1348", "type": "narration", "speaker": "", "content": "然后退开。", "expression": "", "background": "night", "next": "5B-2-text-1349" },
    { "id": "5B-2-text-1349", "type": "narration", "speaker": "", "content": "下一秒，羽翼舒展开来。", "expression": "", "background": "night", "next": "5B-2-text-1350" },
    { "id": "5B-2-text-1350", "type": "narration", "speaker": "", "content": "光从她身后升起，不刺眼，却足够把整座阳台都照亮。雨不知何时停了，云层裂开一道缝，月光和羽光交在一起，像夜空也被这一刻温柔地让出一点位置。", "expression": "", "background": "night", "next": "5B-2-text-1351" },
    { "id": "5B-2-text-1351", "type": "narration", "speaker": "", "content": "她最后看了我一眼。", "expression": "", "background": "night", "next": "5B-2-text-1352" },
    { "id": "5B-2-text-1352", "type": "narration", "speaker": "", "content": "那一眼里有舍不得，有难过，也有某种被认真珍藏的温柔。", "expression": "", "background": "night", "next": "5B-2-text-1353" },
    { "id": "5B-2-text-1353", "type": "dialogue", "speaker": "皖萱", "content": "我们下一个故事见。", "expression": "", "background": "night", "next": "5B-2-text-1354" },
    { "id": "5B-2-text-1354", "type": "narration", "speaker": "", "content": "说完，她向后退了一步。", "expression": "", "background": "night", "next": "5B-2-text-1355" },
    { "id": "5B-2-text-1355", "type": "narration", "speaker": "", "content": "风忽然变大。", "expression": "", "background": "night", "next": "5B-2-text-1356" },
    { "id": "5B-2-text-1356", "type": "narration", "speaker": "", "content": "她的身影被光托起，慢慢升高。", "expression": "", "background": "night", "next": "5B-2-text-1357" },
    { "id": "5B-2-text-1357", "type": "narration", "speaker": "", "content": "白裙、长发、羽翼、那圈淡淡的金，全部一起融进夜色最干净的地方。不是骤然消失，而是一点点远去，像一颗本来就属于天空的星，终于回到了它应在的位置。", "expression": "", "background": "night", "next": "5B-2-text-1358" },
    { "id": "5B-2-text-1358", "type": "narration", "speaker": "", "content": "我站在阳台上，看着那片光越来越小，直到最后，只剩一粒几乎看不见的亮。", "expression": "", "background": "night", "next": "5B-2-text-1359" },
    { "id": "5B-2-text-1359", "type": "narration", "speaker": "", "content": "然后，彻底没入夜空。", "expression": "", "background": "night", "next": "5B-2-text-1360" },
    { "id": "5B-2-text-1360", "type": "narration", "speaker": "", "content": "手心里还残留着她刚才拥抱时的温度。", "expression": "", "background": "night", "next": "5B-2-text-1361" },
    { "id": "5B-2-text-1361", "type": "narration", "speaker": "", "content": "可眼前已经只剩风。", "expression": "", "background": "night", "next": "5B-3" },
    { "id": "5B-3", "type": "marker", "markerTitle": "留下来的房间，继续前进的人", "next": "5B-3-text-1363" },
    { "id": "5B-3-text-1363", "type": "narration", "speaker": "", "content": "她离开以后，房子确实重新安静下来。", "expression": "", "background": "day", "stageNote": "【场景】客厅 / 数周后 / 午后\n【BG】同样的客厅，安静但不空\n【BGM】温柔、带一点余韵的钢琴", "next": "5B-3-text-1364" },
    { "id": "5B-3-text-1364", "type": "narration", "speaker": "", "content": "可那种安静，已经不再和最开始一样。", "expression": "", "background": "day", "next": "5B-3-text-1365" },
    { "id": "5B-3-text-1365", "type": "narration", "speaker": "", "content": "它不再是空。", "expression": "", "background": "day", "next": "5B-3-text-1366" },
    { "id": "5B-3-text-1366", "type": "narration", "speaker": "", "content": "更像一只被认真装满过的杯子，即使水已经喝完，杯壁上也仍然留着一点甜。", "expression": "", "background": "day", "next": "5B-3-text-1367" },
    { "id": "5B-3-text-1367", "type": "narration", "speaker": "", "content": "我还是会买甜点。", "expression": "", "background": "day", "next": "5B-3-text-1368" },
    { "id": "5B-3-text-1368", "type": "narration", "speaker": "", "content": "还是会在下雨天点外卖。", "expression": "", "background": "day", "next": "5B-3-text-1369" },
    { "id": "5B-3-text-1369", "type": "narration", "speaker": "", "content": "还是会偶尔深夜给自己煮一碗面，或者去楼下便利店买一杯关东煮。", "expression": "", "background": "day", "next": "5B-3-text-1370" },
    { "id": "5B-3-text-1370", "type": "narration", "speaker": "", "content": "只是做这些事的时候，我会更慢一点。", "expression": "", "background": "day", "next": "5B-3-text-1371" },
    { "id": "5B-3-text-1371", "type": "narration", "speaker": "", "content": "因为我知道，有些味道之所以让人念念不忘，不只是因为它本身好吃。", "expression": "", "background": "day", "next": "5B-3-text-1372" },
    { "id": "5B-3-text-1372", "type": "narration", "speaker": "", "content": "还因为你曾经和谁一起，在什么样的灯光下、什么样的天气里，把它慢慢吃完。", "expression": "", "background": "day", "next": "5B-3-text-1373" },
    { "id": "5B-3-text-1373", "type": "narration", "speaker": "", "content": "客房没有立刻收拾回原样。", "expression": "", "background": "day", "next": "5B-3-text-1374" },
    { "id": "5B-3-text-1374", "type": "narration", "speaker": "", "content": "她留下的便签还贴在冰箱门上。", "expression": "", "background": "day", "next": "5B-3-text-1375" },
    { "id": "5B-3-text-1375", "type": "narration", "speaker": "", "content": "“牛奶要补。”", "expression": "", "background": "day", "next": "5B-3-text-1376" },
    { "id": "5B-3-text-1376", "type": "narration", "speaker": "", "content": "“草莓很好吃，可以再买。”", "expression": "", "background": "day", "next": "5B-3-text-1377" },
    { "id": "5B-3-text-1377", "type": "narration", "speaker": "", "content": "“不要把布丁藏在蔬菜后面，我已经发现了。”", "expression": "", "background": "day", "next": "5B-3-text-1378" },
    { "id": "5B-3-text-1378", "type": "narration", "speaker": "", "content": "我没有撕掉。", "expression": "", "background": "day", "next": "5B-3-text-1379" },
    { "id": "5B-3-text-1379", "type": "narration", "speaker": "", "content": "不是放不下。", "expression": "", "background": "day", "next": "5B-3-text-1380" },
    { "id": "5B-3-text-1380", "type": "narration", "speaker": "", "content": "而是觉得，那些字迹和那段时间一样，都已经成了这个家的一部分。", "expression": "", "background": "day", "next": "5B-3-text-1381" },
    { "id": "5B-3-text-1381", "type": "narration", "speaker": "", "content": "某天下午，我又买回了和第一天很像的草莓蛋糕。", "expression": "", "background": "day", "next": "5B-3-text-1382" },
    { "id": "5B-3-text-1382", "type": "narration", "speaker": "", "content": "切开、咬下、咽下。", "expression": "", "background": "day", "next": "5B-3-text-1383" },
    { "id": "5B-3-text-1383", "type": "narration", "speaker": "", "content": "味道还是一样。", "expression": "", "background": "day", "next": "5B-3-text-1384" },
    { "id": "5B-3-text-1384", "type": "narration", "speaker": "", "content": "柔软，微凉，甜里带一点恰到好处的酸。", "expression": "", "background": "day", "next": "5B-3-text-1385" },
    { "id": "5B-3-text-1385", "type": "narration", "speaker": "", "content": "我低头笑了笑。", "expression": "", "background": "day", "next": "5B-3-text-1386" },
    { "id": "5B-3-text-1386", "type": "dialogue", "speaker": "我", "content": "明明是这么甜的东西。", "expression": "", "background": "day", "next": "5B-3-text-1387" },
    { "id": "5B-3-text-1387", "type": "narration", "speaker": "", "content": "现在一个人吃，好像也不只是多余的热量了。", "expression": "", "background": "day", "next": "5B-3-text-1388" },
    { "id": "5B-3-text-1388", "type": "narration", "speaker": "", "content": "因为我知道，在某个很高、很远、也许还带着光的地方，也有人会因为想起同样的味道，而短暂地停下来。", "expression": "", "background": "day", "next": "5B-3-text-1389" },
    { "id": "5B-3-text-1389", "type": "narration", "speaker": "", "content": "后来我终于明白，有些相遇并不是为了永远留下。", "expression": "", "background": "day", "stageNote": "【飞升结局旁白】", "next": "5B-3-text-1390" },
    { "id": "5B-3-text-1390", "type": "dialogue", "speaker": "它们更像一颗糖在舌尖融开——", "content": "短暂，清晰，甜得让你以后再也没办法回到从前那个什么都没尝过的自己。", "expression": "", "background": "day", "next": "5B-3-text-1391" },
    { "id": "5B-3-text-1391", "type": "narration", "speaker": "", "content": "皖萱把羽翼带回了天空。", "expression": "", "background": "day", "next": "5B-3-text-1392" },
    { "id": "5B-3-text-1392", "type": "narration", "speaker": "", "content": "而我把她留下的人间，继续一天天过下去。", "expression": "", "background": "day", "next": "5B-3-text-1393" },
    { "id": "5B-3-text-1393", "type": "narration", "speaker": "", "content": "故事没有停在一起生活的结尾。", "expression": "", "background": "day", "next": "5B-3-text-1394" },
    { "id": "5B-3-text-1394", "type": "narration", "speaker": "", "content": "它只是换了一种方式，延续在每一顿饭、每一次想念，以及每一个依然愿意认真过日子的明天里。", "expression": "", "background": "day", "next": "ending-be" },
    { "id": "ending-he", "type": "end", "endingTitle": "永不落幕的茶会", "endingMessage": "皖萱留在了人间。茶会还会继续。" },
    { "id": "ending-be", "type": "end", "endingTitle": "把甜味带回去的人", "endingMessage": "皖萱带着这段甜味回到了天空。" }
  ]
}
;
